/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100316-3","meetingId":"h22-c-budget","date":"2010年3月16日","dateIso":"2010-03-16","committee":"予算特別委員会","time":"午前１０時０２分～午後５時４１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を141件整理しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計予算","agenda":"平成２２年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問・要望","question":"４目社会教育費のＰＴＡ関係費について、それから３５３ページ、４目社会教育費の図書館経費についてお伺いをいたします。それから、特別支援学級のあり方ということで、品川区の小中一貫教育における特別支援学級の考え方をお伺いしたいと思います。","respondent":"冠木指導課長","answer":"これは特別支援学級、いわゆる知的障害の固定学級に通っているお子さんに対しての介助員という形で、今まで対応してまいりました。自立の道、９年間の中で、小中が連携して取り組んでいく必要があるというような考え方から特別支援教育に取り組んでいるところです。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"非常に支援を受ける児童にとっても、生徒にとっても大切なことだと思いますので、ますます充実させていっていただきたいと考えています。それから、ちょっと教えていただきたいんですけれども、その割合というのは大体どのぐらいになるのか教えていただけますか尋ねました。","respondent":"冠木指導課長","answer":"説明が不十分でございました。特別支援学校につきましては、小学校から中学校へという中では、知的障害の特別支援学校に１人です。","id":"exchange-002"},{"speaker":"井桁委員","kind":"意見","question":"かなり高度といいますか、そこのあたりで、やはり小学校１年生と中学校３年生というのはかなり体力的にも違うところも出てくると思うんですね。そこのあたりでの格段の配慮というのが必要だと思うのですが、そこのあたりをもう１回お聞かせいただけますかとの意見を述べました。","respondent":"冠木指導課長","answer":"小学校から中学校へ、６年生から７年生に参ったときに、当然、子どもたちの体力も、それから障害の程度も変わってまいります。介助員、学習支援員というような制度を併用していただきまして、その子に合った特別支援教育を進めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"井桁委員","kind":"質問・要望","question":"次にちょっと飛びまして、３５３ページの４目社会教育費の図書館経費についてお伺いいたします。これは主に子どもと図書とのかかわりと、あとホームページ、インターネット、ウェブ関係のことでお伺いをしたいと考えています。","respondent":"小川品川図書館長","answer":"平成１７年度より、これは他の自治体に比べても、いち早く策定させていただきました。年間でもそれぞれの図書館においておはなし会やさまざまな事業を実施いたしておりまして、１年間でも１万人近くの参加者をいただいているです。","id":"exchange-004"},{"speaker":"井桁委員","kind":"質問","question":"子どもの科学館と併館だったんですけれども、そこのあたりで、子どもに特化をしたというような図書館の環境づくりというのは今後お考えでしょうか。それから、これにとっての１日のアクセスということと、子どもがウェブ上で見るときの工夫などあれば教えていただけますか尋ねました。","respondent":"小川品川図書館長","answer":"それから、特に児童図書等を手厚くしているような、例えば源氏前図書館のような図書館もありますので、そうした面で工夫をしてまいる予定です。さらに今度１０月にオープンいたします五反田図書館ですが、子育て支援に関するような資料も手厚くしていきたいと考えています。","id":"exchange-005"},{"speaker":"井桁委員","kind":"質問","question":"その中で子ども向けの検索というのを今後考えていかれるのかなというのが一つお伺いしたいところです。中学校になったら、一気に離れていってしまう傾向というのがまだまだ感じられるのですが、そこのあたりへの工夫とともにお伺いしたいと思います。","respondent":"小川品川図書館長","answer":"そのあたりにつきましては、システム上の問題もありますので、検討をぜひさせていただきたいと思います。学校図書館との連携もしていますし、そのあたりで連携をしつつ、今後検討してまいりたいと考えています。","id":"exchange-006"},{"speaker":"井桁委員","kind":"質問・要望","question":"子どもへのインターネットも普及しておりますので、ぜひ児童が検索ができるようなシステムというのを今後前向きに検討してほしいと求めました。ぜひ継続して本を読むことが楽しいんだよというようなことを図書館を通じて、また学校を通じてアピールしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"ページ数３４９ページの小中一貫教育要領印刷費、３５７ページの保幼小連携改修工事費、３６５ページのプール消毒薬品購入等の４点でお伺いします。主にこの小中一貫教育要領の改訂された内容をお示しいただきたいのと、わかりにくいイメージもあるので、具体的にご説明をお願いいたします。","respondent":"冠木指導課長","answer":"そういった、今お答えをさせていただいたような活用の部分についても、十分に先生方に指導していただけるような時間を設定したです。３年間、どちらかといえば、私どもも地方基準としての小中一貫教育要領を力強く発信してまいりたいと思ってあります。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"今のご答弁、前にもいろいろな議会の中で取り上げられた中で、この質問で国が品川区に追いついてきたというご答弁、たくさんいただきました。もうちょっと何がどういうふうに国が追いついてきたのか、品川区はこんなに先行しているというところをもう少し具体的に説明を求めました。","respondent":"冠木指導課長","answer":"それについては私どもの小中一貫教育要領では、もう既に平成１８年に出したものの段階から入れて指導をしていたわけです。今回、また国のほうも復活してきたというようなところは、各教科、随時見られるです。","id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"大半というか、ちょっとうまく表現できないですが、この品川区の小中一貫教育を非常に期待されているというところだと思うんです。まずこれから平成２２年度は印刷をして、この教員の方々へどう周知徹底をされ、その点の流れを説明を求めました。","respondent":"冠木指導課長","answer":"十分にその趣旨をお伝えするような機会を随所につくってまいりたいと思ってあります。これについてもホームページであるとか、あるいはその説明を簡単にした概要版だとか、そういうものを工夫してまいりたいと思ってあります。","id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"教員の方の指導力というところが大変に求められていくところなのかと思いますので、今、平成２２年度は継続という形になっておりますので。９月から全公立の保育園、幼稚園あるいは小学校で実施をしていくとプレス発表をされていますけれども、この内容を具体的に説明を求めました。","respondent":"冠木指導課長","answer":"この子どもたちが４月になりますと、小学校に入りますので、１学期は小学校におけるモデル実施ということを進めてまいりたいと思ってあります。保育園側のモデル実施の考察と、そんなスケジュールで、今取り組んでいるところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"３４７ページのプラン２１推進事業に関連いたしまして、小学校５年生、６年生で行われている定期テストについて伺いたいと思います。それと幾つの学校でこういう状況になっているのか、ご説明いただけますか尋ねました。","respondent":"冠木指導課長","answer":"その意味合いで、今、お話にありました、学校では８時から８時半というような設定をしていると考えます。ですので、そのクラブ活動等は特別な許可を得て、その担当の先生がその前の時間帯で対応しているというふうに考えております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"この教育改革と何か関係があるのかどうか、そこを伺いたいのと、幾つの学校がこういう状況なのかを伺いたいと思います。私自身も８時２０分でしょうか、３０分でしょうか、いかがか尋ねました。","respondent":"冠木指導課長","answer":"これは安全上の配慮という意味ですので、これは小学校、中学校においても、全校で実施しています。その活動には必ずねらいがあって、それを指導する教員がいるというのが学校ですので、そのような対応をしています。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"早く学校に来るんだったら、早く帰れるような体制も必要だと思いますけれども、この子どもの事情というのもしっかり考えてほしいと求めました。見直す考えはないんか尋ねました。","respondent":"冠木指導課長","answer":"これは先ほどもお答えしましたが、安全上の配慮ですので、まずそれが第一だと考えております。したがって朝、そういうようなことを見直す予定はございません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"小学校５年生からの定期テストについて伺いたいんですけれども、６年生で定期テスト、なぜなのかということです。中学校でよく中間、中学校で行っている指導方法を小学校５年生から行っているそのねらいや、あと小中一貫教育との関係について伺いたいと思います。","respondent":"冠木指導課長","answer":"小中一貫校３校とも実施しております。小中連携という意味合いの中で、学習効果を上げさせるというのが考査の１つのねらいかと思ってありますので、そういう意味で実施をしているです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを教えていただきたいんですけれども、先ほど伺ったのは中学校では中間・期末テストはありましたけれども、そこをご説明ほしいと求めました。それと今、説明がありましたけれども、小中一貫校３校だけ実施しているというのがよく意味がわからないので、ご説明いただけますか尋ねました。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"時期につきましては、年間５回ということで、しかるべき時期に実施をしているです。これは小中一貫教育、小中一貫校の中のカリキュラムの中で、そういう取り組みをしているです。そういう中で、一貫校の中で先行的に５、６年生もしっかりと定期考査をすることによって学力を定着させていきたいということで考えているわけです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ある意味年５回だったんでしょうか、ありましたけれども、なぜ小学校５年生から実施をしたのかと。先行したというご説明がありましたけれども、なぜ小学校５年生からやったのかというそこの説明がないので、そこをご説明ほしいと求めました。","respondent":"冠木指導課長","answer":"今、担当課長からもお答えをしたように、品川区の小中一貫教育要領、１年生から４年生まで、そして５年生から７年生までという形で進めしています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"小学校５年生から、今まで中学校でやっていた定期テストをなぜ前倒しで実施をするのか、全く意味がわかりません。１つの学級の中で学び取っていく、小学校の５年生の発達段階に応じた学習なのかと、そこを伺いたい。","respondent":"冠木指導課長","answer":"単元テストよりも一定期間まとまった勉強に子どもたちが取り組むという意味で、非常に学習意欲が上がるという効果をねらっているところです。私どもの実施をしております各種の調査においても、これは５年生にとって、発達段階に応じた指導であると思ってあります。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"答えが合っていればよいという学習では、私は勉強嫌いを招いてしまうと思うんですけれども、どういう研究を行って、そうおっしゃるのか伺いたい。小学校の１年生、６年生、ご説明ください。","respondent":"冠木指導課長","answer":"この取り組みが、早いお子さんですと、４年生の後半から６年生の前半までに始まります。そういうようなところで、５年生という時期は物事を振り返って、集中して取り組むにふさわしい時期と考えているところです。","id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"３５１ページ、それと３４９ページ、経済活動体験学習経費についてお伺いします。ファイナンス・パークが今回載っていないんですが、これは今後どうしていくのか、その展開を説明を求めました。","respondent":"和氣小中一貫教育担当課長、冠木指導課長","answer":"このため、今年度は実施ができないということになります。来年度、品川地区に一貫校ができた段階で、今まで未実習だった子どもたちも含めて、２年分をまとめてやろうと計画をしているところであります。教員を招致いたしまして、中学校の英語の授業で教えていただいたり、交流をしたりというような交流をさせていただいているです。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"これは要望で終わります。来年まとめて２年分やるということなので、予算書の中でも好きな１つですから、ぜひ進めていってほしいと求めました。","respondent":"冠木指導課長","answer":"教員交流の規模につきましては、ポートランド市のほうが６人前後、それからオークランド市のほうが２人ということで、毎年やらせていただいております。","id":"exchange-021"},{"speaker":"石田委員","kind":"質問","question":"このオークランド市の教員の方が２人、ポートランド市が６人となっていますが、例えば１カ月か何週間かという期間だと思うんですが、例えば１年間通しての英語の教育がある中での部分でやられていると思うんですが、どういった指導を行っているのか、説明を求めました。","respondent":"冠木指導課長","answer":"ポートランド市にしても、オークランド市にしましても、中学校のほうの教育課程に位置づけていただきまして、お見えになった先生をそれぞれの学校に配置しまして、約１カ月交流および授業の指導をしていただいているです。","id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"９月開校ということですけど、予定どおり進んでおられるかどうか、順調ですかということです。一貫校についてもう１点が、これはちょっと出るかどうかわかりませんけれども、。","respondent":"和氣小中一貫教育担当課長、富田学務課長、田村庶務課長","answer":"これは基本的に教員に周知をするということと、あと、これについて、これ以降、欲しい方にどう頒布していくかも考えてまいりたいと考えております。… 私からは日光林間学園運営費についてのお尋ねです。１億２,０００万円、平成２２年度につきましては、それらの工事経費が入っているです。 耐震補強工事で１校ということで、１校だけ２カ年にわたった鈴ヶ森小学校がありますが、前年度と比較して大きな減の理由じゃないかと考えております。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"１点だけ、質問的には大体理解したつもりでいるんですけれども、この区役所のほうに来るというのが、学校別に来ているというのはわかるんですけど、日本全国から視察に来ているというような形、その辺をもうちょっとわかれば説明を求めました。","respondent":"和氣小中一貫教育担当課長","answer":"区役所にももちろんお見えになっていますが、直接一貫校を見たいということがございまして、私のほうが一貫校のほうで対応させていただいているです。","id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"父母目線でお聞きしてしまいますけれども、これは小学校から中学校へ行くとき、具体的にはこれは連携校に行かなくちゃいけないんでしょうか。どうか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"選択制を敷いておりますので、連携校に必ずしも行かなくてはいけないということではございませんが、各連携グループの中では、それぞれがしっかり連携して、連携の学校に来てもらいたいということで努力をしています。","id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"小中一貫教育連携４校ニュースという形で、連携教育４校と、小学校が３校の中学校が１校と。その辺のところがあるものですから、どんなお考えなのか、ちょっとお教えいただけると助かります。","respondent":"和氣小中一貫教育担当課長","answer":"今のお話ですが、ぜひ自分の連携した学校に来てほしいというのは当然のことですし、そういう形で皆様に呼びかけたいと思っていると思います。連携校に行っても、そういう連携グループの中で、それはまた徹底してまいりたいとは思います。","id":"exchange-026"},{"speaker":"原委員","kind":"質問・要望","question":"これで要望ということになってしまうと、そのままで終わってしまうものですから、出されているものも非常にいいんですね。ですから、あくまでも教育の品川区ですから、その辺のところをお答えほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"今の委員の指摘を受けまして、学校のほうにも熱意はわかりますけれども、基本的に学校選択制というのは堅持したままで、品川のすべての学校がより高い質の教育を提供できるというふうに改善していくことだと、もう１回徹底してまいりたいと思いますので、よろしくお願いします。","id":"exchange-027"},{"speaker":"高橋委員","kind":"意見","question":"３５１ページ、それから３５７ページ、学校環境整備事業の中の保幼小連携にかかわる部分です。中学校にいらっしゃる方が、副校長先生になるための試験を受けた数と、合格された先生の数をお願いしますとの意見を述べました。","respondent":"冠木指導課長","answer":"Ａ選考のほうの倍率は１.３３倍、Ｂ選考のほうは１.２６倍です。Ａ選考が３人、Ｂ選考が１４人でございまして、１７人中１３人が合格されているという状況があります。","id":"exchange-028"},{"speaker":"高橋委員","kind":"意見","question":"東京都全体でも１.３３倍と１.２６倍という形の倍率で、この数年の傾向と、この数字をごらんになってのお考えをお願いしますとの意見を述べました。","respondent":"冠木指導課長","answer":"受験者の数が減っていたり、倍率が１倍台だというような状況があります。３０代後半から４０代が少ないという状況がございまして、東京都のほうにいろいろと意見を言ってまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"高橋委員","kind":"質問","question":"立派な方がいらっしゃいますので、皆さんが目指していただけるといいんですが、その一方で忙し過ぎるというところがあると思うんですね。事務作業があれば雑用もあり、地域との関係もありという、そういった非常に忙しい状況についてどうお考えか尋ねました。","respondent":"冠木指導課長","answer":"今、副校長、どういうふうに分担していったらいいんだろうかというような検討委員会を持ちまして議論を進めているところです。検討結果を受けまして、それからあと、十分に成果の上がるものを一生懸命やっていくというような学校づくりを進めてまいりたいと思ってあります。","id":"exchange-030"},{"speaker":"高橋委員","kind":"質問","question":"これは１つお聞きしますが、副校長先生が忙しいということに関する調査をすると聞いておりますが、それとまた別にやられることなんでしょうか。そういった２人体制というんでしょうか、それ以外の教員に対する指導というのでしょうか、そういう点も含めてお考えをお願いします。","respondent":"冠木指導課長","answer":"１点目の事務内容の検討についてはですが、それも踏まえつつ、品川区は品川区としての考え方を打ち出してまいりたいと思ってあります。副校長の２人制、あるいは２人目に行政系の職員をというようなお話でございましたが、今後研究をしてまいりたいと思ってあります。","id":"exchange-031"},{"speaker":"高橋委員","kind":"意見","question":"全体として、学校全体の教員の方々が仕事をされることが、最終的に生徒・児童の教育につながるので、よろしくお願いします。特別支援学級の編成が進んでいると思うんですが、来年度、区立の特別支援学級が１学級から２学級などに増える学校があればお教えくださいとの意見を述べました。","respondent":"冠木指導課長","answer":"来年度、学級数が増える中学校の特別支援学級ですけれども、伊藤学園が１学級から２学級に増える予定です。それから八潮学園ですが、１学級から２学級に増える予定です。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"今までよりも生徒の数が増えるわけですが、予想されるいろいろな変化と、それに対して区としてはどのような対応をする形になっているんでしょうか。それから、この中学生が例えばすまいるスクールに、小学校ですけれども、一緒に行きたいというのがあったときはどうか尋ねました。","respondent":"冠木指導課長、田村庶務課長","answer":"この特別支援学級の学級というのは、９人になれば１学級増えるですので、より充実した環境で教育を受けられるという状況になってくるのかなと思ってあります。 ポイントで交流を深める機会とはなりますが、すまいるスクール自体に中学生が来て、そこで過ごすという形は今のところ考えてはございません。","id":"exchange-033"},{"speaker":"高橋委員","kind":"質問","question":"対応をお願いしたいのですが、それで現在、特別支援教育担当の職員の方は係長だと思うんですね。そういったお仕事等々考えると、そういった立場のほうが円滑に進むのではないかと思うのですが、いかがか尋ねました。","respondent":"冠木指導課長","answer":"組織の話ですので、ご意見をいただいたということで、それと、成人の障害のある方とのやりとり、あるいは交流というような部分につきましては、障害者福祉課と連携をして取り組んでまいりたいと思ってあります。","id":"exchange-034"},{"speaker":"高橋委員","kind":"質問・要望","question":"これは要望といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうは、そしてその次のページの３５１ページの適応指導教室運営費、マイスクール八潮のことについてお伺いしたいと思います。もう１点、これは１年間通してやるのかどうかも教えてほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"なぜそうするのかについての根拠を説明したりして、鈴ヶ森中学校、上神明小学校で実施をしたところです。来年度、平成２２年度以降については、今募集をかけているところでございまして、手を挙げてきた学校に対して保証してまいりたいと考えております。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"１回ですか。ずっと通して、この礼儀作法を教えていただけるのかなと思いましたが、そうしますと、その後、先生が教えていくという形になりますか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"これを使って、これを契機にして教員が何度も何度も繰り返して、こういう機会を与えていく。そういうものを活用しながら、基本的には私ども市民科というところでこれをしっかりやっておりますので、あくまでも市民科が基本です。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問","question":"バスケットボールでもいいしということ。それはその学校にお任せするということか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"実際にこれをやりますと、一度、これで何度も何度も大きい声であいさつをしますと、子どもたちは大変慣れてきます。道で歩いても、これを１つの契機にしながら、系統的に教員が時折々にしっかりと指導していくという形になってあります。","id":"exchange-038"},{"speaker":"山元委員","kind":"質問","question":"その次のところの特色ある教育活動経費につきましてお伺いしたいと思います。具体的にこの特色ある教育活動経費というのは具体的にどのような内容なのか、教えていただけますか尋ねました。","respondent":"富田学務課長","answer":"それを審査し、また状況によっては校長とのヒアリングを設定するなどして、購入するものを決定していくです。各学校から出されておりますさまざまな学力テストの実施経費、体育用の教材、また生活習慣調査等々の経費等々といったものが含まれているものです。","id":"exchange-039"},{"speaker":"山元委員","kind":"意見","question":"そうしますと、その学校みずから、いろいろお考えをして、それを教育委員会のほうでオーケーが出れば、それができるということになりますかとの意見を述べました。","respondent":"富田学務課長","answer":"学校から出された要望を教育委員会として内々の審査といいますか、ヒアリングを含めて審査を行った上で予算要求に上げ、予算査定がされたものについて、こういう形で計上しているものです。","id":"exchange-040"},{"speaker":"山元委員","kind":"質問","question":"ここのところに、学校別パンフレット作成というふうに書いてあります。そしてお子さんは２４％近いということは、何かマニュアル的なものというのがあるのかどうか、教えていただけますか。","respondent":"富田学務課長","answer":"こちらにつきましては、教育委員会のほうでマニュアルを示したということはございません。従前、学校によりましてはＰＴＡの活動のＰＲ欄、学校の特色活動の中に盛り込んでＰＲしている学校が多いようです。","id":"exchange-041"},{"speaker":"山元委員","kind":"質問","question":"しつこいようですが、このパンフレット、これだけはやっちゃいけないという、何かルールというのはあるんですか。それとも本当に自由につくっていいんか尋ねました。","respondent":"富田学務課長","answer":"教育委員会として、これはやらないようにということは言っていることはございませんが、もし注意するとすれば、例えば個人情報ですとか、そういった扱いに注意していただいてということのみになろうかと思います。","id":"exchange-042"},{"speaker":"山元委員","kind":"質問・要望","question":"では、次のページの３５１ページの適応指導教室運営費、マイスクール八潮についてお伺いさせてほしいと求めました。こちらの教育相談員等雇用費ということで、１１人と書いてありますが、この１１人はどういう方なのか、教えていただけますか尋ねました。","respondent":"冠木指導課長","answer":"この１１人につきましては、１人が心理系の相談員、あとは教員を目指して教員免許を持っているような方で、マイスクールの対応に当たっていただいている教員系の方です。","id":"exchange-043"},{"speaker":"山元委員","kind":"質問","question":"なかなか学校、不登校の方が多い中で、マイスクールのほうには毎日というか、来ていらっしゃるのかどうか、またせっかく来ているのに来れなくなった場合の対応ですか、それはどのようになさっているか、教えていただけますか。","respondent":"冠木指導課長","answer":"個々によってかなり差がありますので、対応しています。","id":"exchange-044"},{"speaker":"藤原委員","kind":"質問","question":"学校の交通安全についてお伺いしますが、１年生が通うようになりますが、どのような指導をしていくかということをお伺いします。それと３５３ページの図書館経費についてお伺いしますが、あと地区の図書館の関係とか、あと学校の図書館との関係についてお伺いします。","respondent":"冠木指導課長、小川品川図書館長","answer":"必ず４月当初に、横断歩道の渡り方であるとか、道路の歩き方を実際に体験をしながら学ぶ学習を行って、登下校の安全確保に努めているところです。昨今は保護者に対して、加害者にならないための指導など… ビジネス支援図書館ですが、今後、それらについて特にビジネス支援図書館以外の特化した図書館を展開するという予定は今のところございません。","id":"exchange-045"},{"speaker":"藤原委員","kind":"質問","question":"４警察署の学校の交通安全指導の授業に関して、区長部局ですけれども、交通安全担当課長がどういうふうにかかわっているかを教えてください。ＤＶＤに関しても、それはいわゆる民間のそういうお店がやっていけばいいと思っているんですけれども、その辺についてはどうか尋ねました。","respondent":"諸石交通安全担当課長、小川品川図書館長","answer":"５人が円卓に座った状態で協議ができるという雰囲気ができておりまして、そういう関係で話ができるということで、スムーズに進んだです。委員の方のいろいろなお話を持って帰りたいと、警視庁で生かしていきたいと考えています。ただ、ご利用者の方によっては、当然、週刊誌等も必要だという熱い要望もありますので、そうしたお声にもお答えしなければならないと考えております。","id":"exchange-046"},{"speaker":"藤原委員","kind":"質問","question":"図書館ですけれども、武蔵小山の商業支援施設で、図書の取り次ぎをするということですが、これ、品川区全体ではどういうふうにこれから考えていくのか尋ねました。","respondent":"小川品川図書館長","answer":"武蔵小山での図書サービスの開始に当たりましては、そこの場所にある本を借りるとは限らなくなってきたというような経過がございました。武蔵小山がたまたま１０館の図書館に少しだけ遠い場所にあるということも兼ね合わせまして、それ以外の場所については、まだ全くの未定です。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、また警視庁に帰ってもそれを役立てたいという思いが何かありましたら、ご答弁お願いいたします。","respondent":"諸石交通安全担当課長","answer":"確かにまだはっきりした内示をいただいておりませんので、戻るかどうかわかりませんが、一応戻るという予定でおります。帰ったら頑張ります。","id":"exchange-048"},{"speaker":"山内委員","kind":"質問・要望","question":"プラン２１推進事業のことで伺いますけれども、先日配付をしていただきました事務事業の点検および評価報告書を読ませていただきました。というのは、やはり主導をする立場だからだと思うんですけれども、その辺についての対応をどのように行っているかをまず伺います。","respondent":"冠木指導課長","answer":"方針等があった場合に、あるいはチームティーチングをとっていくとか、そういうような形態の違いが出てくるのかなと思ってあります。校長先生が変わられても、しっかりと引き継いでいっていただきたいという考えで、私どもも学校を支援しています。","id":"exchange-049"},{"speaker":"山内委員","kind":"質問・要望","question":"やはり今、そういういろいろな話を伺いまして、地域に根づいた教育というものが非常に今大事になってきているのかなと。地域に根づいた教育と、それから品川区の独自採用の教員というものの関連した考えというものを改めてお伺いさせてほしいと求めました。","respondent":"冠木指導課長","answer":"ぜひ品川区に根ざした教員が少しでも多く、品川区の子どもたちに力を発揮していただけるように、引き続き努力してまいりたいと思ってあります。東京都の任用のあり方が若干違いますので、すぐにはというふうにはいきませんけれども、参考にさせていただきたいと思ってあります。","id":"exchange-050"},{"speaker":"稲川委員","kind":"質問","question":"３４９ページ、毎回質問させていただいているんですが、３６９ページの学校改築推進経費の第一日野小学校の学校芝生化についてちょっとお伺いします。３４９ページなんですが、毎回質問させていただいているんですが、また改めてお伺いをいたします。","respondent":"冠木指導課長","answer":"それから、和楽器につきましては、小学校、中学校とも全校で実施をしています。琴以外にも取り組んでいる学校がありますし、また民謡ではございませんけれども、長唄等の学習をしている学校も把握しています。","id":"exchange-051"},{"speaker":"稲川委員","kind":"質問","question":"地域においてやはり民謡をやられている方とかも多いので、そういったボランティアの方を活用するという考えがあるかどうか、教えてください。これは一般質問でもお伺いしたんですが、地域の方の活用を望まれるところだと思うんですが、その辺はいかがか尋ねました。","respondent":"冠木指導課長","answer":"現在は、楽器店を通して講師の方をお願いしていますけれども、地域の方であるとか、民謡協会の方であるとか、そういうような地域の人材についても、今後積極的に活用できるようにしてまいりたいと思ってあります。","id":"exchange-052"},{"speaker":"稲川委員","kind":"質問・要望","question":"学校改築費の芝生化についてなんですが、今日の庁内放送ですか、第一日野小学校の校庭芝生化がモデル校ということで、放送がかかっておりました。校庭の芝生化というのは、いろいろ聞くと多くの問題があると、それはお伺いをしています。","respondent":"田村庶務課長","answer":"これまでもお答えしているように、校庭の芝生化の利点と申しますと、やはり芝生が体に優しい。公園の所管の部署と連携しながら、やはりモデル実施で、モデル実施の検証に努めてまいりたいと考えています。","id":"exchange-053"},{"speaker":"稲川委員","kind":"質問・要望","question":"校地借地料、これはちょっと軽く聞きたいと思いますが、まず９校から７校に減った理由というのは、何か一貫校の関係で減ったのかどうなのか。この７校の地域別というのですか、。","respondent":"田村庶務課長","answer":"小学校７校です。１つは城南小学校のお寺からお借りしている分を買い取りましたので、あともう１つは、その２校の減です。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この健康管理に全力で取り組んでいく必要があると思うんですけれども、何点かちょっと伺いたいと思います。この２人の先生の勤務がどんな状況だったのか、残業時間なんかもどうだったのか、ちょっとかいつまんで説明ほしいと求めました。","respondent":"田村庶務課長、冠木指導課長","answer":"もう１人については、この方も健康診断は受けていました。あるいは要治療というような指示は出ていない方で、両者とも、まだ検死の結果が出ていないという状況です。 お二人の先生の死については、重く受けとめているところです。お二人の勤務状況につきましては、荏原第三中学校、それから日野学園とも、通常の勤務の範囲内ということで把握しています。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"品川区はどうなのかということで、ちょっと伺いたいんですけれども、直近でどういう状況になっているのかというところを伺いたいと思います。たしか無いということなので、即退職ということになってしまうのかと思うんですけれども、そこら辺の状況も伺いたいと思います。","respondent":"冠木指導課長","answer":"直近の病気休暇、休職の実数です。平成２１年度におきましては、病気休職が１４人、それから病気休暇は１９人となっています。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"あとそのうちのいわゆるメンタルはどんな状況なのかということを改めて伺いたいと思います。時には、そこら辺の状況もどういうふうにつかんでいるか、伺いたいと思います。","respondent":"冠木指導課長","answer":"私ども、品川区で平成２０年度から学校安全衛生推進会議というのを持ってございまして、勤務の状況などについての検証等を行っているところです。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"労働安全衛生推進委員会ですか、指導課長の説明がありましたけれども、やっぱり子どもたちのためということで一生懸命になるんだと。この今の労働安全衛生推進委員会でしょうか、どういう実態調査、あるいは指導なりされているのかということを伺いたいと思います。","respondent":"田村庶務課長","answer":"学校の安全衛生組織についてご説明しますが、まず１つが、労働安全衛生法に基づく大本のところが、学校安全衛生推進会議というのがあります。事務２人、事務というのは県費の事務２人ということで、調査・検討をしているという内容です。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"それともう１つ、ちょっと伺いたいのは、教職員の健康管理ということで指摘がありました。ここのところがちょっと抜けているんじゃないかと感じたんですけれども、どうなんか尋ねました。","respondent":"冠木指導課長","answer":"１つ目の基準といいますか、考え方というところについてお答えしたいと思いますけれども、十分に対応してまいりたいと考えております。それから疲労の蓄積度であるとかというようなところは十分に私どもも踏まえて対応してまいりたいと考えておりまして、今回。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"意見","question":"そういうのをなくすということは、今、行政のほうの一番大事なところじゃないかと思います。今、全体を取り組むということと、やっぱり制度をもうちょっとはっきりさせていくということが必要じゃないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"渡辺委員","kind":"確認","question":"３４５ページ、スクールカウンセラーの項目、３４７ページ教育相談について、３４９ページ、学校評価実施経費の３点で伺ってまいります。確認なんですが、この辺の実施経費は一緒であるかどうか、その性格を説明を求めました。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"それから問題行動についての相談が１,９８８件、１２％となっています。それから２番目がお子さん本人からの相談が４,０００件程度… 私からは学校評価実施経費に関してお答えいたします。この内訳ですが、学校ごとにある校区外部評価の経費が６０９万４,０００円… カウンセラー自体のスーパーバイズ等々も必要になってまいりますので、強みを出し合いながら、区としての教育相談体制を組んでいるです。","id":"exchange-061"},{"speaker":"渡辺委員","kind":"質問","question":"お子さんが先生に相談を乗った形と、あと先生ご自身のケースと、この辺は把握できるものなんでしょうか。専門家ゆえに、そういうふうに必要性だとか、仕組みの中であるのかどうか説明を求めました。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"これまでもそれで実績を上げてきたということもありますので、教員の相談にも乗っていけるように充実してまいりたいと考えているところです。計画的に１週間に一度、あるいは２週間に一度という形で助言ができるように… そういう意味で、この専門外部評価を実施することによりまして、また改めて違う専門的な観点からご指摘いただくということが実現できております。","id":"exchange-062"},{"speaker":"渡辺委員","kind":"意見","question":"１点だけ。この立場の性格をもっとやりやすい環境というのは、当然研究されていると思いますが、しっかり私たちも見守っていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"若林委員","kind":"質問・要望","question":"これは来年度からＰＴＡの活動から外れるという意味のこの予算書の見方でよろしいんでしょうか。１つ、何台分というんでしょうか、お聞かせほしいと求めました。","respondent":"田村庶務課長、富田学務課長","answer":"考え方はＰＴＡ活動とは別ということで、８３運動のステッカーだとか、リーフレットというような関係を予算計上しているものです。車いす対応車の駐車場の確保をしているということで、特段… 一般への周知等々の強化に努めていくのか、そういったことも含めて区長部局とよくよく連携をとり、検討してまいりたいと思っています。","id":"exchange-064"},{"speaker":"若林委員","kind":"質問・要望","question":"学校のほうとしても、環境教育の一環として、またこういう問題にも積極的に取り組んでいただきたいということで要望します。こういう委員会以外でのお話を伺ったことがありますけれども、委員会の答弁がどうこうという意味ではなくて、そういう熱意を感じております。","respondent":"田村庶務課長、和氣小中一貫教育担当課長","answer":"８３運動の関係ですが、先ほどちょっと説明が不十分だったかもしれないです。ですから、新たに保護者となる方も含めて、区全域で８３運動と活動を引き続き推進していきたいと考えております。 コミュニケーション能力については、特に市民科で私どもは大変力を入れております。そういうためには基本的なスキルも含めまして、しっかりと私どもが学校教育を通じて子どもたちに育んでまいりたいと考えています。","id":"exchange-065"},{"speaker":"市川委員","kind":"質問・要望","question":"もう１点は、都が始めるということなんですけれども、これについて品川区では取り組みのお考えがあるのか伺います。趣旨を理解して受けてほしいといったことが書かれていたというところで、品川区としてはどういう位置づけにしているのかということを伺いたい。","respondent":"田村庶務課長、冠木指導課長、富田学務課長、金子企画財政課長、久保田行財政改革担当課長","answer":"これに類するものも、過去２年前にもやっていましたが、引き続きそれを実施していこうという内容です。場合によっては担任教諭と連携を密にして… ２つ目の運営の状況ですけれども、それから特別支援学級の担任会等で、学習支援員の派遣等についての共通理解を図ってまいったところでございまして… こちらについてはこれから研究してまいりたいと考えていますが、品川カブであるとか、あるいは東京産の豚肉であるとか。","id":"exchange-066"},{"speaker":"市川委員","kind":"質問・要望","question":"保護者にとっては、運営の体制を保護者のほうにしっかり伝えていただきたいということを要望としてお願いをしておきます。３月下旬になっても通知が届かないというような場合もあるというようなことも聞いたことがあるんですけれども、そこの辺を伺いたいと思います。","respondent":"冠木指導課長、富田学務課長","answer":"一番最後の、特別支援関係で就学相談をお受けになって今現在というお話ですけれども、今年は９４件の相談を受けて対応しているところでございまして。２件というところで、今、全力を挙げて４月に向けて準備をしています。 就学時健診の受診の有無等々、内容についても教育委員会で把握すべきではないかとのご意見ですけれども、ご意見として受けとめさせていただきたいと思います。","id":"exchange-067"},{"speaker":"市川委員","kind":"質問","question":"普通学級でみんなと学びたい子どももいるという、こういう状況の中で、選択の自由を保障する教育委員会であってほしいなというふうに思っています。このことについてはいかがか尋ねました。","respondent":"冠木指導課長","answer":"判断に向けて事務作業を進めていくという状況ですけれども、その中で、保護者あるいは中学生ですと子どもの意見ということも入ってくる。慌てて就学先を決めて、その後トラブルが起こるよりは、十分な相談の上で決定をしていくのが望ましいかと思って対応しています。","id":"exchange-068"},{"speaker":"市川委員","kind":"質問・要望","question":"その決定というところが重大なんだ、大切なんだというところにぜひ立ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"阿部委員","kind":"質問","question":"３７１ページの御殿山小学校改築基本計画、多分３４４ページの教育指導費のところに多くかかってくると思います、お伺いしたいと思います。学校に張り付けるという考え方を、そろそろ模索すべきではないかと考えておりますが、いかがか尋ねました。","respondent":"冠木指導課長、田村庶務課長","answer":"学習支援員と介助員の配置につきましては、緊急時の対応ですとか、それから行事に参加される場面での対応なども含めまして予算計上させていただいて。通常学級におきましては、基本はお子さんへの配置ということで… 保幼小連携改修工事費ですが、これは２校というのは台場小学校、第一日野小学校の待機児対策のハード部分の経費です。","id":"exchange-070"},{"speaker":"阿部委員","kind":"質問","question":"ハードの面では１点、すまいるスクールは普通教室２教室、それを教えてください。そういった不安、学校や教職員は、保育士や保育園の園児たちをどのような形で受け入れていくのかということを説明を求めました。","respondent":"冠木指導課長、田村庶務課長","answer":"通常学校における学習支援員あるいは介助員ということで、お子さんの状況によってもかなり変わってくるのかなということは思っております。その辺のところも考えまして… 学校の施設を待機児対策に使うということで、その辺は学校運営に支障が出たら問題ですから、それはないような対応が図られるということです。","id":"exchange-071"},{"speaker":"阿部委員","kind":"質問・要望","question":"次に日光林間学園なんですけれども、これは確認なんですけれども、区外の団体というのは使う可能性というのはあるのでしょうか。それから、これは何を検討していくのかということと、その基本計画を本年度やった後の今後の日程について説明を求めました。","respondent":"富田学務課長、田村庶務課長","answer":"日光林間学園は区民以外の方もご利用いただけます。使用料が１.５倍です。まず基本設計を１年、それと実施設計を１年、本体工事を２年という経過をたどって改築に至っています。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問・要望","question":"あそこはぜひ上の民地との関係についてもきちんとやっていただきたいということと、芝生化についての可能性も検討できないかと思っているんです。この点だけ答弁ください。","respondent":"田村庶務課長","answer":"その検証のほうをして考えないと、まだ時間もありますので、その様子を見て考えていきたいというふうに思います。","id":"exchange-073"},{"speaker":"阿部委員","kind":"質問","question":"小中に分けて人数、それから出現率、そして多い学年について教えてください。それから、合わせて、対応としての学校と教育委員会の役割分担、そしてスクールカウンセラーの活用についても説明を求めました。","respondent":"冠木指導課長","answer":"そして７年生、８年生になったときに、そういうようなところで学校に対して支援をしています。平成２２年度からは、あるいは巡回相談の回数も増やすような拡充を進める中で、不登校対策にも当たってまいりたいというふうに思っているところです。","id":"exchange-074"},{"speaker":"阿部委員","kind":"質問・要望","question":"ピークはピークであっても、割とわかりやすいと思うんですけれども、その辺の数字というのはとっていらっしゃいますでしょうか。この時期は週２回来てもらおうとか、そういったフレキシブルな活用というのもぜひしていただきたいんですけれども、いかがか尋ねました。","respondent":"冠木指導課長","answer":"平成２１年と数値を追ってまいりますと、第２位のけたで見ていきますと、そういう現状もあります。これについては教育相談センターのほうにも心理職がおりますので、より充実した相談体制を組んでまいりたい、このように思ってあります。","id":"exchange-075"},{"speaker":"阿部委員","kind":"質問","question":"例えば予防に関するロールプレイングですとか、あるいは区内の身近な失敗事例と言ったらいいんでしょうか。もしそういうことを既にやっていらっしゃるというのなら、それでもいいんですけれども、内容について説明を求めました。","respondent":"冠木指導課長","answer":"それを今一つ一つチェックリストのようなものにしまして、学校に配付し、活用していただいているところです。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"まず最初に２点目なんですが、最近話を伺うに、お母さん方が保護者会に出る。やはりお子さんが２人いて重なる部分があるので、そこのところの対応方をどういうふうにされているのかということを一つ伺いたい。","respondent":"冠木指導課長、富田学務課長","answer":"初めの保護者会の日程等の調整ですけれども、これは学校行事ということで校長が判断していくものでございまして、私どもとしては、近隣の小中学校の日程等をよく協議して決定をいただけるよう指導しています。 は見た目がとてもきれいだといったことですとか、あと、リサイクルが可能な製品であるということでの評価をいただいております。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問・要望","question":"社会科の教科書についてお伺いをしたいと思います。これはこの場でやっていいいのか、それとも個別にお伺いしたほうがいいのか迷いましたけれども、この場で聞かせてほしいと求めました。","respondent":"冠木指導課長","answer":"その上で品川区が今実施しています小中一貫教育を進めていく上でふさわしい教科書なのかどうか、あるいは地域の教材が入っている教科書なのか。その歴史的事実を解釈したり学習していく上で必要な人物というふうに、各教科書会社が判断していると思われるというふうに思います。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"では例えで言います、いいですか。混乱を来しちゃうと思うんですけれども、そこのところはどういうふうに仕分けをされているのか、教えてほしいと求めました。","respondent":"冠木指導課長","answer":"それぞれの教科書がいろいろな工夫をしていると思うんですけれども、それについて教科書の検定を通すという段階で、いろいろな検定の基準があります。合格した教科書ということでの理解ですので、現場では教員が混乱のないように指導をしています。","id":"exchange-079"},{"speaker":"大沢委員","kind":"質問・要望","question":"迷う意識のある子が何割いるかはわかりませんけれども。わかりやすいような形でご指導をいただきたいんですけれども、再度、お話を聞かせていただきたいんですが。","respondent":"冠木指導課長","answer":"入試につきましては私どもはちょっとわかるところではないんですけれども、学校の教育の中では混乱のないよう教員が指導するように、私どももお話を進めていきたいというふうに思います。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成２３年、平成２４年と、平成２３年から小学校でしょうか、平成２４年から中学ということで、新学習指導要領の中でということで、あります。どのように説明をされて、どのように子どもたちに教えていくのか、ビジョンがありましたら教えてほしいと求めました。","respondent":"冠木指導課長","answer":"学校の教育、教科の中身については、学習指導要領に基づいて指導してまいります。","id":"exchange-081"},{"speaker":"山路委員","kind":"質問・要望","question":"４点目が３５３ページ、図書館経費の中から資料充実費についてお伺いします。これについてご説明をいただきたいことと、どのようなかかわりがあるか、お伺いいたします。","respondent":"富田学務課長、冠木指導課長","answer":"人数について増やすということではございませんで、実質的な２名というところは変わらないものです。就学に当たりましての相談員ですので、中学への小学校からの進学相談等々につきましても… これは中学校９年生が高校進学あるいは専門学校等々の進路を実現をしていくために、進路説明会を各学校が実施をしたりしております。","id":"exchange-082"},{"speaker":"山路委員","kind":"質問・要望","question":"ここで私が質問したいことは、非常に就職難の時代に入ってきました。そういうときに、どのように指導されるか、そこについて現場から上がっているお話があったら聞かせてほしいと求めました。","respondent":"冠木指導課長","answer":"それぞれのお子さんがどういうふうに自己実現をしてやがて社会に出ていくかという、そういった進路の学習も重要であるというふうに思ってあります。ただ、将来を見据えてどんな仕事をしたいのか、どんな勉強をしたいのかというようなことも含めて各学校は指導をしています。","id":"exchange-083"},{"speaker":"山路委員","kind":"質問・要望","question":"もうご存じですよね。これについて、品川区は、特に何か特色があるものをやっていらっしゃったらお聞かせほしいと求めました。","respondent":"冠木指導課長","answer":"いろいろなところで進められているということは聞いておりまして、私どももアンテナを張って、いろいろな研究について情報を仕入れているです。何がどの施策を展開するのがいいのかという、そういう判断をしながら進めていくことが大事かなというふうに思ってあります。","id":"exchange-084"},{"speaker":"山路委員","kind":"質問・要望","question":"毎年授業内容もアップしているですが、この授業についての、能力を伸ばす計画が平成２２年度であったら聞かせてほしいと求めました。区の職員の方も現場でお役に立つことをやられているということをお伺いしましたが、どういう講演を、お伺いいたします。","respondent":"和氣小中一貫教育担当課長","answer":"平成２１年度、前期で言いますと、総授業数の８％を習熟度別学習に充てているところです。","id":"exchange-085"},{"speaker":"山路委員","kind":"質問","question":"この質問をしたのは、職員の方で能力のある、教員免許を持っている人とかそういう方がサポートしている。こういう新しい案があると伺っておりますが、それについてはどのようにお考えか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"今、教育というのは本当に学校だけでやるものでもありませんし、総合的に子どもたちの力をつけてまいりたいと思っています。その意味では、非常に今後、区の職員がどういう形でかかわれるかについては、ぜひ研究させていただきたいというふうに考えてあります。","id":"exchange-086"},{"speaker":"山路委員","kind":"質問・要望","question":"能力、それもまた活かしていただいて、充実をしていくことを要望いたします。ここでお伺いしたいのは、これを一部障害者の方からお伺いしたのですが、お伺いいたします。","respondent":"冠木指導課長","answer":"小学校、そして特別支援学校の教育課程、一言でインクルージョン教育というのはなかなか難しいのかなという考えを持ってあります。という意味合いもございまして、品川区では子ども一人ひとりの状況に応じた特別支援教育を進めているです。","id":"exchange-087"},{"speaker":"山路委員","kind":"質問","question":"一部の障害者のお母さん方に、もう少しこうしてもらいたいというご意見もあるんですが、どうぞまたその節はよろしくお願いいたします。標語あるいは国に準じて準備をされていると思いますが、どういう計画をされているのか、お伺いします。","respondent":"小川品川図書館長","answer":"品川区立図書館」などのような標語のようなものをさまざま活用し、ＰＲに努めているところです。具体的には、さらに国民読書年用のしおりですとか、小さなのぼり旗のようなものも作成をするべく準備を進めているところです。","id":"exchange-088"},{"speaker":"山路委員","kind":"質問","question":"そういうものを考えて１０月の文字・活字文化の日に向けて、何かアイデアがあったら企画してもいいんじゃないかと思うんですけれども、どうか尋ねました。","respondent":"小川品川図書館長","answer":"特に川柳ですとかそのようなことについては、今のところ計画はございません。もうＰＲについては既に始まってありますし、国のほうの国民読書年祭典に向けて頑張ってまいります。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問","question":"３４７ページ、プラン２１推進事業について伺います。プラン２１、高いテストの点を取り、有名進学校へ進学できる児童を増やすということを指すのか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"私どもは、このプラン２１を通しまして、きめの細かい、個に応じた学習を展開をしながら、今の子どもの現実に応じた学習を展開をしています。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問・要望","question":"同じ小中一貫校、八潮では４０分なのに、なぜなのでしょうか。当然私は開校記念日は休みにすべきだと思いまして、日野学園の開校記念日で子どもは休みになっているのでしょうか、これも２点目でお伺いします。","respondent":"冠木指導課長","answer":"その校長の考え等々をお伺いしまして助言等を与えていく、そういうようなところを踏まえた上で、教育課程の編成に当たっているです。助言は申し上げますけれども、日野学園の子どもたちにとっての教育課程だということをご理解いただきたいと思います。","id":"exchange-091"},{"speaker":"安藤委員","kind":"質問","question":"答弁漏れなので、開校記念日は休みになっているかどうかお伺いします。","respondent":"冠木指導課長","answer":"開校記念日は、日野学園の場合、授業日です。開校記念日を休みとする根拠はございません。","id":"exchange-092"},{"speaker":"安藤委員","kind":"質問","question":"開校記念日、根拠がないかどうか私も知らないですけれども、それは何のための開校記念日なんですか。そこを授業に振り分けるなんて、ちょっと私は異常だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"安藤委員","kind":"質問","question":"子どもたちは何時から何時まで勉強するのでしょうか。これは授業扱いなんでしょうか、答えるよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問","question":"入浴した後になるんでしょうか、合計１日に１２時間勉強するという、これをいいという感性は異常ですよ。朝から晩まで、９時から夜中の１２時まで勉強させるということが、常軌を逸していると思わないんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"細かいところは詰めていきますけれども、当然、しっかりとした学習習慣を子どもたちに体感をさせるということが大変重要かと思います。まだまだ協議をしながら、より効果的な合宿になるように、教育委員会も日野学園とともに考えてまいりたいというふうに考えております。","id":"exchange-095"},{"speaker":"安藤委員","kind":"質問","question":"公教育のあり方として常軌を逸しているんではないですかというふうに質問したんですが、私はまさに、これが前段に申し上げた。少人数による学び合いの教育こそ、そうした環境こそ整えるべきだと思うのですが、いかがか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"そういうことを総合的に考えて、私どもは逆にすべての学校で高い質の教育を提供するためにさまざまな施策を打っているわけです。そして生活をしていける、そういうことを目指して、私どもは細かく細かく丁寧にやっているところです。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"確認","question":"私は３４５ページ、教育指導費に関連して、それから３４７ページ、小中一貫教育推進経費に関連して質問をいたします。確認したいのは、それから、この原則はしっかり守られているのでしょうかということの確認をお願いいたします。","respondent":"冠木指導課長","answer":"教員の服務につきましては、法律に基づいて徹底して指導をしています。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問","question":"それから平成２１年度、鈴ヶ森中学校で２年間施設分離型における小中連携が研究されて、今年の１月２２日に発表がありました。少し挙げますと、この非常にいい結果が出ているのですが、まずこのことについての教育委員会等の見解を説明を求めました。","respondent":"和氣小中一貫教育担当課長","answer":"実際にこの研究を進める中で、なかなか先生同士が一緒にやっていても、本音まで含めて踏み込むことができなかったという実態がございました。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"質問","question":"併せて今度は外に向かっていく作業ですから、それから地域との連携とか、さらに難しいハードルがこれから出てくる。だから、そういうことについて、やはり教育委員会としてのこれからの方向性、方針をぜひ、示すよう求めました。","respondent":"和氣小中一貫教育担当課長","answer":"それをさらに地域や保護者の皆さんと一緒に、私どもはこれを学校を支えていきながら行きたいと考えていますが、まだまだ不十分な点があります。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"せっかく２年間された教育の課題が消えてしまうし、またもしかしたら、その小中一貫教育にかかわった教師の方々が人事異動になるかもしれない。だから今の課長の答弁も安心するんだけれども、さらに将来を見据えた方向性をお示しいただければと思うんですが、いかがか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"次の手をどう打っていくかということは考えなければいけないと考えていますし、この研究にも区内のさまざまな学校が見に来て、学んでまいりました。それで、この鈴ヶ森グループについては、さらに２年間研究をしていただこうというふうに考えているところです。","id":"exchange-100"},{"speaker":"川西委員","kind":"質問","question":"一つ目は学校選択制で、今回の入学希望状況と受け入れ状況について、簡単で結構ですから、どのぐらいあふれたのか、あふれないのか。地元の意見、どのように当面使われていくのか、とりあえず伺います。","respondent":"富田学務課長、田村庶務課長","answer":"中学校ですが、中学校の希望申請は６０９人ということで、住民基本台帳に対しまして２９.８％、これも昨年を若干下回っております。昨年と同様の３校でございまして、若干残った学校が、中学校は伊藤学園１校です。 地域の方ですと、品川第一地区の町会長会議のほうに１回私が赴きまして、取得の経過からお話ししました。色だとか形状だとか、もし相談に乗ってもらえるのだったら調整してくれますかということで、調整しています。","id":"exchange-101"},{"speaker":"川西委員","kind":"質問・要望","question":"３４７ページ、中学校が１００人という予定人数というのは、どういうことなのでしょうか。二つですが、とりあえず伺います。","respondent":"富田学務課長、冠木指導課長","answer":"夏季施設ということで、夏休みに参加している学校は、中学校では冨士見台中学校１校だけでございまして、１００名予定です。 連合音楽会につきましては、品川区教育会のほうに委託をしていますので、３４５ページの品川区教育会のほうで予算計上しているということで、実施はしております。","id":"exchange-102"},{"speaker":"川西委員","kind":"質問","question":"移動教室の人数に比べて少ないから１００人、１校しか実施していないというのは、こういう傾向についてどういうふうに分析をしていらっしゃるか。中学校で１校しか行っていないということをどう評価していらっしゃるか、この点だけ伺います。","respondent":"富田学務課長","answer":"小学校６年生の移動教室、また５年生の夏季施設ということで多くの学校が使っていただいています。そのほかにもぜひ、日光の林間学園を中学生にもさまざまな機会で団体でも使っていただければというふうに思ってはおります。","id":"exchange-103"},{"speaker":"川西委員","kind":"質問","question":"どういう、このままずっとこの形で行くのかどうか、これもご意見を伺いたいと思います。ないということは、保護者はどうしたらいいんでしょうか、伺います。","respondent":"田村庶務課長","answer":"文化財の関係をまず１点目にお答えします。文化財めぐりというのもなかなか好評でして、そういうのを実施して、歴史をまた改めて見直してもらうというさまざまな活動をしているものです。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから何とか区内の中で、そういうことをできないだろうかということで、ご検討の結果、進捗状況をお聞きします。アナフィラキシーショックを起こした場合に、注射、教師の研修はちゃんとされているのでしょうかということについてお聞きいたします。","respondent":"田村庶務課長、和氣小中一貫教育担当課長、富田学務課長","answer":"ほかの教室だとか勉強会との連携という横のつながりが、やはりどこかの時点で、今度はＰＴＡの方というのはサービスを受ける側ですね。… ６年生、７年生が参加できるという形で、区内に限っては参加できる構図をつくりました。という形で、具体的にさまざまな課題はありますけれども… 一貫校については５年生で前倒しできないかということで検討したところですけれども、実は、前倒し支給を生活保護のほうでできないです。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり地域の中のすまいるスクールというのを私がイメージしているものですから、やはりそういう意味では、よろしくお願いします。それから、給食調理ですけれども、入らない、これはそうすると、きちっと対応してくれるんか尋ねました。","respondent":"富田学務課長","answer":"小中一貫校の５年生ですが、標準服につきましては、小中一貫校だけ別途支給するということは困難であろうというふうに考えている状況であります。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"１点目は３５７ページ、この３校がどこなのか、お聞きしたいと思います。中学校ＰＴＡ連合会」というふうに書かれていますけれども、これは３５３ページのＰＴＡ関係費でつくっているのかどうかをお聞きしたいと思います。","respondent":"田村庶務課長","answer":"それと平成２１年度が城南小学校、それで平成２２年度が、立会小学校を予定しているものです。中学校が４階建てということで、東京都の事業では平成２８年度まで延長する予定ということで、そのような事業です。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問・要望","question":"そんな意味では、やはりガソリン代より高いと言われる水ですから、東京都の水道水をぜひとも使っていくような施策をしてほしいと求めました。フィルタリングを知っていますかとか、インターネットの危険性、警察の少年係の係長のお話を伺いながらＤＶＤを見せていただきました。","respondent":"冠木指導課長","answer":"中学校になりますと、男子の平均で６４.２％、女子で７６.２％、平均でも約７０％の中学校の生徒が携帯電話を持っているという状況があります。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問・要望","question":"先ほども述べましたけれども、このリーフレットはよくできています。中学生の子どもたち、あるいは保護者全員に見せて考えていただきたいというふうに思っているんですけれども、これについてお願いをいたします。","respondent":"冠木指導課長","answer":"このリーフレットにつきましては、既に現在、小学校、中学校にいる児童・生徒についてはすべてご家庭のほうへの配付もしております。そして今度入ってくる新１年生のご家庭にも配付すべく準備をしています。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問・要望","question":"これだって自宅と通話連絡はとれるわけですから、帰っちゃうと、もう使わない。品川区の教育は日本に誇る教育ですので、しっかりやっていただきたいということで、もう一度お答えをほしいと求めました。","respondent":"冠木指導課長","answer":"情報の扱い方について非常に重要な課題だというふうに思ってあります。子どもたちへの指導を徹底するとともに、地域の方々にも協力を願ってまいりたいというふうに思います。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問・要望","question":"インターネットを使っての犯罪、加害者というとネットいじめということになるんでしょうけれども、それ以上にもっともっと恐ろしい話も聞きました。やはり携帯電話の使い方は、本当にさらにしっかり全児童、全保護者に対する啓発活動を続けていただきたいというふうに思って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"武内委員","kind":"質問・要望","question":"それから平成２２年度４月は今のところお聞きしているのは３名ということだと思うんですけれども、年度途中で採用を考えていくのかどうかということ。３６５ページの新しい事業で歯磨き指導法研究委託、どこの学校でどのようにやっていくかということで、４点お伺いしたいと思います。","respondent":"冠木指導課長、和氣小中一貫教育担当課長、富田学務課長","answer":"今後４月になりましたら、また学校の状況をお聞きしながら追加の配置については考えてまいりたいなというふうに思っているところです。１名、特別支援教育… 来年度は、この教科書を使うのは平成２３年度４月から新しい、この市民科教科書で授業をしていただくということを考えております。８年生… 歯磨き指導法研究委託ですが、現時点では芳水小学校と京陽小学校を予定をしております。","id":"exchange-112"},{"speaker":"武内委員","kind":"質問・要望","question":"例えば、例えば相談の内容によって、そういう連携の体制がどのようにとられているかということを教えてほしいと求めました。情報モラルのほうはもう既にやっているということも私ども伺っているのですけれども、また時代に合った、これは要望します。","respondent":"冠木指導課長、富田学務課長","answer":"その辺は柔軟に対応してまいりたいと考えています。それから、特に緊急案件、それから教育センターの中の教育相談センターがともに対応していくというような事例も出てこようかと思ってあります。歯磨き指導法ですけれども、必ずしもすべての学年で実施するというふうに決まっているわけではございません。","id":"exchange-113"},{"speaker":"武内委員","kind":"質問","question":"これは特別支援の子たちのことなのか、それともいろいろなケースがありますね、いじめとか不登校とか。そういったことについて、例えば学校の中で連携をとりながら進めていくとかということがあるのかどうか、説明を求めました。","respondent":"冠木指導課長","answer":"こういうような個別指導計画をつくって共通理解のもとに対応していくということで、この考え方は別に特別支援教育だけではなくて、あるいは今。特に特別支援については、１５名という話がありましたけれども、そんな取り組みを進めてまいりたいなと考えているところです。","id":"exchange-114"},{"speaker":"武内委員","kind":"質問","question":"最後に１点伺いますけれども、スクールカウンセラーの方が、例えば職員会議ですとか、または保護者会とか、地域のそういった青少年の関係とか、そういったところに請われて行くケースとか、また積極的に行ったりするケースとかというのは、あるんか尋ねました。","respondent":"冠木指導課長","answer":"専門職として採用しているわけですので、ぜひ、地域や保護者等々の集まりでも積極的に活用していただきたいというふうに思ってあります。私どももそういう部分については学校のほうに話をしていきたいと思ってあります。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、３４４ページ、教育指導費全般についてお聞きしたいと思います。子どもに格差のない学びの場をつくることが今求められているという、これについて何かご感想がありましたら言ってください。","respondent":"冠木指導課長","answer":"そして子どもたちの健全育成という目標があって、そういった大きなスケールの中で、私どもは品川区の小中一貫教育を進めているわけです。歴史的に見た場合に、品川区の小中学校については、やはり区民のための学校だというふうに認識をしています。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"先ほど一生懸命やっているというお話がありましたが、では教育費の予算はどうでしょうか。学校の先生、ほとんど品川区の教育は根本的なところで私は改善されていないんではないかと思うんですが、いかが思いますか。","respondent":"冠木指導課長","answer":"読み書きそろばんといいますか、そういうような部分では、きちっとした実力をつけているというふうに私は認識をしております。私は思考力とか判断力とかいうような部分についても、もっともっと力をつけていく必要があろうかなというふうに思っているところです。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"そしてあまり使わない副教科書、これは普通の教科書だってやるのは大変なのに、なんでさらに品川区でお金をかけてつくるんですか。じゃあ、その大変な子に対して気がついているなら、なんで補習をしてやれないんか尋ねました。","respondent":"冠木指導課長","answer":"保護者や地域も一緒になって取り組んでいるという実態がございまして、こういうようなところは、この３年上昇傾向にあります。それから規範意識もきちんとついてるというようなところでございまして、私どもとしましては、学力はきちんとついているというふうに思っているです。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"今、補習をしているとおっしゃいましたが、じゃあ、どこの学校がどうやっているんでしょうか。そうすると片一方はなくて、片一方は、働け働けとやって残業を一生懸命やらせて、その管理責任はどうなるんか尋ねました。","respondent":"冠木指導課長","answer":"子どもたちが例えば学力の部分で支援が必要な場合、そういった教員こそ地域に信頼を得て、学校が信頼を得ているというふうに思っているところです。時間外の勤務についてのお話もございましたが、これは法に基づいて対応しています。","id":"exchange-119"},{"speaker":"須藤委員","kind":"質問","question":"そこで質問をいたします。国のほうでは学校の耐震化については、ここで、そういった可能性で国の補助がもらえなくなってしまうという可能性はこの中にあるんか尋ねました。","respondent":"田村庶務課長","answer":"学校施設は耐震補強をやるとＩｓ値０.７以上にするという工事にしなければならないですが、間が０.３以上の耐震の関係が、宙に浮いていると。０.３未満についてはちゃんと耐震補強の対応として当初の予定どおり出るということで、今。","id":"exchange-120"},{"speaker":"須藤委員","kind":"質問","question":"それは、鈴ヶ森小学校、清水台小学校、両方ともＩｓ値０.３から０.７の間に入ってしまっているということなのですか。その場合、もしだめですよという話になったらいかがなさるのですか、区の一般会計でこの事業をなさるわけか尋ねました。","respondent":"田村庶務課長","answer":"鈴ヶ森小学校もＩｓ値０.３未満の部分と０.３以上の部分、両方あります。もう耐震補強、避難所としてあるいは学校の安全のために当初の予定どおり、計画どおり進めていくという予定です。","id":"exchange-121"},{"speaker":"須藤委員","kind":"意見","question":"それで、区の学力定着度調査が小学校４年生と中学校１年生でやっている。この４年生と７年生を選んだ理由は何かありますかとの意見を述べました。","respondent":"和氣小中一貫教育担当課長","answer":"この４年生と７年生というのは、私どもの４・３・２という学習のまとまりの到達段階で、どこまで私どもが狙いとしたところが定着しているのか、そのことを確認するために４年生と７年生というふうに分けてあります。","id":"exchange-122"},{"speaker":"須藤委員","kind":"質問","question":"品川区としては、予算的にはそうしないぞというような国のほうの話が出てしまっているんだけれども、そのあたりはいかがでしょうか。全部受けるようにしますか。","respondent":"冠木指導課長","answer":"この全国学力・学習状況調査というのは、先ほど委員のお話のように非常に質の高い調査問題というふうに認識しております。今回、全校で実施するよう予算措置をしまして、ご審議いただいているところです。","id":"exchange-123"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区としてはやはり頑張っていただいて、これに対応して、しっかりお子さんたちの成長の過程を見ていただきたい。教育長あたりが先頭になって、国のほうへやはり話をしてほしいと求めましたが、いかがか尋ねました。","respondent":"冠木指導課長","answer":"全国学力・学習状況調査については、いろいろな国の動向がありますけれども、私どもとして子ども一人ひとりの学力向上のために活かしてまいりたいと思いますので、そういった声は国のほうにも伝えてまいりたいと思ってあります。","id":"exchange-124"},{"speaker":"土井委員","kind":"質問・要望","question":"私から４点ほど伺います。これは当たり年って、何か寄附金充当というふうな感じで伺ったような気がするので、ということだけはちょっと聞かせてください。","respondent":"富田学務課長、金子企画財政課長、田村庶務課長","answer":"平成２２年度は再々リース、再リース６年目利用の１校、また５年目利用の１９校という３０校についてのセンターサーバ化を行っていくというものです。… それから図書館経費、ＰＴＡ関係費、これを現在このように整理しているものです。わかりやすく、ご提示申し上げるかというところを年々検討しておりますの… 待機児対策の保幼小の連携ですが、校長会のほうにそういう区の方針だけれども手を挙げてみないかということで、今回の待機児対策の学校を選定したものです。","id":"exchange-125"},{"speaker":"土井委員","kind":"質問・要望","question":"ですから、これらをどう、二重三重にならないようにしっかりやっていただきたいと思うんですね。これをやるんだったらほかとのバランスもこれから出てくるわけで、そこら辺も含めてこれが恒久的なものなのかどうかだけは１回聞かせてください。","respondent":"富田学務課長","answer":"空港周辺環境整備事業については、財団法人空港環境整備協会の実施事業です。浜川小学校と、鈴ヶ森中学校、浜川中学校ということで限定をされているところです。","id":"exchange-126"},{"speaker":"土井委員","kind":"質問","question":"わかりました。財団法人ですから、必要によっては一般会計からも出さなければいけないかもしれないということになりますので、その辺やっておいてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"３６０ページの教育振興費に関連して伺います。そういう状況について、品川区ではあるのかないのか、教育委員会の見解をちょっと伺いたいと思います。","respondent":"冠木指導課長","answer":"朝食をなかなかとれないで学校に登校してくるというご家庭があるというような報告は私どものほうでも受けております。そういう統計的な数字は持っておりませんけれども、学校との連絡の中で、そういうようなご家庭があるということは聞いてあります。","id":"exchange-128"},{"speaker":"南委員","kind":"質問","question":"その点について、ちょっと後で見解を伺いたいと思います。これについての認識と、それから、こういう状況についてどういうふうに受けとめているかということをちょっと伺いたいと思います。","respondent":"冠木指導課長","answer":"区全体として例えば８３運動とか、そして私どもも、保護者に対しても朝食を食べてくることは大事ですよということは啓発をしているわけです。実数についてはそれぞれの学校の報告以上のものはございませんけれども、対応をしていくことが必要なのかなというふうに思ってあります。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"ＯＥＣＤから警告が出されているということについての認識も伺ったんですけれども、後でお願いします。したがって、その点についての見解を伺いたいと思います。","respondent":"富田学務課長","answer":"私ども教育委員会といたしましては、経済的理由によって就学困難なご家庭を対象にした制度として、就学援助の制度というのがあります。これを適正に実施しています。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"相変わらずＯＥＣＤの認識、警告についての認識というのはないですか。こういう状況について、無償化との問題でもどういうふうに考えるのか、この辺についての見解も、ちょっとあわせて伺いたいと思います。","respondent":"富田学務課長","answer":"保護者の方々の学校への学納金、これにつきましては、かなりの部分について就学援助で支給をさせていただいているところです。","id":"exchange-131"},{"speaker":"南委員","kind":"確認","question":"品川区はあまりそこにこだわらずに１.２５倍を確保しているよということなのかどうなのか、ちょっと改めてその辺も確認したいというふうに思います。いつも毎年やっている移動教室がありますけれども、この費用負担の関係では、どういうふうになっているのかも併せて伺います。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"私どもといたしましては教育委員会として、必要な就学援助は実施をしているというふうに考えているところです。生活保護に対するこういった算定基準というものは変更せずに実施をしてきているという状況があります。学校が今、必死になって子どもたちのために考えている、この内容について私どもはしっかり支援をしてまいりたいというふうに思っております。","id":"exchange-132"},{"speaker":"南委員","kind":"質問","question":"私は、幾らですかと。幾らですかと、その資料に幾らと書いてあるかと聞いているんです。","respondent":"和氣小中一貫教育担当課長","answer":"学校で内部で今検討しているものについて、私が幾らですと言う、こういう権利はございません。","id":"exchange-133"},{"speaker":"南委員","kind":"意見","question":"どこでどういうふうに決めたか答弁がないからわからないですけれども、そういう計画をやはり私はやるべきではないというふうに思うんですね。やめるべきですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-134"},{"speaker":"三上委員","kind":"提案","question":"品川区でも実践したらどうかと提案させていただいて、あるいはエコの部分を見せていくことができないかについて調べてみたいというご答弁があった。","respondent":"冠木指導課長、小川品川図書館長、田村庶務課長","answer":"私のほうからは保育園と小学校とのこれからの取り組み、５歳児の取り組みについて、小学校側の意識ということでお答えをしたいと思います。… 延べ利用者の関係なんですけれども、２０代前半におきましても、毎年ここのところ伸びているというような現状です。ちなみに… 日にちが、冬場はちょうど時期的には無理なので３月３０日に実施する予定です。","id":"exchange-135"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういった点での取り組みをぜひお願いしたいと、こう思います。ですから、その井戸水がどういうふうに使えるのかということも含めまして、どういうふうに対応されるかお伺いしておきたい。","respondent":"中山防災課長","answer":"私ども防災課といたしましては、いわゆる下水道管の耐震工事で排泄物の削減にかなりの能力を発揮するだろうと思ってあります。ただ、今掘ってあります１ｔ便槽が、くみ取りも入れて６つありますけれども、これは残しておいていただきたいと思ってあります。","id":"exchange-136"},{"speaker":"鈴木委員","kind":"質問","question":"教育指導費の中から、市民科とスクールカウンセラー、それと、それに関連して１点お聞きします。そこをどういうふうに先生方がとらえるのか、その点をちょっと先にお聞きしたいと思います。","respondent":"冠木指導課長","answer":"もちろん教員は教育の専門家ということで子どもたちに対応してくるんですけれども、スクールカウンセラーについては。その辺の敷居といいますか、その辺は今払拭をさせていただいておりまして、学校とスクールカウンセラーが十分に連携して取り組んでいるところです。","id":"exchange-137"},{"speaker":"鈴木委員","kind":"質問","question":"先生方はその辺のところをどうとっているかというのは非常に気になって、変な言い方ですけれども、ちょっとそれはお聞きしました。この点で、考え方としてちょっと整理させてください。","respondent":"中山人権啓発課長","answer":"こうした暴力ですとか虐待ということは、ほかにも児童虐待や高齢者の虐待ということで、今それぞれの所管が対応しているところです。区としても対応を一つにして、あるいはそういう相談を広く組み入れて対応していくかということを考えてまいるつもりでおります。","id":"exchange-138"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やはり全体、どこから入っていってもいいというように、教育委員会もその辺も調整していただきたいということでお願いいたします。９年間の、資料の中では９年間の狙いが出ていますけれども、どうなっているのでしょうかということをお答えをお願いいたします。","respondent":"冠木指導課長","answer":"モデル実施をしているところにつきましては、市民科の考えをそこで伝えていきたいという思いでの考え方ですので、市民科自体をその後のカリキュラムにということではございません。","id":"exchange-139"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それを今年度、平成２３年度に向けてたしか改訂していくということなので、いい市民科を続けていってほしいと求めました。これは偶然出たのかどうか、当然子どもに対しておめでとうと言うのと同時に先生方の評価はどういうふうに考えたらいいんか尋ねました。","respondent":"冠木指導課長","answer":"世界児童画展で２年連続特別賞、文部科学大臣賞あるいは内閣総理大臣賞ということで、非常にうれしい知らせがここ続いているところです。長年教育の中で培ってきたノウハウ、今回の、そして去年の表彰につながっているのかなというふうに思ってあります。","id":"exchange-140"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう中で、教育委員会からいろいろな予算の要望がある中で、区長として予算編成をしていく。たしか正月の番組か何かでも、品川区の教育についてもう一回、最後に区長のお考えをほしいと求めました。","respondent":"濱野区長","answer":"それから皆さんの活躍が品川区の自慢、誇りだということを伝えて、長く続けてもらうようにお願いをしております。そうした才能や力が開花する、これも一つ品川区の教育の成果だというふうに思っております。","id":"exchange-141"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/998976?Template=document&Id=940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":115922,"voices":356}},{"id":"h22-20100323-3","meetingId":"h22-c-budget","date":"2010年3月23日","dateIso":"2010-03-23","committee":"予算特別委員会","time":"午前１０時０２分～午後７時２６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、学校教育だけで学ぶ話ではない中で、教育という幅広い中で、一義的な責任というものはどこにあるのか、それをまず伺いたいと思います。そして、２点目に、よく言われる、学校、地域、家庭、それぞれの連携と役割を、改めて伺いたいと思います。","respondent":"市川教育次長","answer":"学校、家庭、地域の三者がそれぞれの役割と責任を自覚し、お互いに協力し合うことが求められていると考えております。このような考え方は、３年前に改正されました教育基本法の中にも、はっきりとうたわれているところです。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"確認","question":"確認を含めて、伺わせていただきました。なぜあいさつが必要なのかということも踏まえて、このことについて２点ほど、伺えればと思います。","respondent":"市川教育次長","answer":"いわゆるマニュアル社会の課題と対応ということにつきましては、自分で考える力については、必要不可欠な力です。２点目のあいさつに関連してですが、このことは、古今東西変わらぬ普遍の原理だととらえてあります。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"今回、総括質疑ということで、来年度の予算にも、項目で言いますと、マナーキッズという項目がありました。市民科の流れの中での力の入れぐあいのあらわれだと思いますが、この点を、もう一度伺えればと思います。","respondent":"市川教育次長","answer":"子どもはもちろんですが、同時に保護者にも向けた取り組みということで、このマナーキッズというものを採用しています。いわゆる地域の大人の方との触れ合い、テニス関係者の方も含めですが、こうしたことをポイントにしている事業です。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問・要望","question":"次に、社会教育の一環で、子どもの遊び方というくくりで伺っていきたいと思います。その方針と、今後の展開について、まず１点、伺いたい。","respondent":"久保田都市環境事業部長、古川子ども未来事業部長","answer":"区は、地域バランスを考慮して可能な限り遊び場を整備するということで、子どもたちが自由に遊べるように対応してきたということが一つあります。したがいまして、残りの２０５公園については… 児童センターの方針と、０歳から１８歳までが児童センターを主として活用する、そういう中での健全育成を担ってあります。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"公園のところは要望と合わせて、数字を伺って、時間は限られている。これはいいというようなソフトな表示も要望としてありましたので、どうか今後、その点を伺わせてください。","respondent":"久保田都市環境事業部長","answer":"ソフトな対応ということでございましたけれども、そういう面での、ソフト化を図ってほしいというご提案だと思います。できるだけ対応したいと考えておりますが、広さなど、公園によってはいろいろ制約もあります。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"これから伺っていくのは、社会教育の必要を感じることの事例が結構あると思います、遊び方以外にも。そして、テレビゲーム、インターネット社会への対応と課題、この辺をあわせて伺えればと思います。","respondent":"市川教育次長","answer":"そのゲームと接している子どもの２４時間を通しての生活習慣なり、生活態度、この問題へのアプローチとしてまず大切なことだろうと考えています。この社会の中で盛んに用いられていることへの対応ですけれども、発達段階に応じて、きちんと教えていく必要があると思ってあります。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"これも対象学年が広いですから、１日にどれぐらい利用するのか、そのような時間のことが把握できていれば教えてください。これをまず、伺いたいと思います。","respondent":"市川教育次長","answer":"男女別につきましては、小学校、中学校ともに、女子のほうがおおよそ１０％高くなっている傾向があります。小学校６年生と中学校９年生ですけれども、「ほぼ毎日している」と答えた６年生が２０％、９年生は４４％と数字になってあります。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"今後、強い指導やルールづくり、このようなことをどうお考えか。あるいは市民科の取り組み、全体というくくりで、最後に伺えればと思います。","respondent":"市川教育次長","answer":"まさに、しながわアクションを構成する地域の関係者による地域の教育力というもので、この携帯電話の問題に取り組んでまいりたいと考えています。改めて、このことについては、教育の出発点に立って、家庭との連携ということが大変重要な課題になってくると考えています。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"確認","question":"確認を含めて伺います。そして、品川区と連携を密にしている主な種目、団体、それぞれの携わる児童数、競技人口、このあたりを伺えればと思います。","respondent":"古川子ども未来事業部長","answer":"おおむね１,７００名の子どもたち、約１,５００名ぐらい、バレーボールにつきましては１４０名ぐらいです。社会性を身につけていくという場になっているということについては、私どもも、今後とも支援していきたいと考えています。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ボランティアによって支えられていますが、この点をどのようにお考えか、確認を含めて伺います。今後の区の取り組み、姿勢を伺わせてください。","respondent":"古川子ども未来事業部長","answer":"さまざまなスポーツの支援、さまざまな事業がありますけれども、そのためにできる限りの支援をしていきたいと思ってあります。私ども熱心に伺わせていただきながら、何とかやりくりをし、そして初期の目的が達成できるようなスポーツ活動を支えていきたいと考えております。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そのようなアスリートを育成するような形、あるいは、品川区としてのできること、今後の方向性を伺えればと思います。今まで強く要望してまいりましたが、あるいは子どもたちに触れる機会を強く求めてまいりましたが、現状をお知らせください。","respondent":"宮地地域振興事業部長","answer":"実際には、特に平成２２年度からは、文化、芸術、スポーツ活動の顕彰制度などもスタートさせる予定です。特に小学生が演劇を鑑賞できるような事業につきましては、劇団四季としても、前向きに検討していると伺っております。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問・要望","question":"あるいは、健康増進効果、主な事例があったら教えていただきたい。教えていただいたように、最後に、全体論として伺えればと思います。","respondent":"宮地地域振興事業部長","answer":"多くの方たちが健康な生活を送り、社会参加や仲間づくりをする、あるいは交流を広げることが一定の健康づくりに効果があると考えています。文化スポーツを通じたまちづくりを、また広げていくということで、非常に組織改正の効果はあったと考えているところです。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"次に、生活安全、防犯のことを伺えばと思います。そのような分析、調査があれば、説明を求めました。","respondent":"宮地地域振興事業部長","answer":"犯罪の未然防止は、区民の方の理解と協力によるものだと認識しております。実際に、活動といたしましては、わがまちパトロール隊、これは現在、１２５名の委嘱の予定者がおります。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問","question":"対象が広い防犯の中で、ちょっと絞って伺いたいと思います。防犯カメラへの、区の取り組みを説明を求めました。","respondent":"宮地地域振興事業部長","answer":"新年度に実施いたしますが、ドアの設置などに、部品なども対象となっています。課題といたしましては、やはり設置場所にちょっと苦労いたしますが、その他、維持管理を継続してやることがあります。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問","question":"私のほうは、これで終了します。松澤委員のほうから、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問・要望","question":"質問の内容は、大きく三つ、まず第１点目は、財政について、２点目、防災について、３点目、教育について、お伺いをいたします。大きなくくりとして、今後の財政運営についてのお考え、展望をお聞かせほしいと求めました。","respondent":"濱野区長","answer":"経済の縮小に対応するもう一つの予算といった、いわば２階建ての予算をいつまで組めるかということは、非常に疑問です。来年度の予算に向けて、ゼロベースでの事務事業の見直しといったものを精力的に取り組まなければならない、こんな思いでいるところです。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"品川区の基金について、どのような種類が、幾らあるのか。平成２２年度の取崩し額、財政調整基金の推移はどうなっているのか、お伺いしていきたいと思います。","respondent":"金子企画財政課長","answer":"同じく基金の積立予定額ですけれども、減債基金が１,５００万円余、財政調整基金が４億３,０００万円ほどです。現在の見込みということでは、平成２２年度末では、４６億円弱となります。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"いろいろお話を伺いました。それから、杉並区の区税の減税案ではありませんけれども、基金の効率的な運用についてはどう考えているのか、この点をお聞きしたいと思います。","respondent":"金子企画財政課長","answer":"基金の効率的な運用というご質問ですけれども、私ども、先ほど申しましたとおり、施設整備のピークが、平成２１年度、２２年度であります。では、やはり予算の中で積立額も増やすことによって、今後の公共施設の更新期にも対応できるようなことで考えていきたいと考えております。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"多分にパフォーマンス的なものが含まれているのではないか、この国の事業仕分けの評価結果による区への影響について、お伺いをしたいと思います。その詳細についてと、区としての対応策について、お伺いしたいと思います。","respondent":"金子企画財政課長","answer":"国の公共事業関係費で１５％の削減とされていますけれども、現在は、情報収集に努めている段階です。区として必要な事業については実施していくという立場から、学力テストの全校実施については、実施してまいる考えでおります。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"ひも付ではなく、地方で自由に使えるようにとの話ではありますけれども、金額が減少する。特に大都市では減少額が大きいと伝え聞いておりますが、区への影響について、お伺いしたいと思います。","respondent":"金子企画財政課長","answer":"交付金等の制度を改革するという考え方が、現在、示されております。国で制度設計を検討していると、平成２３年度からの導入を目指すということですので、国の検討の推移を注視してまいりたいと考えています。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問・要望","question":"次に、子ども手当について、お伺いをいたします。子ども手当の仕組みはどうなっているのか、どう対応したのかについて、お伺いをしたいと思います。","respondent":"古川子ども未来事業部長","answer":"本来、子ども手当につきましては、国の制度として、国が全額、国庫で負担するという方針でございました。国のほうでの負担による実施が望ましいと考えていますし、さまざまな形で、そのような要望をしています。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"その上乗せということですから、３,０００円しかもらえない世帯、三つに分かれているということを指摘しておきたいと思います。質問していた中で、何らかの対策を講じたのかについて、お伺いをしていきたいと思います。","respondent":"金子企画財政課長、古川子ども未来事業部長","answer":"この２月末までに４万人を超える利用の方がございまして、そういう意味では、かなり成果が上がっているとは思っております。今後も、このサービス向上については、より一層図っていきたいと考えているところです。 ちょっと私のほうの説明が不足しておりました、申しわけございません。３,０００円、８,０００円受給されている方々につきましては、お一人１万３,０００円です。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"前年度比１７.４％という大きな数字になりました。今後の見込みについてと、このような義務的経費が増えることについて、どう考えているのか、お伺いしたいと思います。","respondent":"木下健康福祉事業部長","answer":"生活保護費の今後の見込みですけれども、この間の大きなトレンドで見てまいりますと、大体５％ぐらい増えてきております。特に就労につながるような支援をきちんとしていくこと、保護の廃止に努める、今後とも努めていきたいと考えております。","id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"最後に、国保改正について、お伺いしたいと思います。国は、地方主権と言いながら、地方自治体に負担をかけている、国に対してものを申すべきではないかと思いますが、いかがか尋ねました。","respondent":"日下部企画部長","answer":"例年同様の予定で、平成２２年度予算に計上し、上程をさせていただいたです。今後、再びこのような事態を招くことのないよう、改めて申し入れを行うなど、さらに必要な対応についても検討してまいりたいと考えているところです。","id":"exchange-024"},{"speaker":"松澤委員","kind":"質問・要望","question":"国のことで区が振り回されないように、しっかりとものを申していただきたいと要望しておきます。その内容と、品川区内における被害想定はどのようになっているのかについて、お伺いをしていきたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"この東京都の首都直下地震による被害想定の品川区内における被害の状況ですけれども、この被害想定は、早朝と夕方の場合の２種類に分けてあります。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"発災後１日経ったときに１５万７,３６８人、その避難者の６５％ということで、１０万２,２８９人とされています。その避難所整備計画と、減災目標に対する施策について、お伺いをしていきたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"外出者は約３８万人を想定しておりますけれども、こういう方々が早期に帰宅できるような対策も、この中で打ってあります。全員が、発災後４日以内に帰宅できるように、事業所との協力体制を組んで、体制を強化してまいります。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問・要望","question":"小さいながらも戸越公園一帯を広域避難場所と指定すべきだと、議会で主張してきた私にとっては、まさに我が意を得たりという思いがいたしました。その周辺整備として、都市防災不燃化促進事業と、防災生活圏促進事業が行われていますが、その事業内容と、現在の進捗状況をお願いいたします。","respondent":"岩田防災まちづくり事業部長","answer":"戸越公園の周辺につきまして、ご説明します。直近では、戸越公園一帯につきましては、平成１８年度から実施しまして、ここはまだ実施後、間もないんですが、助成棟数が約３６棟です。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問・要望","question":"あるいは、高さ制限をしたいという話も、前に伺ったことがあります。どのような案が多かったのかについて、現時点での調査結果をお知らせほしいと求めました。","respondent":"岩田防災まちづくり事業部長","answer":"パブリックコメントの意見ですけれども、現在まで、１９件が区のほうに寄せられてあります。特に防災に関する意見が６件ございまして、トイレをきちっと確保してほしい等々の、防災上の積極的な意見が多く出されております。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"現状では、安全な避難場所とは言えないと思いますが、これについての見解をお聞きしたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"約１,６００人が避難できるということになっておりますが、約１,０００人が増えて２,６００人が、プラス１,０００人になります。不燃化率を７０％まで上げますと、一度に１万５００人まで避難者が増えるということですので、そういう施策も検討してまいりたいと考えています。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"総合危険度５にランクされる地域が４カ所、なぜか西品川二丁目地区だけは、何の防災の網もかかっていないんです。私も、再三、議会で質問しているんですが、なぜここに網をかけることができないのかについて、お伺いしたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"総合危険度の１から５のランクというのは、２３区全体の中での相対評価になりますので、全体と比べてランクが上がってしまうという状況です。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問・要望","question":"品川区は独自に取り組んできた品川区小中一貫教育が、約４年経過いたしました。この４年間、今後の展望について、お聞かせほしいと求めました。","respondent":"若月教育長","answer":"私は冨士見台中学校に行ってまいりましたが、やはり７年生も、８年生も、９年生も、ほんとうに立派な卒業式をやっていただきました。これからも続けていけば、確実にその成果といったようなものが積み重ねられていくだろうと、かように考えているところです。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"展望について、お伺いをいたしました。小中一貫教育全国サミット２０１０ｉｎ品川が計画されておりますけれども、ねらいについて、お伺いしたいと思います。","respondent":"若月教育長","answer":"と申しますのは、やはり施設一体型の一貫校といったようなもの、これをすべての自治体でつくるというのは、やはりなかなか難しい。現在、およそ１,８００名の方が参加をしたいといったような問い合わせがきているところです。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問・要望","question":"次に、私たち議員も委員会視察とか、会派の視察、個人視察と、全国の先駆的事例研究のために視察に参りますけれども、品川区の小中一貫教育、または施設一体型小中一貫校に対する視察要望と、その実現件数について、お教えほしいと求めました。","respondent":"若月教育長","answer":"国家レベルで１０回以上きておりまして、日野学園という名前は、もう日常で使われているほど有名になっているとも伺っているところです。それを、この一貫教育の中から見出そうと、そういった問題意識が底流にあるように感じられます。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問・要望","question":"たくさんの全国の自治体、あるいは外国からも、どこを、どう工夫すればという勉強にきているというお話を伺いました。今後の施設一体型小中一貫校建設について、どう考えているのか、展望についてお聞かせほしいと求めました。","respondent":"若月教育長","answer":"平成２５年３月には、荏原東地区の小中一貫校、施設一体型が完成をするわけであります。そうしたことを考えますと、これをまず図ることが第一義的な問題であると、かように考えるところです。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"今のお話で、了としておきます。最後に、品川区固有教員の配置が、昨年から始まっておりますが、その成果についてお聞きしたいと思います。","respondent":"若月教育長","answer":"それから、２点目に校長が言っていたことは、いわゆる新採の教員になるわけでありますけれども、その教員の育成計画も非常に具体的になってきた。それだけに、また、そうした先生方、また、それを育成する教育委員会の責任は重いと、このような自覚をしています。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問・要望","question":"今、お話を伺いました。どうぞこの政策は進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"山元委員","kind":"提案","question":"公明党の提案で、本区では、昨年１０月からスタートした同検診事業も、この３月末でひとまず終了いたします。私たちの要望も受け入れていただき、４月からの事業継続の予算が示されていますが、お伺いいたしますとの意見を述べました。","respondent":"中村品川区保健所長","answer":"平成２０年度、１７.９％が今年度１月末で１８.３％に上昇し、それぞれ２０％を超える見込みです。できるだけ早い時期から実施し、平成２１年度は６カ月間の実施でございましたけれども、年度末までの実施期間を設定できればと考えております。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"そこで、現在、１０カ所まで拡大されている医療機関の、今後の拡充についてのお考えをお伺いいたします。制度の利用を医師会などに働きかけたのか、お伺いいたします。","respondent":"中村品川区保健所長","answer":"実施の医療機関ですが、１１カ所目を、この３月から開始しております。平成２２年度につきましては、現在、交渉中の医療機関が１カ所増える予定です。","id":"exchange-038"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党はいち早く国に求め、１２月から、１０歳以上の女性に予防接種が可能となりました。さきの第１回定例会での我が党の一般質問の答弁では、１８型が７割から８割を占めるとのデータもあるようですが、あわせてご所見をお伺いいたします。","respondent":"中村品川区保健所長","answer":"ワクチンの効果についてですけれども、子宮頸がんワクチンが有用なワクチンであるということについては認識をしているわけです。ウイルスに感染しないという啓発を重視するべきかと考えておるわけです。","id":"exchange-039"},{"speaker":"山元委員","kind":"提案","question":"どうかもう一度、その辺をご確認いただき、ご検討をほしいと求めました。一日も早い子宮頸がん予防ワクチン接種の公費助成を実施するように、改めて要望いたしますが、本区のお考えをお伺いいたしますとの意見を述べました。","respondent":"中村品川区保健所長","answer":"東京都におきまして、説明会を開催するですけれども、まだ日時等の通知が届いておりません。こうしたことから、今後も情報収集を継続いたしまして、一定の見解が得られた時点で、改めて公費助成の検討を行いたいと考えております。","id":"exchange-040"},{"speaker":"山元委員","kind":"質問","question":"ここ数年で結構ですが、追加したがん検診と、追加した理由および追加までの検討経緯について、お伺いします。がん検診の実施はしていませんが、検診によってがんの兆候が発見できるがんはどのような種類があるのか、この２点について、お伺いいたします。","respondent":"中村品川区保健所長","answer":"このほかのがん検診につきましては、今のところ、費用対効果を考えますと、直ちに実施を検討するような状況にはないと考えているわけです。現在我が区で実施しております検診の受診率の向上を図り、また、検診の制度を高めていくことが重要かと考えております。","id":"exchange-041"},{"speaker":"山元委員","kind":"提案","question":"茨城県の下妻市では、歯科医師会と協力して、自己負担金５００円で、口腔がんの検診を開始したと聞きました。５年に１回の成人歯科検診を無料で実施していますが、がん検診の拡充を提案いたしますが、ご所見をお伺いいたしますとの意見を述べました。","respondent":"中村品川区保健所長","answer":"現在、行っております５年に一度の節目の歯科検診におきまして、口腔がんが発見されたということは、これまでに聞いておらないわけです。義歯の手入れ等、定期的な受診をしていただきまして、口腔がんの早期発見につなげていただきたいと思っているわけです。","id":"exchange-042"},{"speaker":"山元委員","kind":"質問・要望","question":"はじめに、待機児童解消の現状について、お伺いいたします。年度途中で予定されています、待機児童対策による解消の見込みについても、お伺いします。","respondent":"古川子ども未来事業部長","answer":"例年ですと、４月中旬以降に、今回の入園についての一定の結果が出てまいります。それにつきましても、有効な手だてになると考えています。","id":"exchange-043"},{"speaker":"山元委員","kind":"提案","question":"これまで待機児童ゼロに向けてさまざまな提案を行っておりますが、潜在的需要もあわせると、まだまだ増える可能性があるとされています。区の見解と、今後の取り組みについて、説明を求めました。","respondent":"古川子ども未来事業部長","answer":"若干あるのかなと考えてございまして、あるいは、検討も必要なのかということも考えてあります。両面から、待機児を一人でも減らしていくという考え方で、今後とも進めてまいります。","id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"次に、保育ママ制度について、お伺いします。約４００万円を計上していますが、評価について、説明を求めました。","respondent":"古川子ども未来事業部長","answer":"特に乳児期における子どもと親との愛着関係等を考えますと、一定の必要性もあろうかと考えていますし、推進をしていく。そういう中での取り組みを、今後、始めていきたいと考えています。","id":"exchange-045"},{"speaker":"山元委員","kind":"質問","question":"当時を振り返り、継続が困難だった要因は何だったのでしょうか。そこで、今後の一般公募に対する考え方を、お伺いいたします。","respondent":"古川子ども未来事業部長","answer":"そういう中では、０歳児保育に対する保育園の施策が非常に優れた内容があった、こういうのも一つの原因であったのかなと思ってあります。そしてそのような方々に家庭福祉員、保育ママとしての事業にご理解をいただき、一人でも多くの方々に協力していただきたいと考えています。","id":"exchange-046"},{"speaker":"山元委員","kind":"質問","question":"そして、それが各区市町村で進めるとしているわけですが、そこで、品川区は、例えばこの研修について、どのような受講体制をお考えなのでしょうか。講座の要請をするなど、研修体制の整備を具体的に進めるべきと考えますけれども、ご所見をお伺いいたします。","respondent":"古川子ども未来事業部長","answer":"その研修をどういう形で取り組んでいくかですが、さまざまな養成期間、大学等の先生方との交流もしています。保育ママ制度がスムーズに運営できるように、研修制度につきましても、さまざまな方面から検討してまいりたいと考えています。","id":"exchange-047"},{"speaker":"山元委員","kind":"提案","question":"空き店舗も、同様に活用を考えてみてはいかがでしょうか。区有地や都有地などに、プレハブなどの簡易な建物の設置もあわせて提案いたしますけれども、それぞれのご所見をお伺いいたしますとの意見を述べました。","respondent":"古川子ども未来事業部長","answer":"負担がかかっていたと考えておりまして、１人ではなくて、あろうかと考えています。複数の方々による合同保育的な要素も、当然あるという中では、さまざまな施設の可能性を探っていきたいと考えております。","id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにいたしましても、あらゆる施策を総動員して、待機児童ゼロに向けて積極的に取り組まれますよう強く要望いたします。最後に、ご決意をお伺いいたしたいと思います。","respondent":"古川子ども未来事業部長","answer":"これは、私の経験の中でも、今まであり得なかった大きな受け皿を用意したと考えております。一人でも待機者を出さないという方針を持って、この４月、さまざまな検討をしてまいりたいと考えております。","id":"exchange-049"},{"speaker":"山元委員","kind":"質問","question":"ただいま、力強いご決意をしかと承りました。どうか待機児童対策に、より一層のご尽力をお願いいたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"堺委員","kind":"提案","question":"都営や都民住宅の誘致を都に要望するよう提案、低家賃の公的住宅の大量確保を提案するなど、住宅対策についてお伺いをいたします。１点目は、第三次品川区住宅マスタープランの検証と、第四次品川区住宅マスタープランの策定について、お伺いをいたしますとの意見を述べました。","respondent":"岩田防災まちづくり事業部長","answer":"その中で、品川区住宅マスタープランについても、同じ土俵の中で全面改定を検討していく予定です。品川区のこの１０年間の都市の構造の変化、それから、住宅関係がどのように区内で変化しているのかということを調査する予定になっております。","id":"exchange-051"},{"speaker":"堺委員","kind":"質問","question":"そこで、誠に時期を得た施策であり、早期実現を願う立場から、検討状況について、お伺いをします。それぞれご見解をお伺いいたします。","respondent":"岩田防災まちづくり事業部長","answer":"今年、行います都市マスタープランのための基礎調査とあわせて、新たにどういうふうに打っていくかということを検討してまいりたいと考えています。さまざまな対策を検討中ですけれども、今、検討している最中です。","id":"exchange-052"},{"speaker":"堺委員","kind":"質問・要望","question":"これについては、また後ほど、重ねて確認をさせてほしいと求めました。更新されるよう、改めて確認をしておきたいと思いますが、それぞれご見解をお伺いいたします。","respondent":"木下健康福祉事業部長","answer":"区といたしましては、まず、新規の借上型の高齢者住宅については、その家賃助成の負担、補助制度等の関連から、予定はしてございません。","id":"exchange-053"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひしっかりと取り組んでいただきたいと、この辺につきましても、ぜひそのようなお取り組みをお願いしておきたいと思います。４点目になりますが、借上型それぞれ３月１日現在の入居状況について、お伺いをしておきたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"管理戸数は２９８戸のうち、空き室になっておりますのは５１室、１７％の空室率です。それから、建設型につきましては、管理戸数１,０５６戸のうち、空き室が７６戸、空室率は７％です。","id":"exchange-054"},{"speaker":"堺委員","kind":"意見","question":"借上型については５１戸の空き室で、１７％、全体的には１,０５６戸のうち７６戸空き室が出ているというご答弁でございました。借上型住宅の借上期間と、その方針の有無について、お聞かせほしいと求めました。","respondent":"岩田防災まちづくり事業部長","answer":"現在では、この制度の趣旨から言って、２０年後には傾斜家賃が市場家賃と一緒になるという理論上の考え方から、オーナーに２０年後は引き継ぐです。おおむね１５年程度で、家賃が市場家賃と一緒になるという、当時の考え方でございました。","id":"exchange-055"},{"speaker":"堺委員","kind":"確認","question":"借上型では５１戸、建設型では２７戸というあきが出ているという中で、ちょっと確認をしておきたい。トータルでは２９８戸が管理戸数ですが、これは今後どういうふうにしていくのか、ちょっとあわせて確認をしておきたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"さまざまないろいろな国の動きを引き続きやってまいりますけれども、今年の早い時期に、オーナーとの交渉に入っていきたいと考えております。こういった政策目的の部分に、今、手を加えるということは考えてございません。","id":"exchange-056"},{"speaker":"堺委員","kind":"提案","question":"平成７年第４回定例会の一般質問や、平成８年第４回定例会の一般質問において、我が党が提案させていただいた経緯があります。３％に下げたという実績を踏まえて、住み続けられるような対策を早急に講ずるべきであると思いますが、重ねてご見解を確認しておきたいと思いますとの意見を述べました。","respondent":"岩田防災まちづくり事業部長","answer":"こういったものを含めて、今、総合的に検討をしている最中です。先ほど申し上げましたように、できるだけ早い時期に結論を出して、打って出たいと考えております。","id":"exchange-057"},{"speaker":"堺委員","kind":"質問・要望","question":"できるだけ早い時期に結論を出したいというご答弁ですが、区民住宅の空き部屋対策について、最後に区長の見解を確認しておきたいんです。そこで、今後、どのように取り組んでいかれるのか、ここで区長の見解を、ちょっと確認をしておきたい。","respondent":"濱野区長","answer":"その際に、国との整合性、あるいは、先ほど申しましたように、従来居住者の整合性をつけるということで、今、鋭意、検討しています。なるべく早い時期に、制度の切り替えを図ってまいりたいと考えていますので、ご理解をお願いしたいと思います。","id":"exchange-058"},{"speaker":"堺委員","kind":"質問・要望","question":"そこで、今後、補強工事が必要と思われる施設について、個々に具体的にお伺いをします。そこで、一連の経過と、耐震診断の結果によっては、補強工事が必要となると思いますが、この見通しについて教えてほしいと求めました。","respondent":"日下部企画部長","answer":"施設の所有権を保有しておりますので、費用負担も含めまして、すべて東京都の責任において実施をするということになっております。平成２３年度に実施設計、平成２４年度には工事を完了させる予定であると、こういうことで承知をしています。","id":"exchange-059"},{"speaker":"堺委員","kind":"確認","question":"２点目ですが、二葉保育園、二葉図書館、区営住宅、この複合施設について、確認をしておきたいと思います。このように思いますが、この辺の見通しについて、それぞれご見解をお伺いいたします。","respondent":"日下部企画部長","answer":"具体的な説明を行い、工事の実施に向けまして、適切な対応をしてまいりたいと考えております。２回にわたりまして保護者説明会を開催しておりまして、荏原第三中学校の校庭の一角に仮移転するという予定で準備を進めているという状況です。","id":"exchange-060"},{"speaker":"堺委員","kind":"確認","question":"たしかここには３３世帯の方が入居されてありますけれども、場合によっては入居者が一たん仮移転先に転居するのかと思いますが、その辺の状況。保護者への周知と工事期間中は、その辺について、ちょっと確認をしておきたいと思います。","respondent":"日下部企画部長","answer":"仮移転をしないで済むような工事方法を前提に検討を進めているということでございまして、ご説明をするということで、適切な対応を図ってまいります。昨年２回にわたって保護者説明会を、工事期間中は、平塚小学校の跡地の一角に仮移転をするということで予定しているものです。","id":"exchange-061"},{"speaker":"堺委員","kind":"質問・要望","question":"ここは、昭和５４年度に建築確認申請がされているこのマンションに、昭和５６年４月１日に水神児童センターは開設されまた。対応が大変難しいかとは思いますが、この現在の状況を含め、今後どのように取り組んでいかれるのか確認をしておきたいと思います。","respondent":"日下部企画部長","answer":"小関児童センターにつきましては、この３月から補強工事に着手をしておりまして、８月には完了です。管理組合において、耐震診断の実施について検討を進めているという状況ですので、今しばらくはこの動向を注視してまいりたいと考えているところです。","id":"exchange-062"},{"speaker":"堺委員","kind":"質問","question":"検討を進めているですので、検討経過を待ちたいと思います。耐震補強工事が必要な８カ所の耐震化計画が、早急に計画案を示されるべきではないかと思いますが、ご見解をお伺いいたします。","respondent":"日下部企画部長","answer":"今、ご質問にありました区営住宅、それから、品川区の場合は、子どもの施設を優先して、急ピッチで耐震化を進めてまいりました。早い段階でお示しできるように、今後、できるだけ頑張っていきたいと考えているところです。","id":"exchange-063"},{"speaker":"堺委員","kind":"質問・要望","question":"公共施設有効活用プラン策定費との関連でお伺いしておきたいと思うんですが、ぜひ策定をしていただきたいと思うわけですが、これについてのご見解をお伺いいたします。","respondent":"日下部企画部長","answer":"ハード面の整備の方針ですけれども、どちらかというと、ソフト面の対応が中心になってくるというものです。ご質問にございました、より効果的、そして効率的なサービスの提供につなげてまいりたいと考えています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"３本目の柱、保育園の待機児解消については、どうでしょうか。うち認可保育園の増設によって増える枠は何人でしょうか、ご説明ください。","respondent":"古川子ども未来事業部長","answer":"そういう中では、この４月の入園に対しまして、３００名余の定員の拡大を図った。今年度内に５００人を超える認可保育園の定員の拡大、これが大きな内容であると、このように考えてあります。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"うち、認可保育園の増設による受入枠の増は幾らでしょうかと聞いたので、答弁漏れなので、お願いします。","respondent":"古川子ども未来事業部長","answer":"認可保育園は、６月に第一日野幼保一体施設として、西五反田第二保育園が開設いたします。１３０人の定員を考えてあります。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"この４月の認可保育園入園を希望した申込者数は何人でしょうか。あわせて、４月１日の認可保育園の全子ども数、何人になるのかも伺います。","respondent":"古川子ども未来事業部長","answer":"数字のことですので、少しお時間をいただきたいんですが、この４月の認可保育園を希望した申込者数ということなんですが、これは非常に難しいんです。４月になってみないと、全体が見えてこないです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"私は、事前に入園者数、申し込んだ方は何人ですかとお伺いしましたところ、区が出した数字が１,８９１人ということです。今現在、どのような申込み数の想定をしているのかも、伺います。","respondent":"古川子ども未来事業部長","answer":"約１,７００名ぐらいかなというような、品川区に対する入園の希望があったと考えてございまして、今回の緊急対策はどこまで対応できているか。大変申しわけございませんけれども、まだあと１０日余の中で、最終的な数字は固まっていくだろうと考えております。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺いたいんですが、今後の対策として、こういう４９４人もの５００人近くの方、どうするんでしょうか。５００人近い未入園児は、この区の対策で、これから解消できるのかどうか、解消するつもりがあるのかどうか伺います。","respondent":"古川子ども未来事業部長","answer":"転園希望者も入った上での４４３人ということで、４月以降に、私はよく承知してございません。国の認可基準を守っていながら、詰め込みという言葉については、理解できません。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"細かい数字のやりとりというか、認識の違いはあるかもしれませんけれども、少なくとも５００人近い方が未入園児なんです。その方をどうするのか、解消できるのですかということを伺いましたので、もう一度、伺います。","respondent":"古川子ども未来事業部長","answer":"先ほど来、申し上げていますけれども、５６３人が未入園児ではございません。先ほど来、申し上げているんですが、よくご理解いただけないのが残念です。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、それをどうするんですか。解決するつもりがあるのか、できるのか、区の対策で、これからどうしていくのかということを伺っているので、誠実にお答えほしいと求めました。","respondent":"古川子ども未来事業部長","answer":"転園の正確な数字は、まだよく見えていない部分もありますし、内定をした後に、辞退が、この１０日間でまた出てくるだろうと考えています。今度は繰り上げの内定も出てまいりますので、なかなか明らかにできないということについては、ご理解をいただきたいと思います。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"いろいろ言われますけれども、結局、区の姿勢は、努力はするんだけれども、解消できるかどうかわからない、知らないという姿勢だと、私は思います。自治体の責任に照らして、いかがでしょうか、答弁を伺います。","respondent":"古川子ども未来事業部長","answer":"６月、９月の部分もありますけれども、ぜひご認識をしていただきたい。認証保育所が３０名で２カ所の予定もされておりますし、もし４月１日の中での待機児をどうしても、さまざまな方策を持って相談に乗っております。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした現状へのさらなる詰め込みの子どもへの影響を、どう考えているんでしょうか。子どもの成長に支障をきたしかねないと思いますが、どうなんでしょうか、伺います。","respondent":"古川子ども未来事業部長","answer":"既存の保育園で、２０年前、少なくとも数年前までは、待機児ではなくて、欠員対策が、私の当時の保育課長時代の仕事でした。どのような環境であっても、品川区の保育士たちは受けいれた子どもに対して等しく、きちっとした保育をやってくれると、このように信じております。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"子どもたちへの影響をどう考えているのかと伺ったんですけれども、その答弁がないんですね。これが子どもの育ちにどういう影響を与えるのかという検討をされているのかどうか、どのように考えているのかを、もう一度お伺いします。","respondent":"古川子ども未来事業部長","answer":"しかしながら、それを補う保育士の力量も、そして、さまざまな手法によって、子どもには何ら影響は及ぼさない、そういう保育をやっていく予定です。よくお考えいただきたいんですが、それを４月において、これは国の方針なんです。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"どういう意味なんでしょうか。さきに紹介した深刻な願いを、我慢をしてもらわなくてはいけないぐらい深刻なものなんか尋ねました。","respondent":"古川子ども未来事業部長","answer":"保育園の需要については、２０年スパンで考えて、あるいは１０年でも相当変わってくると考えています。これは、財政負担を極力減らしながら、最大の効果をねらっていると、このようにとらえていただければと思います。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"最小の経費で最大の効果というよりも、親としては、認可保育園をつくってくださいという請願も上がりました。なぜつくらないのか、財政上問題があるというのだったら、どういう問題なのか、全然説明してないので、説明を求めました。","respondent":"古川子ども未来事業部長","answer":"その負担を最大限生かしていく手法をとって、この４月、あるいは９月までに５１０人の定員の拡大を図ってまいります。各年１園ずつつくってまいりますし、認可保育園についても一定の数の確保をしていく、この考え方です。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"期間限定でも、あとに老人ホームに変更になるのでもいいではないですか。今、このときに、認可保育園の大幅増設で待機児解消を強く求めまして、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"菊地委員","kind":"質問","question":"お聞きしたいのが、まず１点、お聞きしたい。それからもう１点、こうした超高層のビルだらけのまちづくりというのが進められるのか、という点をお聞きしたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"建ぺい率の既存の用途地域からの変更は、一律にかかっております現在の用途、容積がベースになります。もし目黒のような開発を考えるのであれば、その新たな地区を地区計画に位置づけて、法的手続をとる必要があります。","id":"exchange-078"},{"speaker":"菊地委員","kind":"質問","question":"その辺を、今、私はお聞きをしたんです。その辺をちょっと明確にお答え願えませんか。","respondent":"岩田防災まちづくり事業部長","answer":"ご説明申し上げましたように、その地区、その地区の駅の乗降客数と都市基盤整備の状況によって必然的に出てきます。事業者がこれだけの容積が欲しいとか、欲しくないとかということで上乗せられるとかという制度では、もともとないです。","id":"exchange-079"},{"speaker":"菊地委員","kind":"質問・要望","question":"明確にお答えいただきたいのは、どうか、ちょっとそこをはっきりさせていただきたいんです。それから、住むことのできる基準というのもお聞かせ願いたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"市街地整備基本方針というのを定めさせていただいたときには、駅前というのは、それなりの商業が集積する地区です。それはすべて、品川区の原点です市街地整備基本構想に基づいて、１１地区の望むべき地区のあり方に基づいて指導をしているです。","id":"exchange-080"},{"speaker":"菊地委員","kind":"質問","question":"事業者がつくり上げた計画をどうすれば実際に実行できるのかということを基本に置いて行われたものであり、当然のことながら、私は思っています。それから、住むところの基準というところをお聞きしたんですけれども、この辺ははっきりしたご答弁がなかったので、その辺をお聞かせ願います。","respondent":"岩田防災まちづくり事業部長","answer":"これは、品川区の昭和４０年代から流れをずっと考えていただければ、よくわかります。第１号の市街地再開発事業として東五反田二丁目第１地区が認可をされたですので、後からつけ加えたようなものではございません。","id":"exchange-081"},{"speaker":"菊地委員","kind":"意見","question":"区内に２万戸のストックがあると、住宅が増加したので、付置義務もなくしたと。あり得るべきなんだという話に聞こえてきますので、ぜひその辺、まず先にお伝え願いたいと思いますとの意見を述べました。","respondent":"岩田防災まちづくり事業部長","answer":"いわゆる道路や空地や、あるべき姿をどうつくるのかという、いわゆるまちづくりのベースの中で開発を考えるわけです。中地区については、ディベロッパーがきちっと床を取得されましたので、再開発事業は見事成功をしたです。","id":"exchange-082"},{"speaker":"菊地委員","kind":"質問","question":"今のマンション計画へ変更したのは２００５年ですから、わずか５年間、あそこで地上げを進めていた。それからもう１点、法人が所有する権利住戸数についても、お聞かせ願いたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"こういった開発需要のあるところは、区民の望むべきまちのあり方に誘導していくというのは、私は行政の責務だと考えております。何度もお答えさせてもらっていますけれども、住宅の処分ということは、私どもが心配してあげるというような立場にはございません。","id":"exchange-083"},{"speaker":"菊地委員","kind":"質問","question":"まちづくりに対して責任を持つ、そして売れないということに対しても責任を持つ、これが税を投入した行政の責任ではないでしょうか。この点は、再度、答弁を願いたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"その売却費と、かかった経費がプラスマイナス０できちっと精算をするというのは、法の事業になっております。行政が指導しておりますので、もしそういうお声があれば、ぜひ教えていただきたいと思います。","id":"exchange-084"},{"speaker":"菊地委員","kind":"意見","question":"ここでは、はっきりした答えがないんですけれども、建て替えが実際に、これから結局どうなるのか。こういう問いかけですので、この辺も、再度、答弁を願いたいと思いますとの意見を述べました。","respondent":"岩田防災まちづくり事業部長","answer":"大体５年から１０年で、全部プラスになるということで、いわゆる税の投入としては非常に効率的だと言われています。公開空地とか、こういったいわゆる準公共的なものについて補助金を出しているということを、ご理解いただきたいと思います。","id":"exchange-085"},{"speaker":"菊地委員","kind":"意見","question":"こうした７,０００万円からの高級住宅をつくり上げたわけですけれども、しっかりと方向転換をしていくことが必要ではないかと思います。保育園、こういうものの供給に使っていくべきだと思いますけれども、最後にこの点を説明を求めました。","respondent":"岩田防災まちづくり事業部長","answer":"例えば１００億円再開発事業でお金を使っている、１００億円、お金は出てこないんです。ここをよくご理解をお願いしたいと思います。","id":"exchange-086"},{"speaker":"菊地委員","kind":"意見","question":"今の話は、最後はどうでもいいよという話ですよ。全体を見て、しっかりとしたまちづくりをしていくべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"稲川委員","kind":"確認","question":"はじめに、震災に強いまちづくりについて、お伺いしたいと思います。このことは、たしか、私が以前に質問した中で、ご答弁、確認をさせていただいたと思います。","respondent":"岩田防災まちづくり事業部長","answer":"第１弾としては、もう少し深く突っ込んだ部分でいろいろやっていく必要があるということは、だんだん明らかになってまいりました。","id":"exchange-088"},{"speaker":"稲川委員","kind":"確認","question":"改めて確認をしたいんですが、先ほど、私が、密集住宅市街地の整備が進まない理由として、３点挙げました。明らかにその３点かどうか、それだけ確認のため、ご答弁をお願いします。","respondent":"岩田防災まちづくり事業部長","answer":"委員のおっしゃる、大きく３点、これも品川区はそのように考えております。先ほどいいましたように、もっと深く突っ込んだ中で、事業展開をしていく必要があると認識しております。","id":"exchange-089"},{"speaker":"稲川委員","kind":"質問・要望","question":"品川区の密集市街地などの事業施策をつくる上で、参考ということでお伺いしておりますが、参考にされております。今後必要と考えますが、その辺をいかがお考えか、説明を求めました。","respondent":"岩田防災まちづくり事業部長","answer":"４月から行います品川区マスタープランの検討の中では、その最終データを用いて、品川区のまちをもう一度細かく再検証していこうと考えております。品川区は４km四方しかございませんので、地域危険度というのは、都内を一斉に統一基準で見ていく必要があると考えております。","id":"exchange-090"},{"speaker":"稲川委員","kind":"確認","question":"確認なんですけれども、平成１５年の現況調査とおっしゃっていましたけれども、平成１３年でよろしいですか。住宅建物の耐震化率を７５％から９０％にするということが、お伺いしたところ、いかがか尋ねました。","respondent":"岩田防災まちづくり事業部長","answer":"これは所管の課長のほうからお答えしたケースだと思うんですけれども、耐震化率を、国の場合は出しています。２３区の場合も、マンションは１棟として数えて耐震化率を出しておりますので、若干違うということだったんだろうと思います。","id":"exchange-091"},{"speaker":"稲川委員","kind":"質問・要望","question":"火災を起こさないためには何をするべきなのか、建物が倒壊しないためには何をするべきなのか、その手法を考えていかなければならないと考えています。この密集住宅市街地の整備というのは進まないと考えていますので、その辺、いかがお考えか説明を求めました。","respondent":"岩田防災まちづくり事業部長","answer":"骨格はきちっと進めておりますけれども、少なくとも一人でも多くの人の命を助けようと、これが原点になります。そういうもので考えられる対策というのは、いろいろなものを考え出して、今後の施策を検討していきたいと思います。","id":"exchange-092"},{"speaker":"稲川委員","kind":"質問・要望","question":"１点、確認なんですが、設置をしていただきたい。品川区内には可搬ポンプが入らない密集住宅市街地が多数点在しておりますので、その辺だけ確認のためにお願いします。","respondent":"岩田防災まちづくり事業部長","answer":"これは、ご指摘のように、消防水利が不足している地区とか、あるいは、ポンプ車がなかなか中に入って行けない。消防と協議をしてまいりまして、地下貯水槽が必要ならば、貯水槽の設置という対策を打っていきたいと思います。","id":"exchange-093"},{"speaker":"稲川委員","kind":"質問・要望","question":"次に、地域見守り型の高齢者福祉について、お伺いいたします。それとも、品川区の公募などによって申込みがあったのか、ちょっと２点説明を求めました。","respondent":"木下健康福祉事業部長","answer":"世話人が緊急時の対応をするだけでしたけれども、緊急通報は当然のことでありますけれども、基本的に中廊下方式にいたします。区のほうでこういう施策を進めたいという中で、民間事業者の第１号として、モデル事業として新井湯が入って来たです。","id":"exchange-094"},{"speaker":"稲川委員","kind":"質問","question":"手続的にも、最大限のバックアップが必要と考えますが、いかがお考えでしょうか。竣工は平成２３年度ですが、区立型や区民型の高齢者優良賃貸住宅を整備していくお考えがあるか、どうか。","respondent":"木下健康福祉事業部長","answer":"積極的な支援ということでありますけれども、今回の新井湯を一つのモデルに、誘導基準みたいなものは考えていきたいと考えています。区としては、国土交通省のほうの高優賃制度の枠を基本に、必要な支援をしていくと考えております。","id":"exchange-095"},{"speaker":"稲川委員","kind":"質問・要望","question":"続きまして、待機児童対策について、お伺いをいたします。今回の待機児童解消策がウルトラＣであるのであれば、今後の施策をお持ちかどうか、改めてお伺いをしたいと思います。","respondent":"古川子ども未来事業部長","answer":"それにしても、需要にこたえるのは区の責務ですから、さらなる需要にまた対応していかなきゃいけない。これを中心にしながら、この４月の入園の動向をしっかり見極めた上で、また、次なる策を練っていきたいと考えています。","id":"exchange-096"},{"speaker":"稲川委員","kind":"質問・要望","question":"質問の最後になりますが、質問の第２と第３におきましては、高齢者福祉と保育について、私は、質問をしてまいりました。その件について、いかがお考えか、お願いします。","respondent":"古川子ども未来事業部長","answer":"しかしながら、それぞれよって立つ制度が異なりますので、直ちにそれを一体的にやるというのは、非常に難しいのかなと考えております。","id":"exchange-097"},{"speaker":"稲川委員","kind":"質問・要望","question":"これで私の質問を終ります。川西絹子委員にバトンタッチをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"川西委員","kind":"質問","question":"最初に、環境問題の基本方針について、区の姿勢を伺います。区の中で電気自動車や太陽光の導入等を計画しておりますが、区の基本方針について、伺います。","respondent":"久保田都市環境事業部長、日下部企画部長、市川教育次長","answer":"平成２２年度について、モデル施設の省エネ診断を行って、経費や省エネ診断の総合評価を行う予定になってあります。このことを踏まえて… 太陽光発電、それからＬＥＤ照明ということで、この設備の導入という方向で準備を進めているです。環境問題の視点から… 私からは、品川地区の小中一貫校、品川学園のエコスクールの概要について、説明します。","id":"exchange-099"},{"speaker":"川西委員","kind":"質問","question":"品川学園については、何kwぐらいなのか、簡単で結構ですから、お答えください。私は、全面的に太陽光エネルギー、自然エネルギーで実施設計をされるべきだと思いますが、いかがか尋ねました。","respondent":"日下部企画部長、市川教育次長","answer":"平塚小学校跡ですが、こちらの太陽光は、約１０kwということで予定しています。先ほどもお答えいたしましたとおり、いずれにしましても、検討してまいりたいと考えています。 品川学園の太陽電池パネルにつきましては、４kwのものを設置いたしまして、校舎内の電力使用の一部に充てていくことを考えてあります。","id":"exchange-100"},{"speaker":"川西委員","kind":"質問・要望","question":"やはり１０kw、２０kw単位で、区の計画は推進してほしいと、切にお願いをいたします。区のほうでは、これについては、どんなふうにお考えか尋ねました。","respondent":"久保田都市環境事業部長","answer":"エネルギー政策の分野に入るかと思いますけれども、現実に、原子力発電、日本の電力使用の３分の１、もう既に使っております。もう既に、そういう需要に対して供給しているという現状を考えれば、これは重く見る必要はあるだろうと感じております。","id":"exchange-101"},{"speaker":"川西委員","kind":"質問","question":"３年経った今、学校側はどのような理解を示しておられるのか、ということを一つ伺います。第１庁舎はなぜできないのか、なぜ、第２庁舎にしたのか、この２点だけ伺って、この件については終わりたいと思います。","respondent":"市川教育次長、市岡総務部長","answer":"最終的に学校施設としての教育環境を優先して考えたときに、太陽光設備を屋上に設置できない場合があるということで、説明をさせていただきました。こういう学校につきましては、太陽光発電による街灯を設置するなどして… 第２庁舎に導入した理由ですが、第２庁舎には、３階のロビーのダウンライトをＬＥＤに変えていこうという当初の計画です。今後また、その発展形ということで、いろいろ考えていきたいと思います。","id":"exchange-102"},{"speaker":"川西委員","kind":"質問・要望","question":"進めてきたわけですから、伺うところによりますと、今後もよろしくお願いいたします。ちょうど平成２３年から改修というような予定がされていると聞いておりますので、そのときに使わせてもらえば、まとめて質問させていただきました。","respondent":"日下部企画部長、本間副区長","answer":"ただ、関係者の要望、意見などにつきましても、十分に踏まえて対応してまいりたいと考えています。今後は、必要となります基本的な条件の整備をまずしっかりとやっていくというところからスタートしてまいりたいと考えているところです。 この間、何回となく、その後の検討状況等をお伺いしてきました。ご提案のような点も十分に踏まえながら、このグラウンドの有効活用について、関係団体等とも協議をしながら進めていきたいと考えているところです。","id":"exchange-103"},{"speaker":"渡部委員","kind":"質問・要望","question":"委託事業についてと、公有地、区の施設の有効活用について伺っていきますので、よろしくお願いいたします。漠然としておりますが、何をしていかなければならないのか、また何をすべきかのお考えをお示しほしいと求めました。","respondent":"古川子ども未来事業部長","answer":"こういうことをとらえますと、いかに乳幼児期における子育て環境が大切であるかということが、私ども認識できると思ってあります。地域、子どもにとって、このような思いで今後ともさまざまな青少年の健全育成についての施策をやっていきたいと考えています。","id":"exchange-104"},{"speaker":"渡部委員","kind":"質問","question":"学校施設においても、改築など整備がされた後も、それまで活動していた団体が従前どおり使えるのでしょうか。この２点お伺いします。","respondent":"古川子ども未来事業部長","answer":"やってきてはありますけれども、ますます場所の確保が難しい中で、私ども真剣に考えていく必要があるだろうと思ってあります。そういう施設を活用できないかどうか、これからもそれぞれ庁内の所管のところとも調整をしながら、検討を進めていきたいと考えています。","id":"exchange-105"},{"speaker":"渡部委員","kind":"質問・要望","question":"新たな計画が上がった場合は、早い段階で利用者に意見を伺って、要望をしっかり受けとめた上で設計に入っていただきたい。平成２２年度に子ども未来事業部の事務掌握や体制に変化があると伺っておりますが、区としてどのように進めていくのかを、示すよう求めました。","respondent":"古川子ども未来事業部長","answer":"結果はこれから４月中旬以降に出てまいりますし、さらなる角度から待機児解消策を積極的にとっていく必要があるだろうと考えています。は４月の状況をとらえた中で、今後の対応については、努力をしてまいりたいと考えています。","id":"exchange-106"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば私の伺ったところによる、教えていただきたいと思ったんですが、何かありますか尋ねました。","respondent":"山田副区長","answer":"組織内部的には、４月１日をもってこの待機児解消に向けて組織を挙げてやっていこうということで、担当課長を設置しまして、いわゆる組織の中、事業部だけではなく、全庁的な部分の視点で、これから方向性を検討していきたいと考えています。","id":"exchange-107"},{"speaker":"渡部委員","kind":"質問","question":"次に、まちのにぎわいづくりについて伺っていきます。ここで伺います。","respondent":"宮地地域振興事業部長","answer":"商業・観光課とものづくり・経営支援課の２課の体制をとったことで、あるいは観光施策に、とりわけ緊急経済対策には素早く対応しまして。地元商店街の空き店舗活用あるいは商店主向けの経営セミナーなどを実施するなど、より一層支援施策の充実を図っていきたいと考えております。","id":"exchange-108"},{"speaker":"渡部委員","kind":"質問・要望","question":"これらの来訪者に対して、品川の魅力をどのように伝えていけるのか、区は何かお考えでしょうか。新たな場所、人の集まる場所にそのようなものをつくればいいなと思っているんですが、あわせていかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"やはり商店街の空き店舗の活用などにつきましても、既に来年度、大井町地区で新たな取り組みが予定されていると聞いております。区としても支援をしてまいります。","id":"exchange-109"},{"speaker":"渡部委員","kind":"質問","question":"話し合い等の中で、今までなさった経験の中で、今後新たな何か展開は生まれそうでしょうか。このつまみ食いウォーク、事業発展の可能性はありますでしょうか、お教えください。","respondent":"宮地地域振興事業部長","answer":"いろいろな可能性を検討しながら、単発で終わらず、既に毎年９０から１００件ほどのさまざまなイベントを商店街としてやっております。","id":"exchange-110"},{"speaker":"渡部委員","kind":"質問","question":"商店街の人はいい人ばかりですから、今、部長のほうからご答弁いただきました一過性のものにしたくないんですね。これらにつきましては、平成２２年度以降にも続けていかれるのか尋ねました。","respondent":"市岡総務部長","answer":"施政方針の中で区長が申し上げましたけれども、まずは仕事を確保すること、このことが喫緊の課題だろうと考えております。現在の景況の回復には相当程度の時間がかかるという現実の中で、今後とも継続的に区内発注の拡充等に重点的に取り組んでまいりたいと思います。","id":"exchange-111"},{"speaker":"渡部委員","kind":"質問・要望","question":"次に、例えば現場の校長先生などにも、このようななるべく区の業者から買いますようにというようなお話はおりているのでしょうか。今現在はどうなんでしょうか、説明を求めました。","respondent":"市川教育次長","answer":"あるいは学校給食の食材で、区内業者から調達の可能なものについては、区内業者からの購入ということを基本にしています。ちょうど１年以上前になりますが、昨年度末から区が緊急経済対策を実施するに当たりまして、折に触れて。","id":"exchange-112"},{"speaker":"渡部委員","kind":"質問","question":"初めに委託事業と直轄の事業について伺います。判断にあたっては何か大きな指針があるのか、これら委託する事業の選定は区の裁量でそもそもできるものなのか、ここまでまず説明を求めました。","respondent":"日下部企画部長","answer":"行政がみずから直接実施する必要のないものについては、できるだけ民間に任せていこうといった考えをもとに民間委託を進めまして。仕事の継続性でありますとか、複数の事業者間の競争性が確保できるかといった点なども含めまして判断をしているというものです。","id":"exchange-113"},{"speaker":"渡部委員","kind":"質問","question":"今後の区政運営を行っていかれる中で、今、お話を聞きましたのは、いろいろ委託できる事業はあるんだなと思いましたので、いわゆる委託というものを事業的に増やしていくのか、逆に委託から区の直営に戻さなければならないようなことも起こり得るのか、説明を求めました。","respondent":"日下部企画部長","answer":"一方で少子高齢化への対応をはじめといたしまして、区の果たすべき役割と責任がますます大きくなってきている。町会、自治会、それからＮＰＯなどとの連携・協力を積極的に図っていく必要があるだろうと考えております。","id":"exchange-114"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここで働かれている区の職員が異動や退職をされた場合、どのような立場の方が職員として入ってくるのでしょうか。毎日ではなくとも、各校を巡回するなどして、後継者育成などをする体制はできないか尋ねました。","respondent":"市川教育次長","answer":"緊急時の対応なり、あるいはそのときどきの業務課題といったことについての共通理解、共通認識を深めておく。ご提案の件につきましては、現に一部、すまいるスクールのＯＢの活用ということで対応していますが、今後の参考とさせていただきたいと思います。","id":"exchange-115"},{"speaker":"渡部委員","kind":"質問","question":"今、例に示したところはわかりました。全体的なところとして、委託事業全般で事業継承などで苦労している点ですとか、このようにという点があればお示しいただけますか尋ねました。","respondent":"日下部企画部長","answer":"そういうところについては日々取り組んでいるところですので、その点をより重視しまして、今後ともしっかり取り組んでまいりたいと考えています。","id":"exchange-116"},{"speaker":"渡部委員","kind":"質問・要望","question":"１０年を前期・後期に分け推進しなければならない事業計画が示されていますが、これらをどのように具体化させていくのでしょうか、お示しください。あわせてこの長期基本計画に区民のニーズというのはどのように反映されていくのでしょうか、説明を求めました。","respondent":"日下部企画部長","answer":"そこで、事業の具体化にあたりましては、３年間の総合実施計画のローリングの中でより具体的な行程等を盛り込んでまいります。既に長期計画の中で、施設の需要見込み、区民ニーズの反映等を行っておりますけれども、今後の変化につきましてもきめ細かくとらえていく。","id":"exchange-117"},{"speaker":"渡部委員","kind":"質問・要望","question":"今後このプランに基づいて、公共施設の有効利用がされていくと思いますが、一つ複合施設についての区としてのお考えを示してほしいと求めました。戸越台中学校のように、高齢者福祉施設と教育施設の複合化など、今後推し進めるべきと思いますが、いかがか尋ねました。","respondent":"日下部企画部長","answer":"今後検討が一定進んだ段階で、これはもちろん議会にご報告をいたしますし、区民の皆様にもお知らせしてまいりたいと考えております。施設の多目的化、こういった取り組みが求められると思われますので、検討課題の一つとして取り上げてまいりたいと考えております。","id":"exchange-118"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後に要望して質問を終わりたいと思います。いずれの混乱も生じないように、新たな事業展開に対して、十二分保護者の方に説明と理解をいただくようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"そして、そもそものこの基金というものはどういうものなのでしょうか。今後の計画、そしてどういう計画で幾ら年数はどのようにしようと考えているのかお聞きしたいと思います。","respondent":"金子企画財政課長","answer":"これで基金の取り崩しを抑制しつつ、できる限り積み立てに努めていこうと考えております。なお、基金のうちの財源対策に活用できます財政調整基金については、今後特に重視していこうという考え方です。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、なぜ基金という形の中に入れられるのかというところは、どういうことを区がされているのかというところのご説明をほしいと求めました。区はどういう考えを持って対応していくのか、それから事業の選択の基準はどういう考え方で選択をしていくのかについてお聞きいたします。","respondent":"金子企画財政課長","answer":"区の負担を増加させても必要であるかどうかということで、その継続性を、あるいはその事業の実施について判断しております。まさにこの場合には区としては絶対に必要な事業であると考えておりますので、負担を増加させても実施すべきと判断しているものです。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほど区長から答弁もありましたけれども、維持していただくものは維持していただくということを頑張っていただきたいと考えています。そして公表の仕方はどうしていくのか、自己評価というだけではなくて、ほかの手法を考えているのかどうかの見解をお聞きしたいと思います。","respondent":"日下部企画部長","answer":"１つはやはり事業の必要性がどうか、それから実施主体のあり方ですね。実施計画のローリング、具体化を図っていくと、このように考えております。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"協働事業というのは、昨年度からでしょうか、かなり協働事業というのは財政効率にも非常に貢献するのではないかと期待をしているわけです。採用は何件で、採用されなかった理由、採用した事業を行ってどのような成果があったのかをお聞きしたいと思います。","respondent":"日下部企画部長、宮地地域振興事業部長","answer":"こうした考え方を基本に評価を進めてまいりますけれども、ＮＰＯ、区民との連携・協力を積極的に図っていきたいと考えております。そしてこれをもとにしまして、区民の皆さん方に対して十分説明をし、理解をしていただく… 自治会などの支援団体からこれら多様な団体まで、具体的な協働事業を実施することで、この基本構想の実現を目指すこととしたものだと考えております。第１次審査は書類審査、第２次審査は事業提案説明という形になっております。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"今、採用された件数をいただきましたけれども、採用されなかった理由はいかがでしょうか。ちょっと答弁漏れがあったように思いますが。","respondent":"宮地地域振興事業部長","answer":"失礼いたしました。町会と一緒になって事業を実施するといった計画でありましたが、協働でやる必要はないといったような内容のもの等がございました。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれの団体の支援の考え方というのをお聞きしたいということです。こういうのがありますけどいかがでしょうかというような、プッシュ型の周知方法を考えてほしいと求めましたが、いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"その後は広報でのＰＲやホームページでの紹介、あるいは活動に対する支援の相談などもやっていっていいのではないかと考えております。そうしたところのアプローチ、いろいろな媒体を使って積極的に展開していきたいと考えております。","id":"exchange-125"},{"speaker":"西本委員","kind":"提案","question":"そして全国的に問題となっています、今までもたくさん質問が出ておりましたが、待機児解消のための新たな政策についての提案をしたいと思います。","respondent":"古川子ども未来事業部長","answer":"子育て支援のあり方というのは大変難しいものだと。保育園においては、こういう観点は常に保育園の園長あるいは保育士が念頭に置きながら、親とさまざまかかわりを持っているです。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"平成２２年度の予算の中にもありましたけれども、中小企業のワークライフバランス支援とか、こういうものを大いに推進してほしいと求めました。その目的と、どのような成果を期待するかをお聞きしたいと思います。","respondent":"古川子ども未来事業部長","answer":"こういう中から、保育園におきましては、ＰＴＡの事業といたしまして、家族そろって朝ご飯運動を実施しています。平成２２年度からはすべての公立保育園でこれを実施したいと考えています。","id":"exchange-127"},{"speaker":"西本委員","kind":"提案","question":"一つの提案としては、一番今、簡単に使われています携帯電話を使った方法ですね。これについてのお考え、そしてぜひモデル実施という形でしていただけないかなという提案をいたしますが、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"携帯電話の可能性についてはさまざまな角度から、ご提案ではありますが、検討していく余地があるのかなと考えています。すぐにというわけにはまいりませんけれども、それぞれの利点をまたとらえながら、全体の中で検討していきたいと考えております。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり忙しいですから、それを補完する意味でも、いろいろな情報ツール等々を使って伝えていただきたいと考えています。そして品川区でもぜひこの時期に、区民との協働でイベントの開催などを公募して実施してはいかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"一方では品川区で、昭和４９年ですが、これは青少年問題協議会の中での一つの事業ですが、毎月第１日曜日を家庭の日と定めました。そして家族団らん、地域の支え合いといったことにつきましては、積極的に考えていきたいと思ってあります。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"それだけ取り組みがどうだったんだろうという反省もあるかと思いますけれども、家族の週間という形で、ぜひとも取り組んでほしいと求めました。そしてこの保育政策における子育てネットワークの大切さということについて、ご見解をお聞きしたいと思います。","respondent":"古川子ども未来事業部長","answer":"いずれにいたしましても、地域が支えあっていく子育て環境は間違いなく必要なものだろうと思ってあります。保育園や幼稚園、そこに集う人たちが何らかのネットワークをつくれるような、そういう環境づくりにこれからも支援をしていきたいと考えています。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問・要望","question":"幼稚園はわりかしネットワークがありますけれども、どうも保育園の親たち、そのＰＴＡの役割というのが少し少ないのではないかなと考えています。そして交流の場であるものを少しつくっていただきたいなと思いますが、その見解もお聞きいたします。","respondent":"古川子ども未来事業部長","answer":"先ほどからさまざまな形でのネットワーク、そして保育園におきましては、それは１つにはＰＴＡということでの結びつきだろうと思ってあります。ＰＴＡを通してさまざまな形で交流の場ができるように、保育園の中でもそういう仕組み、あるいは仕掛けをしていければと考えています。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問・要望","question":"足りないのは０・１・２歳です。人口の推移から、区施設の転用であるとか、それから運営などのほかの方法を考えてほしいと求めましたが、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"しかしながら、０・１・２だけの施策というのも、また全体の５歳児までの成長を考えますと、なかなか難しい部分もあります。いずれにいたしましても、今回の入園の結果を見ながら、さらなる必要な待機児解消策については何らかの方策をとっていきたいと考えています。","id":"exchange-132"},{"speaker":"井上委員","kind":"質問","question":"予算の考え方、障害のある人の社会参加、子どもの育つ環境、以上３点について伺っていきます。そこには市民の満足度、福祉向上という基準は、どのように生かされているのかお伺いしたいと思います。","respondent":"金子企画財政課長","answer":"この３年の中期計画である実施計画に基づいて、各年度ごとの予算を定めております。防災まちづくり事業部では８本、これもちょっと大きく数えますが５本と、一応こういった本数になります。","id":"exchange-133"},{"speaker":"井上委員","kind":"質問","question":"２００９年、２０１０年と、計画策定にコンサルタントがかかわっている件数と金額をそれぞれお伺いいたします。委託内容や程度について、どのような仕組みがあるのか、また区のコンサルタント委託の考え方についてお伺いいたします。","respondent":"日下部企画部長","answer":"計画策定についての基本的な考え方ですけれども、臨時的に策定するというものについて、コンサルタントを活用する。このような業務を対象に、コンサルタントの活用、計画策定を図っているというものです。","id":"exchange-134"},{"speaker":"井上委員","kind":"質問・要望","question":"計画については、計画策定のコンサルタントは考えていただきたいなということを要望しておきたいと思います。障害のある人の社会参加の意味合いを、区はどのようにとらえられているのかお伺いいたします。","respondent":"木下健康福祉事業部長","answer":"あるいは鉄道駅のバリアフリー化、そのほか外出移動支援、道路・公共交通におけるルール・マナーの徹底などの施策を進めているということであります。","id":"exchange-135"},{"speaker":"井上委員","kind":"質問","question":"成果と課題をどうとらえているのか、この事業はどういう事業の内容なのか、対象者人数と定員を伺います。利用できなかった人がいるのか、もしいたとしたら、その方たちにはほかにどのような対応をされているのかお伺いいたします。","respondent":"木下健康福祉事業部長","answer":"障害者生活支援センターを既に整備してありますし、就労移行支援というサービスメニューをそろえておりますけれども、特別支援学校ですが。３５名、就労移行支援は身体、知的合わせまして２０名という枠になっております。","id":"exchange-136"},{"speaker":"井上委員","kind":"質問・要望","question":"定員以上の方がいると思いますので、定員から漏れた方たちはどういうところで対応されているのかということをお答えほしいと求めました。それだけ１つお願いいたします。","respondent":"木下健康福祉事業部長","answer":"ただ今回、３月に特別支援学校を卒業される方が、心身障害者福祉会館の自立訓練センターだけでは受け入れが難しいという事情がございました。","id":"exchange-137"},{"speaker":"井上委員","kind":"確認","question":"地域生活支援事業の２００９年度の決算額と、そのうち国と都の補助金は幾らになっているのか伺います。世帯の中に適当な介助者がいない人とは、どういう状況の方を指すのかお伺いいたします。","respondent":"木下健康福祉事業部長","answer":"移動支援の部分につきまして、１８歳未満の方が１名、合計７０名になります。居宅介護のほうで対応をしておりまして、こちらが５５名、１８歳未満の方はおられません。","id":"exchange-138"},{"speaker":"井上委員","kind":"質問","question":"この事業の対象者が重度視覚障害者と、そこで身体障害者の方がそこに入らない理由はなぜですかということと、世帯の中に適当な介助者がいない人というのはどういう状況の方ですかという質問を先ほどさせていただきました。","respondent":"木下健康福祉事業部長","answer":"そういうことがなかなか難しい、例えば親御さんが病気等で体が不自由だとか、そういうケースについてガイドヘルプをやってきたという経過があります。平成１５年から公的給付としていわゆる支援費制度のほうに乗りかえがされましたので、その結果であると理解しております。","id":"exchange-139"},{"speaker":"井上委員","kind":"質問・要望","question":"今までは１８歳未満は児童福祉法、１８歳以上は身体・知的・精神という法律の中で、一生涯を通じて支援できてこなかった。あわせて対象者も移動が困難という固有ニーズに対応してできるように改めてほしいと求めましたけれども、見解を伺います。","respondent":"木下健康福祉事業部長","answer":"その部分についても、いわゆる地域生活支援事業の別枠ではありますけれども、一定の公的給付で対応するようにいたしました。それは家族だけの責任ではなく、社会全体で支えるということが必要なことだと考えていますので、適宜検証を今後ともしていきたいと思ってあります。","id":"exchange-140"},{"speaker":"井上委員","kind":"質問・要望","question":"区には当事者からどのような支援を求める要望が出されているのか、またその要望に対して区はどのように回答しているのか。１８歳未満のケースでお答えいただきたいのですが、それぞれの給付で、申請に対して給付決定の割合はどのように推移しているのか、説明を求めました。","respondent":"木下健康福祉事業部長","answer":"この部分につきましては、例えばにじのひろば、それから福栄会のほうで、ナイスデーサポートという形での対応をさせていただいているところです。いろいろご相談がある中で、現在のサービスの中で適切に対応できるものについては支給決定をしているというふうに理解しています。","id":"exchange-141"},{"speaker":"井上委員","kind":"質問・要望","question":"そのことをお伺いしたいということ、誤解が生じないためにも、透明化を図って事業をしていただきたいと考えています。支給をするかしないかという文書で回答をするというルール化も必要ではないかと思うんですが、その辺の見解もあわせてお伺いいたします。","respondent":"木下健康福祉事業部長","answer":"その辺は引き続き丁寧な対応に努めていくようにしたいと思います。自立支援協議会というのを法律上つくることになっていますので、それからケアマネジメントの中の困難ケースについての具体的対応。","id":"exchange-142"},{"speaker":"井上委員","kind":"質問・要望","question":"申請書で出された場合には要望の蓄積にもなりますし、ぜひ前向きに検討していただいて、透明化を図っていただきたいということを要望します。３点目には、品川区が進めようとする幼保一体施設のビジョンが何なのかということをお伺いしたいと思います。","respondent":"古川子ども未来事業部長","answer":"幼稚園的な教育をどのように施していくか、そして地域の子育て支援を行っていくか、この３つの課題に対するのが認定こども園です。そして必要な方には長時間保育を、この観点に立って先行的に幼保一体施設を取り組んだと、このように考えてあります。","id":"exchange-143"},{"speaker":"井上委員","kind":"質問","question":"第一日野幼稚園の幼保一体はどういうふうに違うのか、説明してください。品川区が進めようとする総合型のビジョンが、第一日野幼保一体施設ではどのように生かしていこうとされているのか、区の考え方をお伺いいたします。","respondent":"古川子ども未来事業部長","answer":"幼保連携型の並列型というふうに国は提示していますけれども、０歳から３歳児までの保育園があって、このように考えております。０歳から５歳児までの保育園機能を持つことによって、一つの目的です待機児解消に大きく資することができる、このように考えてあります。","id":"exchange-144"},{"speaker":"井上委員","kind":"質問・要望","question":"ほかの対策を取り入れていくべきと思いますが、見解を伺います。どのように取り組んでいかれるのか、お考えを伺います。","respondent":"古川子ども未来事業部長","answer":"品川区の保育園は必ずしもすべての施設が余裕があるわけではありませんけれども、１９園において定員の拡大を図った、このように考えております。そして弾力化を継続することなく、保育士を４月１日から正式に採用し、このように考えてあります。","id":"exchange-145"},{"speaker":"井上委員","kind":"質問・要望","question":"第三者評価は承知しているんですが、そこで子どもがどういうふうに育っているのか、しっかりと評価していただくように要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"鈴木委員","kind":"質問・要望","question":"平成２２年度予算におきまして、我が会派が１７０項目にわたり区長に政策要望いたしましたプレミアム商品券発行、防災対策など。予算執行、また行財政改革の推進が図られることを強く要望し、品川区一般会計ほか４会計予算原案に賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"武内委員","kind":"提案","question":"私どもの要望した女性特有がんの無料クーポン券による検診の継続をはじめ、その他、また我が党がこれまで提案してきた認証保育所保育料助成の拡充や。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問・要望","question":"介護保険特別会計は基金が２３億円にもなりましたが、サービス抑制の改善、特養ホームの早急な増設を重ねて求めます。品川区は非核宣言２５周年、改めて非核宣言を世界各国政府に送付して、核廃絶を訴えること、核兵器廃絶運動を先頭に立って進めるよう求めるものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"土井委員","kind":"意見","question":"環境先進都市としての省エネに加え、新しい「創エネ」やＣＯ2吸収策に期待します。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区は雇用の創出や、未来を担う子どもたちのために、学力や教育環境の向上に向けて、今後全力で取り組んでほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"西本委員","kind":"提案","question":"品川区がしなければならない行政サービスがどういうものなのか、住民と合意を図りながら見直しをしなければならない時期に来ていると考えます。我が会派で提案、要望した各項目について積極的に受けとめていただき、区政運営に生かしていただくことを願いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-152"},{"speaker":"市川委員","kind":"提案","question":"国の制度をどう使うか、また制度の発展をどう方向づけていくかという積極的な姿勢が、これからの基礎自治体に求められていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/998976?Template=document&Id=942#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":145237,"voices":327}},{"id":"h22-20100325-10","meetingId":"h22-cm03","date":"2010年3月25日","dateIso":"2010-03-25","committee":"議会運営委員会","time":"午前１０時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"平成２２年請願第１号、教育都市の実現をめざし、本会議議場において国旗の掲揚を求める請願","agenda":"平成２２年請願第１号、教育都市の実現をめざし、本会議議場において国旗の掲揚を求める請願","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"わかったら伺いたいんですけれども、平成１１年８月１３日に制定され、こういう要請というのは来ているんか尋ねました。","respondent":"桑村区議会事務局長","answer":"平成１１年当時のもので、開庁日及び祝日に、庁舎における国旗の掲揚に努められるようお願いいたします。これは通知が都道府県知事あてに来ていますので、これは、通じて区にも来ているものというふうに想定されます。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこら辺の認識というのはどういうふうなお考えなのか、そこら辺のところはどういうふうに受けとめているのかというのを、考えがあったらお聞かせほしいと求めました。","respondent":"桑村区議会事務局長","answer":"いわゆる開庁日、また祝日に国旗掲揚していますし、また行事等においても基本的には国旗あるいは区旗を掲揚しているところだというふうに思います。","id":"exchange-002"},{"speaker":"土井委員","kind":"確認","question":"この事実をやっぱりしっかりと確認をしておく必要はあるだろうな、また、それをやはりこれからも続けるわけですから。それと同時に、私自身としては、国旗におしりを向けて論ずるという気にはなりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"松澤委員","kind":"意見","question":"今組織ぐるみの選挙違反で有名になっている北海道教職員組合の北海道、あそこではやっていないところがあるんじゃないかという話が相当出ているんですけれども、理事者がつかんでいましたらお知らせくださいとの意見を述べました。","respondent":"桑村区議会事務局長","answer":"正直言いまして、ここに書かれている１００％というものを調べているわけじゃありませんので、どこの県でどれぐらいの率というような形では調べておりません。","id":"exchange-004"},{"speaker":"松澤委員","kind":"意見","question":"私は毎朝来ると、庁舎のを見ながら、ああ、いい天気に翻っているななんて思いながら入ってきますけども、私はこれはあっていいと思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"若林委員","kind":"意見","question":"歴史的な部分も含めて、国論を二分という話も出ましたが、またそういう尊敬の思いとかというのはあるというふうに私どもは理解をしております。以上、会派の意見として申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"そういう伝えていただくという義務を負っているんじゃないかと思います。これに対して、戦争とか何かまた軍国主義に至るとか、そういう気持ちを持つこと自体が私は間違っていると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これを議会というのは、いろんな方々を代表して来ているところですから、やっぱりあってはいけないということが私は大前提だと思うんですよね。やっぱり区民のいろんなさまざまな気持ちを代表している議会だからこそ、一方の意見を強制するということがあってはならないというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"何とかのためでないときは、それを無視したら日章旗が問題、なんでしょうかね。考えたりしていかなきゃならない課題だろうな、このように思いますので、我々としては今答えを出すべき必要はないというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"もしわかりましたら教えていただきたいんですけども、絵画ですとか区のお知らせですとか、そういうものは一切掲載をされていない。この辺の、どこの議会を見ても、この辺はどうしてなのかというところをちょっと事務局としてわかりましたら教えてほしいと求めました。","respondent":"桑村区議会事務局長","answer":"そういう意味では、いろいろなものはなるべくやらないでシンプルにしているのが各議会の状況なんだろうというふうに思います。ただ、これはそこの議会が決めればいいという判断だろうと思いますので、そこの議会、議会の判断があろうかというふうにはもちろん思います。","id":"exchange-010"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"本当に公正中立という立場が求められる場所なんだというふうに思います。ですから、やっぱり公正中立の立場に立つべき本会議場で、これらが掲揚をされるということは、現状ではあってはならないことだと私も思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"そして、今回この掲揚することによって、国民に何が不利なことがあるんですか。いや、生活が大変だ、そんなことはあるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"それぞれ因果関係というんですかね、理屈の上でこれはどうつながっているか、私にはよくわからない。これ以上言っても同じようなことになりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"意見","question":"本来であれば、国旗国歌法を国会で議論するときだって、もっと多く議論してほしい。それで、私はこの請願は不採択にすべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"いろいろお話を伺って、そのときは請願という形でなくて、その中で討論というか議論をして終わったという経緯だったように感じています。ですから、取り扱い方をどういうふうにするんだということも整理していかないと、どっちかに答えを出していかなきゃいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"ですから、私はもう少しやり方から含めてという意味で、継続にして対応したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"採択かどうかというのは不採択にすべきだというふうに考えますけど、もしそういう意見が多いんだったら継続ということでいいんじゃないかと思います。今日もこっちの請願のほうの追加でプラス２０人ですかね、そういう意味で、署名の数も拮抗しているというふうに思うんですけどね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"先ほどから申し上げていますように、本日結論を出すべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/868696?Template=document&Id=5130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":11836,"voices":31}},{"id":"h22-20100326-5","meetingId":"h22-cm03","date":"2010年3月26日","dateIso":"2010-03-26","committee":"総務委員会","time":"午後２時２４分～午後２時３７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"区のほうとしてはどういうふうに見ているのかというのをまず伺いたいのと、大体どのぐらいあるのかというのがわかったら伺いたいと思います。今回、どういうふうにやったのかということもあわせてちょっと伺いたいと思います。","respondent":"阿部経理課長","answer":"３点目の、では、不調になった場合どうするかということですけど、その原因がどういう点にあるのかによってその対応が変わってきます。ですから、その原因によってさまざまな対応をしていくです。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"積算といいますかね、そういうところの評価といいますか、そこら辺というのはやっぱり入札をやってみないとわからないということになるんでしょうか。そこら辺はどうなんか尋ねました。","respondent":"阿部経理課長","answer":"ただ、申し上げたとおり、土木的な要素が大きいものですから、土木業者の場合と建築業者の場合の積算の仕方は若干違うと。そういう意味では、それはあくまでも申し上げるとおり適正な積算をしますけれども、業者の積算の仕方が違うということで今回のような形になったです。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。そうすると、それまでは、グラウンドというのはどういうふうになるのか尋ねました。","respondent":"阿部経理課長","answer":"現在はグラウンド、一番最後の図面でちょっとご説明いたしますけれども、現在は解体プールと書いてあります。ですから、校庭が全くないということではございません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、図面でいくと、この白い部分、プールの周りを使っている、そういう感じなんか尋ねました。","respondent":"阿部経理課長","answer":"解体工事は地下を掘ってありますので、その上にふたを乗せて校庭として使っているです。","id":"exchange-004"},{"speaker":"土井委員","kind":"意見","question":"工事をする時間帯とか、それによっても値段が違うわけで、そこら辺に何か違いがあったのかなかったのか聞かせてください。それはいつごろだったのかということと、今回このようにすぐ工事になるとは思わなかったのかもしれないけど、その辺だけちょっと聞かせてくださいとの意見を述べました。","respondent":"阿部経理課長","answer":"今回の擁壁の中で、解体擁壁と書いてありますけれども、ここが段々になっているところです。ここを今回解体いたしましてグラウンド整備しますので、それで土留めを打って支障ないようにするです。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1848#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":4190,"voices":27}},{"id":"h22-20100331-7","meetingId":"h22-cm03","date":"2010年3月31日","dateIso":"2010-03-31","committee":"厚生委員会","time":"午後１時０８分～午後２時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"第５０号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第５０号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"というのは、明日から施行される。区民に対しての周知はどうするのかとか、その辺について、区としてはどのような考えでいるのかというところをご説明ほしいと求めました。","respondent":"本城国保医療年金課長","answer":"大体２月の半ばぐらいまでには出そろうことが多かったものですから、２３区全体でも厚労省、タイトなことにならないように法令等の制定を迅速にしていただくように重ねて要望してきたところです。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"２月には上程されて何らかの形で準備をする段階、そういう流れで来たと思うんですけれども、今回は閣議決定が２６日ですよね。今、区のほうではどのような形で周知の仕方を考えているのかというところを再度お聞かせほしいと求めました。","respondent":"本城国保医療年金課長","answer":"ある程度下準備的なものはしつつ、今回のことを受けて、これから本格的にＰＲを図っていく予定です。リーフレット等を送らせていただいておりますが、その中に今回の条例改正の内容を踏まえたものを送付して、ＰＲしていくことを予定しています。","id":"exchange-002"},{"speaker":"山路委員","kind":"質問・要望","question":"そして、例えば明日、医療機関に行かれた場合に、医療にかかった人は高くなるわけですよね。そういうことを考えますと、医療機関にはどこまで徹底をされているのか、話をされているのか、その辺についても聞かせてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"今回の改正内容といたしましては、保険料をご負担いただく関係がありますので、医療機関での窓口負担等の影響は、今度の改正では変更するところではないようになっておるところです。","id":"exchange-003"},{"speaker":"山路委員","kind":"意見","question":"先ほどの区民に周知というのは、先ほどの話でこれからやっていく、パンフレット等を配るということですけど、周知されるのは広報、あるいは町会連絡で、大体どれぐらいで区民が周知すると考えていらっしゃるか聞かせてくださいとの意見を述べました。","respondent":"本城国保医療年金課長","answer":"一番基本的な周知方法としては、直接被保険者のほうにご配布するという形で、具体的な方法としては「こんにちは国保」、あるいは「わかりやすい国保」というリーフレット等の形で、早急にＰＲ、配布していきたいと考えておるところです。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"非常に心配ですけど、先ほども出ましたけれども、こういうことにならないように、区のほうからも国のほうに再度要望していただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"その返還するお金というのは、区民の負担なのか、それとも区の一般財源なのかというのをお伺いします。今回の値上げで、区民生活への影響というのを区はどのように考えているのかお伺いします。","respondent":"本城国保医療年金課長","answer":"その対応についてですが、そして一般財源から繰り入れる分、そのように大きく分けて三つの形の財源構成になっているところです。いろいろな困難を抱えている状況も当然あろうかと思いますが、保険料が保険財政を支える柱だということでご理解いただきたいと思っているところです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"値上げの中止を求める請願が区内の中小、零細企業団体の皆さんから上がったわけですけれども、国保料が。自営業の皆さんに限らず、給与所得も下がっている中、どうしてこれは毎年値上がりを続けていくのかお伺いをいたします。","respondent":"本城国保医療年金課長","answer":"それから、これについては冒頭ご説明させていただきましたことと重なりますが、医療給付費が年々上昇するものを保険制度としてまかなっていく上では。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう１度お伺いしたいのが、それは加入者にとって不利益になるのかならないのかだけちょっと教えてほしいと求めました。毎年出している冊子を見ても、そういう加入者の方々の所得実態がわかるデータが全くないので、それをもう一度お伺いします。","respondent":"本城国保医療年金課長","answer":"特別区のほうとしては、相互共済的な国民健康保険制度をみんなで支える意味の支援を少しでもするという視点からの運営を今までもしてきたところです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういうルールで国庫支出金が支出されて、残りの基礎総額で保険料にするわけですから、もうちょっとわかるようにご説明ほしいと求めました。そうした収納率と国庫支出金の金額の関連などはあるのかどうか、お伺いします。","respondent":"本城国保医療年金課長","answer":"具体的には３４％相当額が国民健康保険財政に入ってくるということで、定率的な負担になっているものです。そして、いわゆる法定の繰入金と、その他財源不足額を補うという意味での一般会計のその他繰入金ということで分かれた運用がされているところです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"今は８ページの資料を提示する限りですというお話だったんですが、加入者所得の世帯所得の状況をつかんでおられるのかどうかお伺いします。今後でもいいんですが、それを提示していただくことはぜひお願いしたいと思いますがいかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"１,９００から２,５００を引いた約６００世帯がこの制度の関係で影響がある世帯ということになってくると推測されるところです。今、当然保険料を賦課するときのデータとしては所得状況を踏まえて賦課するですので、何らかの形では所得状況をご提示することは当然可能です。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問","question":"そんなに大きな幅の値上げなんですか」という、最近とったアンケートのことをちょっとだけ紹介したいと思います。未曽有の大不況と言われている中で、大本のところに問題点があると思うんですけれども、その辺をどう考えているのかまずお聞きいたします。","respondent":"本城国保医療年金課長","answer":"今医療制度の見直し、あるいは基盤強化に向けて、国全体の制度としてもいろいろな検討がなされているところです。財政基盤を支援するという意味で、あるいはこれも先ほど制度改正の中でご説明させていただいたところですが、２割に軽減措置を拡大するだとか。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"支え手が少なくなっていくとまた上がっていくという、今の国保は悪循環を繰り返して、このまま行ったら下がるということはないですよね。高い負担は認めながら、その後でどうなってきているのかというのが具体的にあったら教えていただきたいんですけれども、そういった中で区としては。","respondent":"木下健康福祉事業部長、須藤委員長","answer":"このような国の医療制度のあり方に関する検討が今されておりまして、財源問題も含めた国会段階での論議が必要だと考えています。という意味で… だから、所得の低い人のための国保という考え方ではないよね。皆保険制度のスタートになっているんだから。当初、自営業の方々とかが入っておられたわけですけれども、今、私が申し上げたのは実態面から。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問","question":"政管健保は７.４％、組合健保が５.１％。その辺の中身をどう言っていらっしゃるのかなというのもちょっと聞きたいし、いかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"これに限らず社会保障は高齢化の中で大変厳しい状況に置かれていますので、そういう点では国民的論議というのが必要だと考えています。特別区といたしましては、そういう国費の負担の強化という点については、そういう考え方を基本的に持っているです。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ここでそれを論じる場ではないわけですけれども、だからきちんと地方自治体としても求めていく姿勢を貫いていっていただきたい。ぜひ目を向けていただきたいなというところでは、実態を知って論議してほしいなと思うところでは、ぜひ自治体で調査をすべきであると私は思うんです。","respondent":"本城国保医療年金課長","answer":"国民皆保険ということで、当然医療の給付と保険料の賦課というのは表裏一体の関係ですことは、十分認識しています。適切に、十分円滑に医療サービスを利用していただくように、そういった面からも力を入れて対応しています。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問","question":"調査の件も伺いたいんですが、窓口１０割負担の資格証が１４２人でしたっけ、皆さんに使っていただくというのが大事であると思っています。生死にかかわる最悪のペナルティーだと思っているんですが、その点はいかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"そういった個別的なかかわりできめ細かく対応することによって、窓口を通じた実態把握に努めてまいりたいと考えているところです。制度趣旨から申しましても、少しでも窓口でかかわれる機会を増やすという趣旨であるということもあわせてご理解いただければと思います。","id":"exchange-015"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その辺とだぶっても手立てが行かないということなんでしょうか。保険証を渡しますよ」というようなアピールをしてほしいです。","respondent":"本城国保医療年金課長","answer":"この前、千数百人の保険証がお届けできていない世帯の半分、今手元に資料がないんですが、６割以上の方については転居先不明ということで、私たちが探そうと思ってもそれ以上探せないで戻ってきた方が過半を占めているということでご理解いただければと思います。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"提案","question":"例えば２３区の中でこの条例改正にどういうふうに対応しているのかというのは承知しているのかというのと、他の区の中で先に料率改正を先に提案して。この辺、品川区としてはどういうふうに考えて対応したのか、その考え方を教えくださいとの意見を述べました。","respondent":"本城国保医療年金課長","answer":"あるいは会期延長ということで行っていたり、あるいは区によっては専決処分という形でやっているところも幾つかあると聞いております。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"品川のやり方が一番確実なやり方だと思うんですけど、逆に数字的に、もし他の区での状況を、数をつかんでいたら、どういう状況をとったかという数をつかんでいたら教えてほしいなと思ったんですけど。","respondent":"本城国保医療年金課長","answer":"つかんでいる範囲ですが、半分ちょっとぐらいの自治体が会期延長、あるいは臨時会ということで議会に正式に諮って議決をいただいた上での対応をとっていると聞いているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"率直にお伺いしたいのは、品川区としては現状の国保料について高いと思っているのかどうなのか。国保料についての認識を、改めて品川区はどう思っているのかお伺いしたいと思います。","respondent":"本城国保医療年金課長","answer":"先ほどご説明させていただきました療養給付費等負担金というものについては、７割負担部分の簡単な定率で来ているものです。差し押さえの件数については、今現在で約７０件ほどで、主に預貯金だとかの差し押さえが主なものです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"差し押さえ、預貯金というのはその人の口座を差し押さえるということですか。保険証がなければ医療にかかれないわけですから、ぜひとも保険証の交付、医療の機会を保証するという観点を改めて意識していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この二つのやり方、この図のところのどこにどう入るのかというのを教えてほしいのと、それがこの基本の賦課総額に入ってくることなのか。一生懸命考えているんですが、ここがよくわからないので説明を求めました。","respondent":"本城国保医療年金課長","answer":"２３区は特別に統一保険料方式というものでとっているので、政令に定めるルールとは、この表とは逐一対応できているわけではありません。ですから、平成２２年度に来る見込みなのが５０億円で、それは精算額を引いた後の５０億円という形でご理解いただければと思います。","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問","question":"それは難しいことなんでしょうか。だからどこに入って保険料に響いてくるのかというのが今までの説明、何回も伺っているんですけどわからないんですね。","respondent":"本城国保医療年金課長","answer":"制度発足のときにどのぐらいの前期高齢者交付金が来るかなかなか見込めなかったところ、平成２０年度、平成２１年度と多く見込んでいたので。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"確認","question":"緩和はされたけれども、前期高齢者の交付金の部分が保険料に響いているということは確かですよね。その辺だけ確認させてください。","respondent":"本城国保医療年金課長","answer":"その２分の１というのは、本来だったら精算分を全額保険料に転嫁するというのが仕組みであるところ、激変緩和的な意味で半分については一般財源から入れるというものを、統一保険料を決めるときに検討した結果だです。","id":"exchange-023"},{"speaker":"金野委員","kind":"確認","question":"１点だけ事務的なことを確認します。毎年改正をする中でこれまではどのような周知をする、また問い合わせ等、こういう窓口の状況はどうだったのか説明を求めました。","respondent":"本城国保医療年金課長","answer":"そうすると、連絡先とかを中に書きますので、ほんとうに全課体制で電話等の応対に当たるような状況です。そのようなたくさんの電話に対して、課を挙げてできる限り細かく対応させていただいているところです。","id":"exchange-024"},{"speaker":"金野委員","kind":"質問","question":"先ほどのパンフレット等、お渡しをしてくださるということですが、ぜひわかりやすく表現をした配布物等お願いしたいと思います。そこら辺わかりやすく、当然そういうことも考えていらっしゃると思いますけれども、その点いかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"区民の方の目から見てわかりやすいかどうか、チェックしながら少しずつでもレベルアップし、わかりやすいものにしていくように取り組んでいるところです。","id":"exchange-025"},{"speaker":"金野委員","kind":"質問・要望","question":"それで、窓口等も電話等の問い合わせに対してという体制も聞きましたので、より厚くというんでしょうか、対応をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"政令に伴う改定などには２割減額の新たな創設など評価できる点も含まれているわけですけれども、今、しかも国保料だけではないわけですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２３区の中ではどういう状況でこの改正が行われているかということを確認しましたが、日本全国の自治体で同じ状況が起こっていると思います。こういった形のものに対して、先ほど来から区として要望しているということはありますけど、今回の議案には賛成していくということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問・要望","question":"私どもも申し上げましたとおり、国にこの事務手続きの早急さといいますか、これをご意見申し上げていただきたいことと、金野委員から要望がありました、周知に関しましては丁寧にお願いしたいことを要望して賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田委員","kind":"質問・要望","question":"期間が国のせいで短くなってしまったというのがありますが、できる限り周知のほう、よろしくお願いいたします。要望させていただきまして、私ども民主品川も賛成とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":28681,"voices":70}},{"id":"h22-20100413-6","meetingId":"h22-cm04","date":"2010年4月13日","dateIso":"2010-04-13","committee":"区民委員会","time":"午後１時０２分～午後２時５２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"番、報告事項","agenda":"番、報告事項","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"今、なぜこの時期になって、何か町会での会計でトラブルか何か事例があったんでしょうか。長いいろいろな背景があって、何かそういうトラブルがあって、適正化を図っていかなくてはいけないという方向性があったんか尋ねました。","respondent":"中山地域活動課長","answer":"１つは活動そのものが、１つはＰＲというものにさまざま力を入れてきたということで、パンフレットをつくったりしてまいりました。やはり集合型ですと一般的な話が中心になりますので、この会計塾を考える中で個別の支援を考えてきたということで。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"あれはどれぐらいの町会の方が会計としてお見えになりました。もし、わかれば教えていただけますか。","respondent":"中山地域活動課長","answer":"それから各地区で行ったミニ町会塾につきましては、２月に１回、３月に２回ということで、３会場で合計で約１２０人の参加がございました。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"税理士等を区に登録するということですが、これは税理士会、公認会計士の中から選ぶということなんですか。その辺、やりたい人が登録してやるんか尋ねました。","respondent":"中山地域活動課長","answer":"かなり町会活動全体についてもご認識のある方が、これはもう１つ町会から実際どれぐらいのニーズ、要望が正式に出てくるか。もう少し組織立った対応も考えなければいけないかとも思いますが、まずはそういう方々の中で、スケジューリングの中で当面対応できると考えています。","id":"exchange-003"},{"speaker":"松澤委員","kind":"意見","question":"お金のことは何ですけれども、これは１回２万円交通費を含むという、この根拠はどういうようなことでそれがなされているのか、ちょっと聞きたいんですけれどもとの意見を述べました。","respondent":"中山地域活動課長","answer":"それからある程度人数が多くなって、相当資料と準備を要するような場合には３万円というのが一定の目安になっております。ですから今回は、専門性とその時間を考えて、比較的小規模な講師派遣の１つの例ということで、２万円というのを設定しています。","id":"exchange-004"},{"speaker":"稲川委員","kind":"質問・要望","question":"質問というよりは、確認をちょっとしたいんですが、何か黄色い冊子がお手元にあるんでしょうか。定時総会を行うためのひな形みたいなものが載っていなかったと思うんですが、その辺について、２点お伺いします。","respondent":"中山地域活動課長","answer":"町会塾のご説明をしたときに、当日資料としてハンドブックをつくって配布予定ですということをご報告申し上げていたものが、そのときのものです。これはまだこの第１版のところ、それはなかなか再々印刷はできませんが、改正版のハンドブックにしたいと考えております。","id":"exchange-005"},{"speaker":"稲川委員","kind":"質問・要望","question":"総会に関してなぜ質問したかというと、いろいろ聞いていると、今までずっとやってきた総会です。これも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"三上委員","kind":"意見","question":"この町会・自治会といううち、自治会という会はどういうのを想定していますかとの意見を述べました。","respondent":"中山地域活動課長","answer":"ただ品川区の場合、自治会というのは基本的には集合住宅を想定して、品川区の場合は言い分けております。したがって比較的大規模な、単独でいわゆる地縁組織を形成すべき集合住宅に対しての組織を自治会というふうに考えています。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問","question":"そういったところについては、どういうふうに今後そういう参加をさせるのか。こういう現実について、やはり品川区としてはもうちょっと明確な、そこらあたりについてはどういうようにお考えになっているか尋ねました。","respondent":"中山地域活動課長","answer":"基本は集合住宅が入って１つの町会にしていくのが基本ですが、やはりこれは個別にその辺の、マンションの規模に応じた対応も必要かなと考えています。基本的にはまず町会に入っていただくというのは、これはきっちり各町会長にもご支援申し上げたいということでお伝えしています。","id":"exchange-008"},{"speaker":"三上委員","kind":"質問・要望","question":"区のそういったものが直接的に、ストレートにそのマンション内なんかでは伝わってくるということもあるわけですから、どういった方向性がいいのか。ぜひともそういった点での研究を進めていっていただきたいと願う次第ですけれども、どうか尋ねました。","respondent":"中山地域活動課長","answer":"研究・検討としてどういう形で、一定の柔軟性も持った支援、いずれにしても地域のコミュニティをしっかりとつくり上げていく観点からの支援というのを研究していきたいと考えていますので。","id":"exchange-009"},{"speaker":"南副委員長","kind":"確認","question":"でも、要請があれば派遣していくというふうな考え方を持っていいのかどうかちょっと確認したいと思うのが１つと、自治会というものの役割というのが。建築のほうは、全然別の組織ではなくて、改めてその辺の指導も含めてどういうふうになっているのかというのをちょっと確認しておきたいと思います。","respondent":"中山地域活動課長","answer":"管理組合そのものの会計の支援ではございませんので、そこでの会計上の支援ということがありますので、その範疇の中でのということでの考え方です。それをある意味で地域センターを通じて側面で支援していくのが地域活動課の役割ということになっておりますが、いずれにしても。","id":"exchange-010"},{"speaker":"南副委員長","kind":"質問","question":"品川区としてはそういう自治会なり、小規模なところも含めて、一定程度のいわゆる自治会組織というのはつかんでいるという認識でいいんでしょうか。ちょっとどの程度、どういうようにつかんでおられるのか、その辺を説明を求めました。","respondent":"中山地域活動課長","answer":"そういうものはどうかというのは、一義的には今のところ、まず組織的に区との協働の関係もお持ちの町会・自治会を基本に考えております。","id":"exchange-011"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういう点でいろいろと研究もしてほしいと求めましたし、必要な援助はやっていただきたいということで、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"今のご説明から伺うと、この図面の斜線を引いてあるところだけを地域センターとしては使う。あいている教室についてはどういうふうに考えていらっしゃいますか。","respondent":"中山地域活動課長","answer":"今、申し上げたこの左の部分と体育館以外については、基本的には閉鎖をしますので、解体まではそのままにしていくということで考えておるところです。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"そうすると、あいている期間中というのは、ほかの教室を使おうと思えば使えるという考え方をしてもいいわけか尋ねました。","respondent":"中山地域活動課長","answer":"いろいろな目配りもできませんし、ここから出入り口をもう１つ確保しまして、グラウンド用の受付を別途設けるつもりです。地元の利用も一定確保していこうと考えておりますので、それを一般利用となると、安全も確保しながら利用をこの間やっていこうです。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"そういうふうにして、やれるようなところというのが少しでもできたら、開放してもらえないかという要望はたくさんあるんです。この期間だけだって使わせてあげるということを考えてあげたっていいはずだ、というように思うわけですけれども、考えてもらいたい。","respondent":"中山地域活動課長","answer":"したがってこの間で言えば、ちょっと卓球台がどう調達できるかというのは少し検討しますが、例えばそこを使ってやることもできるかと考えています。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問・要望","question":"やはりいろいろ希望を聞いて、やはり可能な限りそれを使えるように、施設として開放してあげていっていただきたいなと思うんです。ぜひお願いしたと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"地域センターがここに来ると、この辺にまた入り口を設けて、地域センターに入る場合はそちらからということですか。こちらはあけて入れるようにしておいて、では、体育館へ入っていくのはこうで、地域センターはこうでと、そんな具体的には決まっていないのか。","respondent":"中山地域活動課長","answer":"要は選挙みたいですけれども、ずっと校庭から入って、校庭を横断する形で入っていく形も確保していきたいと考えております。ただ、ちょっと案内とか混乱のないように、幾つかの動線で地域センターのほうにはたどり着けるようには考えております。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"このスケジュールで見ますと、これは当然管理人を置いてということですから、スポレクの調整会議にのったときに来てもらえる。一番心配なのが、平成２３年の５月から８月の既存の建物の解体工事と出ているんですが、この間は一切使えなくなるんか尋ねました。","respondent":"中山地域活動課長","answer":"校舎を改修している間については、これは工事車両等が入りますので、利用ができなくなります。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"平成２２年の９月から学校が使えないんですか。９月からもう体育館もグラウンドも使えなくなるんか尋ねました。","respondent":"中山地域活動課長","answer":"いずれにしても工事が始まるまでの間につきましては、逆に学校が出て、これは学校が移転すると同時にすべてきれいに使えるかというのは、若干教育委員会との調整がありますが、いずれにしても学校施設として出た後、工事の始まる間については、地域利用が可能になってまいります。","id":"exchange-019"},{"speaker":"南副委員長","kind":"質問","question":"荏原第三地域センターそのものは、戻ってきたときにどのくらいの広さが広くなるのかとか、使い勝手が悪くなって改修するということなので、平面図がちょっとないので、どんなものになるのか全然わからないので、ちょっとその辺を説明を求めました。","respondent":"中山地域活動課長","answer":"これはまだ実施計画前ですからラフな話ですけれども、多目的に利用できるようなものにしていきたいということも考えているところです。全体のほうについては、まだこれは詳細設計を経ていないと答えられませんが、敷地の未利用の部分も有効活用していきたいと考えているわけです。","id":"exchange-020"},{"speaker":"南副委員長","kind":"質問・要望","question":"ですから今、たしかこちらのほうに公園みたいな感じでちょっと敷地が余っているというのか、あれは公園なんですか。その辺も含めて教えていただきたいんですけれども、そのあたりのことをもう少し詳しく教えてほしいと求めました。","respondent":"中山地域活動課長","answer":"敷地の位置づけで、実際従来から地域の人がちょっとした休めるスペースという形での公園的な利用がされているということはあります。少なくとも建築面積というのは３割から４割ぐらいは上げられると考えておりますので、いずれにしてもより有効活用して、よろしくお願いします。","id":"exchange-021"},{"speaker":"三上委員","kind":"意見","question":"これだけ広い敷地の中で、体育館のほうは全然別なわけでしょう。だから最初に体育館のほうの使い勝手についてどうするのかというのをやっておいて、ちょっと大幅に変更する必要があるのではないのかとの意見を述べました。","respondent":"中山地域活動課長","answer":"ただやはり一定機材を置いたり、それから車両が入ってくるということも考えると、グラウンドについてもかなり制約ができるのは現実です。これから施設担当のほうでもきちんと詰めてまいりますので、そういう中で、できる限り利用の可能性については探っていきたいと考えています。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"は全く質問とは関係ないんですが、受理状況とかに別にパーセンテージをつける必要性があるのかどうなのか。要するに１つの機種において充電関係、ランプの不良、操作というのはなくて、みんな１個１個問い合わせがあったということでいいわけですね。","respondent":"矢部生活安全担当課長","answer":"それとあと受理状況の関係ですけれども、推移ということで、これもパーセンテージを参照でつけたということでお示しさせていただきました。","id":"exchange-023"},{"speaker":"稲川委員","kind":"質問","question":"今後、やはりこういう機種ですから、いろいろな形で整備不良というのは出てくると思うんです。故障の多さとか、その上でそういうのを検討していくときが来るのではないかと思うんですけれども、その辺だけ簡単に。","respondent":"矢部生活安全担当課長","answer":"そこがいつも学校を回りまして手配とかをやっておりますので、専用窓口とかを防災センターに開設とかはなかなかちょっと難しいとは思うんですけれども、基本的には区内の近隣システム研究所で対応しているということです。","id":"exchange-024"},{"speaker":"渡部委員","kind":"意見","question":"いわゆる問い合わせではなくて、故障交換は結局何件ぐらいに今のところ上がったかというのはわかりますか。それと、窓口はいつまで、開設をソフトバンクのほうが責任を持ってやってくれるのかとの意見を述べました。","respondent":"矢部生活安全担当課長","answer":"バッテリー関係だと思うんですけれども、充電がやはりもたないということで、全体の１.４％が初期不良ということで判明しております。今、新入生の対応というところも当然持っていますので、私たちが必要がないと判断するまでは専用窓口はつくられている予定です。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"４月に入ってから新入生には当然配るわけですけれども、要は４月に入ってから新入生の問い合わせがあったんですか。わかっているなら説明を求めました。","respondent":"矢部生活安全担当課長","answer":"新入生に配った端末につきましては、メーカーのほうで配る前にすべて基本検査をもう１度やらせております。それとあと、発報テストのほうを実施しまして、一応それの基本動作は異常がないということを確認した上で新入生には配付いたしました。","id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"これは前に報告があったときも伺ったと思うんですけれども、ソフトバンクの契約についての後の詰めというのは何かやったんですか。相手との交渉を。","respondent":"矢部生活安全担当課長","answer":"今はとりあえず対応策といたしまして、あとソフトバンクの社員１名を常駐させまして、そこでも対応させているところです。そのほかの対応といたしましては、学校に回収だとかも行わせております。","id":"exchange-027"},{"speaker":"三上委員","kind":"意見","question":"それは現実に問題が生じた場合に、要するに契約上ソフトバンクがこれだけの不良品をつくって持ち込んでいるという、それに対してのペナルティーです。それについての何か交渉というのはしているのかどうかということの意見を述べました。","respondent":"矢部生活安全担当課長","answer":"今、充電ができない、要は充電がすぐに切れてしまうという状態を調査をかけているところで、根本的な原因が現在までわかっていないという状態です。もう１回調査をかけていかなければならないんですけれども、何らかの判定なり、または指摘なりをしていきたいと考えております。","id":"exchange-028"},{"speaker":"三上委員","kind":"意見","question":"そこらあたりは、やはりきちんとやっておいたほうがいいと思うんです。この案件だけではなくていろいろなことがあると思いますから、そういった点ではよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"これで案内なわけですか。改めて来てくれというようなお話があるのか。","respondent":"矢部生活安全担当課長","answer":"これで終わりです。申しわけございません。","id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"これは設立記念期間が２０１１年３月末まで入会金無料と書いてあるんですけれども、これが過ぎたら入会金とるんですか。それだけ。","respondent":"堀越文化スポーツ振興課長","answer":"２０１０年度については入会金を、入会金は３,０００円なんですけれども、やっていると聞いています。これは３月までの段階でのチラシでございましたので、この前、また地域の中でお願いして周知を図っていきたいと考えていると聞いています。","id":"exchange-031"},{"speaker":"渡辺委員","kind":"確認","question":"確認で聞きますが、その点を伺いたいのが１点と、これまでの準備期間にも相当な労力があったと思います。継続性の大変さという中で、情熱的な方がやらないといけないと思うんですが、どのような構成になっているのか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"ですからこのスポレク１つをとっても、品川型の地域スポーツクラブがこうなんだというような考え方も１つにはありました。事務局については、そういった意味では、立ち上げ期としては非常に順調に滑り出しを図ることができたのではないかなと感じております。","id":"exchange-032"},{"speaker":"渡辺委員","kind":"確認","question":"それがないという点の確認を１点と、もう１点はボランティアの自主運営、そういった側面支援は行政がするべきではないかなという気がしています。この辺の考え方を説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"この検討に当たっても質問として何回か議論のやりとりがあるところでございまして、結局サークルの活動を確保しつつ、不利益をこうむらない中で。","id":"exchange-033"},{"speaker":"南副委員長","kind":"質問・要望","question":"この個人の勧誘、今は５人だけれども、これを増やしていきたいという意味でこれを募集するということなのだろうか。この個人会員として参加はしたものの、それはそれとして自由の問題ですから、それをとりあえず教えてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"そういったことをお知らせしながら、一定の運営の定着と理念の周知が図れれば、個人会員についても増加を図れるのではないかと私も考えています。","id":"exchange-034"},{"speaker":"南副委員長","kind":"質問・要望","question":"安く場所を借りられるというところに本当に条件を充実させていく、整えていくということが求められているのではないかと思うんです。そういう方を自分たちでお願いするわけですから、親しみたいけれども親しめないみたいなのがあるというところではやはり逆行してしまうわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"これは品川・大崎地区という形になっていますけれども、そのほかに品川のほかの地域でも、こういった形のものというのはつくっていく予定でいらっしゃるのか、いかがなんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"品川・大崎地区の検討に当たってもいろいろな意見のやりとりがあって、かなり時間がかかったと思っています。ほかの地域で少し検討してみたいと、こういった部分の１つのツールとして使えるものであれば、この動きは広めていければと考えております。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"そういうようなことでも、仮に使用料的には１００円なり２００円なり払ったにしても、そういうようなところでやるというのは一番安全でやれる。なぜそういう個人に開放しないんですかということをずっと昔から言ってきたんだけれども、今、そこらあたりはどうなんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"先ほどご説明させていただいた施設の有効活用という観点で、人数が少ない状態でいつも場所を専有しているようなのが、今もままあります。今、そういった面でもクラブの魅力が高まるように工夫の１つとして、ご意見はお伝えしたいと思います。","id":"exchange-037"},{"speaker":"三上委員","kind":"質問・要望","question":"個人でやるスポーツというのもやはりあるわけですから。ぜひそういった点についても、やはり１つでも２つでもそういう形ででも拡大していっていただけるように、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"南副委員長","kind":"質問・要望","question":"その辺の状況がもしわかれば教えていただきたいのと、１年ぐらい置くべきではないかと思っていたし、改めてとりわけ聞いていないのだろうか。","respondent":"福島ものづくり・経営支援課長","answer":"その中で３月３１日現在では、実際に融資が行われましたのが２,９１１件で２２０億４,２００万円でございました。確かにそういう声もありますけれども、逆に借りている方を見ますと、今回につきましては融資と同じ程度にしたものです。","id":"exchange-039"},{"speaker":"南副委員長","kind":"質問・要望","question":"今、ものづくりのところで工場の調査をやっているというのが昨年度ありましたよね。わかった範囲でというのがもしあったら、いつごろまとまるのかということも含めて、ちょっと教えてほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"調査自体は３月中に終わっておりますので、今、それを業者のほうがまとめて、こちらのほうにすべて持ち込む予定です。５月の委員会で、できれば行いたいとは思うんですけれども。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":35610,"voices":118}},{"id":"h22-20100413-7","meetingId":"h22-cm04","date":"2010年4月13日","dateIso":"2010-04-13","committee":"厚生委員会","time":"午後１時０２分～午後２時５７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"に入ります。 (1)、都営大井林町アパート跡新高齢者住宅等の整備","agenda":"に入ります。 (1)、都営大井林町アパート跡新高齢者住宅等の整備","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"どういう所得の人が入れるのか、そうした入浴や食事サービスは、利用料金に含まれるのでしょうか。そこら辺を、お伺いします。","respondent":"冨岡高齢者福祉課長","answer":"利用料金等につきましては、今後、ちょっと検討をさせていただきたいと考えています。当然あるかと思いますけれども、今後の家賃の設定とかは、これから検討をして詰めさせていただきたいと考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとお話を伺うと、たしか３段階ぐらいに分かれていて、私は受け取ったんです。グレードのものを、従来型のシルバーピアの高齢者住宅でつくった場合の家賃というのは、どれぐらいになるのか教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"一定の期間、もう１回確認をしながら、どのぐらいかということで確定できるかと考えています。参考となる近傍の家賃という形で調べて、このぐらいだということで確定をして、ベースにして考えてまいりたいと思っているところであります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、そういう方たちも入れるような低廉な料金にしていただきたいと、私は強く要望したいと思います。ちょっと伺いたいんですが、土地の取得費と建設費、それぞれどれぐらいなんか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"それに対しまして、国の地域住宅交付金、これは昨年度の決算の部分ですけれども、４億７,０００万円ほどいただいたです、約４５％ですね。総工事費は１４億円ぐらいで、そのうち今年の部分が５億円、平成２３年度が９億円といった内容です。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"それから、先ほどちょっと質問したんですが、利用料金を設定するに当たっての考え方みたいなものがあれば、お伺いします。いつだったかの質問であったかもしれないんですが、改めて、お伺いします。","respondent":"冨岡高齢者福祉課長","answer":"ある程度の所得層の方が入れるように配慮して決めていくということで、今の段階では、そういうお答えをします。実施設計をやる中で、予算も考えまして、その中で効果的なものについては対応してまいりたいと思っているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"つまり、これのうちどれぐらいが補助金で、区の持ち出し、単独負担というのは幾らぐらいになるのか、お伺いします。こういう区でつくる施設というのは、そうしたいろいろなことができる絶好の機会だと思いますので、ぜひ積極的に導入していただきたいという要望です。","respondent":"冨岡高齢者福祉課長","answer":"すみません、ちょっと細かい数字は計算してございませんけれども、大体、交付金が２０％ぐらいで、区の負担か８０％ぐらいという割合で承知をしております。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問・要望","question":"どういう方が、住み替え住宅という形で入居されるのか、一つ伺いたいと思います。浴室がつくのかどうか、どういうことを考えているのか、その辺を、実施設計に向けた考え方で教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"例えば３階のところを見ていただくと、３８というところをちょっと見ていただきますと、ちょっと説明不足で申しわけございませんでした。個室で対応できる部分もありますけれども、個室で対応できなくなってくる部分については、２階のもうちょっと広いところを使う。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"何となくわかりました。と申しますと、この２階のおふろというのは、私も原小学校跡のこうほうえんに行ったことがあるんですが、あんな感じということでよろしいんですかね。","respondent":"冨岡高齢者福祉課長","answer":"はい、今のところは、個浴ということで考えているところです。１階にも、こちらのほうの利用をどう組み合わせていくかということで、考えてまいりたいと思っています。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問・要望","question":"下の介護施設に１００％入れるのかどうか、それとは別なのかどうか、その辺を聞かせていただきたい。こういう部屋は、考えられるかどうかについて、お伺いいたします。","respondent":"冨岡高齢者福祉課長","answer":"うまくそういうものも工夫できるかということで、ちょっとどうなるか、それについては検討してまいりたいと考えています。食堂の部分などはお使いになれる可能性があるのかなと考えておりますので、もう一度、検討してまいりたいです。","id":"exchange-008"},{"speaker":"山路委員","kind":"提案","question":"昔は、元気な方は別物で、全く別と考えるべきですか。柔軟に対応したらどうかと思うんですけれども、もう１度、説明を求めました。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"これはもうとても賄えないでしょうし、在宅の限界に来た方をどう支援していくかというところで、住宅系で対応することができないだろうかと。特別養護老人ホームとの関係、１階施設との関係では… １階部分については、ある程度、地域に開かれた施設を目指してまいりたいと思っているところです。ありませんけれども、その辺はなかなか、ちょっとそれについては検討をさせていただければと思います。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"ということは、１階のおふろなしのところに住まわれている人たちは、おふろに入るときには２階に行ってくれということなんですかね。そちらを利用してほしいということなのか、どういった、ちょっと説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"それから、小規模多機能型居宅介護のほうの利用ということになれば、こちらという形で対応していただくことを考えているところです。やはり区内部の関係各課に照会しまして、動線については、十分に考えてまいりたいと思っています。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"建ぺい率にしても、２００％のうち１６５％で、何でその程度に押さえてしまったのか。建築をそれだけ小さくしたのかどうか、その辺の影響が出ているのかどうか、まずその辺を説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"５階のところで、西側のところ２部屋ほど、一番上のところが使えないところで、これについては、日影の関係だと聞いております。それから、建物の窓先空地の部分を取ると、どうしてもここが目いっぱいの建設の部分だったと聞いております。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"玄関を入るとすぐに食堂ということなんでしょうか、ということが１点。スペース的なもので、ちょっと説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"運営をしていく中で、いろいろな問題があれば、場所的に考えて対応していけるかなとは思っております。それを考えると、全員ではありませんので、ある程度回せるのかなと考えているところです。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"確認","question":"自炊だとは思うんですけれども、ちょっと私は確認していないんですけれども、例えばさくら会も、基本的には自炊ですよね。そっちに進まないようにするには仕切っておいたほうがいいのではないかなという気が、私はしているんですけれども、その辺の考え方を説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"入り口にこういう印が出ているかと思いますけれども、違う空間ということで明らかに仕切りを入れていくところです。さくら会につきましては、原則、食事付で、不要な場合はお断りするというような流れでありますので、若干違うかと思います。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"だからつくるからいいのかなと考えたんですが、その辺で、そういう話というのはあまり聞いたことがないんですか。私は聞いているんですけれども、その辺の感覚はどうかなと、考え方をお願いします。","respondent":"冨岡高齢者福祉課長","answer":"そういうことを踏まえまして、今回、各部屋に必要かなという形でつけていったという経緯があります。今の部分も考えなければいけないんですが、その辺を考えますと、そういうふうに受けとめているところです。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"それから、訪問看護ステーションは、基本的にはここの方だけではなくて、周りのエリアも対応するわけですよね。この辺のエリアとしては、どのぐらいまで考えているのか、そこの考え方を説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"在宅介護支援センターは、基本的にはケアマネージャーの出動場所ということになるかと思います。うまくぶつからないような調整は、今後、出てくるのかなと理解しています。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"もう１点だけ、確認させてください。実際に、こんなに車が必要な施設なのかどうかという点が、私の考え方では、そんなに要らないのではないかと思ったのが１点です。","respondent":"冨岡高齢者福祉課長","answer":"住み替え住宅の場合を若干考えて、６０歳ぐらいでは、この台数ということで考えているところです。","id":"exchange-016"},{"speaker":"金野委員","kind":"質問","question":"３階の図面を見てください、１階のおふろがない部屋と、そこら辺はどうなんでしょうか。２点目には、これはすべり台になるんでしょうか、そのご説明をちょっとお願いしたい。","respondent":"冨岡高齢者福祉課長","answer":"今、やはり住みやすいということを目指しながら対応させていただきたいということで、話を進めてまいります。消防法上の問題とか、いろいろあるかなと、それで対応している部分があるかなと思います。","id":"exchange-017"},{"speaker":"金野委員","kind":"提案","question":"要望として、皆さんのご意見を網羅された使い勝手のいい部屋に、ぜひしてほしいと求めました。当然考えての設計をされていることだと思いますが、より誘導しやすいというんでしょうか、ちょっと提案をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"２階のおふろというところにおいて、そういう態勢になっているのかどうか、ちょっとそこを一つお伺いしたい。ここのところの基準がどのぐらいで、ここが実際にどれだけ確保されているのか、数字もわかったら説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"実施設計につきましては、これから説明会等がある部分で、実施設計を固めてまいりたいと思います。いずれの部屋につきましても、現在の高齢者住宅と同じぐらいの２５m2以上の広さは、今回、確保しています。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"高齢者ばかりの７０世帯、２０世帯というところにおいては、ちょっとその辺もぜひ充実をお願いしたいと思います。少しゆとりを高齢者に提供できるような、ちょっと環境に配慮されるような面もお願いしたいと思っていますが、いかがか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"ご指摘の点もあるかと思いますが、それについては、環境に配慮した検討はしてまいりたいと思っているところです。制約は、当然あろうかと思いますけれども、どれだけ配慮できるかということで、検討してまいりたいと考えています。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういったところは、どういうふうにしていくのか、指定管理者がしていくのでしょうか。特にこういったゆとりのスペースなんかの使い方もどうなのかなというところも、説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"少しでも皆で活動してほしいと、そういうきっかけづくりをしたいというのが、よろずやというところの趣旨です。それが活動クラブとか、そんなような形をイメージしておりまして、それをよろずやというふうに称していると思っていただければありがたいと思います。","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"補助金が出るみたいな説明があったんですが、この辺、ちょっと中身を説明していただきたい。それから、ほかにそういった面があるのか、ないのか含めて、ご説明をお願いします。","respondent":"冨岡高齢者福祉課長","answer":"これは国も進めているところですけれども、生活支援機能付の住宅という形で、これは東京都の制度です。その適用を受けるというところで、新しい制度です。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"意見","question":"２０２５年、ぜひ特別養護老人ホームをつくってほしいという声をたくさん出されていますので、お願いをして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、なかなか待っていても上がってこない状況を考えたときに、例えば２基にするというようなことは現実に無理なのかどうか。９０戸に１基というのは、ほんとうに適しているのかどうかというのは、その辺の考え方はどうか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"確かに、引きこもりはないほうがいいですけれども、エレベーターについては、当然２基にすると、建設費の問題等があります。それから、どれだけの方が頻繁に出られるかということも含めて、トータルで考えると、１基で何とかなるのではないかと考えているところです。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は必要という気がします。これからですから、まだ今の段階は、これから詰めていくんでしょうけれども、その辺、考えることはできないのかなという要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"山路委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですが、前にちょっとあったと思ったんですけれども、それは別ですか。各階に置くんですか、それとも全体で１人とか。","respondent":"冨岡高齢者福祉課長","answer":"各町会自治会でそれぞれ、さまざまな取り組みを進めていただきまして、ネットワーク化していく。管理人を１階に置いて、管理人の方は２４時間の態勢をとれると思いますので、しっかりとやっていただくという方針で臨みたいと思っています。","id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"確認したいんですが、自宅にはおふろがないわけですから、そこら辺がちょっとよくわからないんです。そういうことが可能なのかなと思って、驚いているというか、そこら辺がちょっとわからないので、説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"例えばお元気なときは２階のほうでできるかなと思っておりまして、こちらの１階のおふろは使えるという形で、使い分けができればいいと思っているところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"意見","question":"それとも、２５人の登録ではないんだけれども、そこでヘルプサービスを受けながらおふろに入れるということなのか。そこら辺が、ちょっと聞きたかったんですとの意見を述べました。","respondent":"冨岡高齢者福祉課長","answer":"それにつきましては、今、繰り返したとおりですが、場合によっては、１階の小規模多機能型居宅介護施設の個室の利用状況、うまく対応できるようにしていくことも可能だと思います。","id":"exchange-028"}]},{"id":"topic-02","title":"の住宅手当支給要件の緩和等","agenda":"の住宅手当支給要件の緩和等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"1)の計算式がちょっと複雑になっておりまして、この改正の意味というか、計算式の変更の意味するところを教えていただきたい。２回、３回とやっている方を誠実と言うのか、ちょっとお伺いします。","respondent":"平澤生活福祉課長","answer":"上限が出てまいりますので、家賃上限額の５万３,７００円の範囲でしたら、これは支給できるということになります。週１回以上応募していただければ、これは誠実に実施しているということで、９カ月までオーケーだです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"これまでの住宅手当がなぜ使い勝手が悪かったのかというのを、区としてはどのように考えているのか、ちょっとお伺いしたいと思います。昨年の１０月にスタートした制度なんですが、大体どれぐらいだったんでしょうか、お伺いします。","respondent":"平澤生活福祉課長","answer":"したがいまして、こういったものが整わないと、住宅がない方につきましては、なかなか難しいということがあります。この１０５人から６４人を引きました４０人強の数字につきましては、今後、よほどのことがない限り支給されるのではないかなと思っています。","id":"exchange-030"},{"speaker":"安藤委員","kind":"確認","question":"支給期間の延長ということだったのですが、受けている方が６カ月だったのは延びるということでいいのかということを、１点、確認したいと思います。意見を述べていくとか、そういう姿勢がおありなのかどうか、お伺いしたいと思います。","respondent":"須藤委員長、平澤生活福祉課長","answer":"今、住宅手当の支給要件の緩和の説明を受けているので、それ以上については、なかなか難しいところがあると思うので、答弁できる範囲でお願いします。 ３点にわたるお尋ねで、まず１点目、誠実に実行していただければ延長されます。そういったところに十分に着目しまして対応してまいりたいと考えています。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本の経済を健全な形に改善していくような声を挙げていってほしいと求めましたし、区の皆さんにも、ぜひそういう立場で意見を挙げていっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、５万４,０００円になったときに、上限は５万３,７００円と言われたけれども、家賃額が上限ではないんですか。ですから、この表でいくと、マイナスが増えていくと、家賃よりも出ちゃいますというのが、この表になると思うんです。","respondent":"平澤生活福祉課長","answer":"今回、ホームページにアップされましたところにつきましては、家賃上限ということは入れてあります。大変失礼いたしました。","id":"exchange-033"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２の就職活動要件の強化というところで、生活福祉課の面接支援、月２回以上、この中身は、どういう支援をされているのか教えていただきたい。そういった面で、ここの部分は、ハローワークの就職相談というのが、これは必ずクリアしなければいけない中身なのか、ちょっとそこも説明を求めました。","respondent":"平澤生活福祉課長","answer":"実際に月に２回、こんなことを言われたけれども、どう答えていいか迷ってしまったというような相談にも応じております。そういったところが面接支援、それから就労支援というところの大まかなところです。","id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"質問","question":"実施時期が４月１日からなんですが、これは、目処としてはいつぐらいまでを考えていらっしゃる制度なのか、説明を求めました。","respondent":"平澤生活福祉課長","answer":"こちらの事業全体につきましては、住宅手当緊急特別措置事業という、国の緊急雇用対策の事業でございまして、当初、設定が３年間です。したがいまして、平成２３年度末までは行われると聞いております。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"４月から、区が行っております、高齢者のひとり暮らしの緊急通報システムの利用料が減額になったという話をちょっと聞いたもので、その内容について、ご説明ほしいと求めましたが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":33292,"voices":109}},{"id":"h22-20100413-8","meetingId":"h22-cm04","date":"2010年4月13日","dateIso":"2010-04-13","committee":"建設委員会","time":"午後１時０２分～午後２時４１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"都営大井林町アパート跡新高齢者住宅等の整備","agenda":"都営大井林町アパート跡新高齢者住宅等の整備","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"これだと建ぺい率６０で容積率２００ということで、その辺の制度的なものを教えていただきたいのと、何らかの助成制度を使ってきたんだと思うんです。それ以外にここの建設に至るまでのところで制度として使っているものがあるのかどうかということと、その辺がどうなっているのか教えていただきたい。","respondent":"柏原住宅担当課長","answer":"建築費の総額は１４億円ほどだと聞いております。設計等につきまして、５億８,０００万円ほどかかるということ、平成２３年度は支出負担行為ということで９億円ほどの費用がかかるということです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"公的な部分で、規制がかかって建ぺい率が６０％ということなんですか。これは地域の一般的な数字なんだと思うんですけれども、どうしてわからなかったのか教えていただきたい。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"補助金についてですけれども、正確に申しますと、区の持ち出す費用の３分の１の４５％というように聞いております。ただ、細かい数値につきましてはこちらではまだ把握していない部分があるのですけれども… ほんのわずかですけれども、ただ現行の指定建ぺい率および容積率は６０の２００ですので、その基準が原則変わるものではございません。その範囲の中で計画されているという状況です。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"では、後でわかれば今の補助金等々の関係と区の持ち出し部分がどうなのかというのを教えてほしいと求めました。最後にもう一つ教えていただきたいのが、入居する希望者がこの２０戸に及ばなかった場合はどういうふうに取り扱っていくのか。","respondent":"柏原住宅担当課長","answer":"使用料金については、今考えておりますのは、単身用でご自身が負担していただくのが７万円から８万円ぐらい。それから世帯用では１０万円程度というように考えております。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、制度そのものがこれにどういうふうに関連してくるのか私もよくわかりませんけれども、今の話ですとしてしまうのですけれども。今のお話だと、あくまでも新しい高齢者住宅の設定で９０戸となっていてもちっとも不思議のない話だと思うんだけれども、その辺少し説明を求めました。","respondent":"柏原住宅担当課長","answer":"６０歳以上であるとか、区としましては、そういう施策の意味あいでこちらの２０戸を住み替え住宅ということで確保させていただいているです。施策的にこういう方たちもいらっしゃるというところです。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"そうすると、住み替え住宅として求めた方たちも高齢者住宅７０戸の方に入っていけるんだよということでいいんですか。そうすると、高齢者住宅の方の家賃はどうなるんだろうかというのも教えていただきたいです。","respondent":"柏原住宅担当課長","answer":"基本的にこの家賃の考え方なんですが、単身者のところですけれども、こちらは住み替え用は８戸で、単身用の高齢者住宅は７０戸となっています。基本的には同じスタイルのお部屋になっていますので、家賃的としましては同じになっているということです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"逆に２０戸埋まらなかったらこの高齢者住宅を望んだ方たちが入りますよというのは、どうもよくわからないですね。片方は空いていれば高齢者住宅に入りたいという人たちが入りますよというのは、そこがよくわからないとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"高齢者住宅につきましては、おそらく７０戸では足らないだろうという予想をしておりまして、かなり多くの方が来るであろうと考えております。７０戸の方もあふれてしまうということも考えられておりまして、２０戸を超えた場合は抽選等の形になってくるだろうと考えています。","id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"家賃変わりませんし、高優賃を使っての制度だと。どうしても行きついてしまうのが、どうしてわざわざ二つに分ける必要があったのかというのが、同じお答えになるかもしれませんがとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"まだ２年余裕がありますのでこの２年間募集をすれば、おおむねどれぐらいが希望されるかというのが、オープンするまでには固まってまいります。それでも埋まらない場合は、一般のまだ不足している高齢者の方々に高齢者住宅として使っていただける道は残しているです。","id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"まとまったものはもうちょっと先になるのかなと思いますが、それを９月というとちょっと心配なんですけれども、そういう考えでいいのか。その辺をお願いします。","respondent":"柏原住宅担当課長","answer":"その調査が７月、８月に終わりまして、９月ということでやっておりました。住み替え意向調査について、冊子として完成したのは１月とか２月とかという形になってしまったということでご了承いただければと考えています。","id":"exchange-008"},{"speaker":"武内委員","kind":"意見","question":"それは全く別で、あくまでこの住宅の管理ということでの指定管理者なのか。その辺の方向性はどういうことになっていますかとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"こちらの指定管理者という話ですと、長期医療とか介護とかを包含した形で、一括してということで話を聞いております。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"私の質問は、その２０戸についてはどういうふうにするのか。その３点をお願いします。","respondent":"柏原住宅担当課長","answer":"ただ、ある程度スパンを見ながらでないとできない部分がありますので、そこはある程度期間を見ておかなくてはいけないだろうと考えております。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"これは要望です。これは私の方で質問させていただいた趣旨としては、これは情報量の問題でしょうからあれなんですが、楽天なども品川区に来ていただいています。","respondent":"柏原住宅担当課長","answer":"一番下の3)実施・連携体制というところで、民間企業等々、こういったところはどういった形で我々と連携して事業を進められるかということで。今、委員からお話がありました民間業者等々についても積極的にお話を伺いながら行こうと思っています。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"それと、最後にご意見があればいただきたいんですけれども、なければ要望で終わります。その辺の感覚についてご意見があればほしいと求めました。","respondent":"柏原住宅担当課長","answer":"単身者向の２７m2ですけれども、２５m2という国の規定があるんですけれども、それを満たすということで２７m2です。内部で検討したときにいろいろ意見はあったんですけれども、２ＤＫを確保しながら、５０m2ということで決めさせていただいたです。","id":"exchange-012"},{"speaker":"高橋委員","kind":"質問","question":"地域の方々に対しての説明について、高齢者住宅というのはどういうものかという説明と工事に関する説明とを別々にやるのか、その時期がどれぐらいか。所管が違うかもしれませんけれども、もしおわかりでしたらお願いします。","respondent":"柏原住宅担当課長","answer":"地域の皆様方へのご説明ですけれども、今月末から来月半ばぐらいにかけて、地元住民の方たちに、こういった建物を建てますということでのご説明をするということで準備を進めているところです。","id":"exchange-013"},{"speaker":"阿部副委員長","kind":"質問","question":"そういう方はこういった住み替え住宅の対象に入ってこないんでしょうか。少なくとも八潮の方に提供するよりは優先度が高いと思うんですが、いかがお考えか尋ねました。","respondent":"柏原住宅担当課長、岩田都市環境事業部長","answer":"それから八潮の枠の話ですが、木造密集地区も含めた形での２０戸というように考えておりますので、全体ということで２０戸と考えております。木造住宅密集地域の住み替えのところというのは、一番喫緊の課題だと考えておりますので… 特に分譲の３ＤＫ、当時６３m2から６６m2が主体になっていますけれども、八潮を選んで社会的実験として行う施策です。","id":"exchange-014"},{"speaker":"阿部副委員長","kind":"質問","question":"そうすると、２年後に募集したときに、だれをどのぐらい入れるのかというバランスがとれなくなるんじゃないですかね。ある程度の目安というのは考えていらっしゃらないと、多分、募集や入居決定の運用ができないんじゃないかと思うんですが、いかがか尋ねました。","respondent":"岩田都市環境事業部長、柏原住宅担当課長","answer":"ただ、この２年間で募集しまして、例えば八潮で５戸しか申し込みが来なければ、残りの１５戸は木密用にするというのが、今のところの考えです。木密を３年か４年やってみて、木密事業が期限切れをしてしまえば一般の高齢者住宅に転用す… 先ほどの建築の補助金の数字ですけれども、本体工事は１４億円と申し上げたんですが、そのうち国からの地域住宅交付金がおよそ２億円来るであろうと見込んでいます。","id":"exchange-015"}]},{"id":"topic-02","title":"の平成２２年５月都営住宅（世帯向・単身者向住宅等）の募集","agenda":"の平成２２年５月都営住宅（世帯向・単身者向住宅等）の募集","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"年に何回か都営住宅の募集についての報告があるんですけれども、都営住宅の募集の申込書を見ましたら、裏に小さく事故物件の募集がありますよというのが書かれてあったんですけれども、いわゆる都営住宅の事故物件について説明していただけますかとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"７月中旬、１０月中旬ということで、年に３回ほどあります。実際は東京都に直接書類を提出していただいて、お申込みいただくという内容です。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"「こういう物件ですけど、いいですか」と言って募集をかければいい。その辺についていかがか尋ねました。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"例えば我々の窓口でご相談を受けたときに、一つの選択肢としてこういう募集も年何回かありますということはお話しさせていただいているところです。… 今、委員のお話にあったことももっともですので、東京都とも確認しながら、どのような説明の仕方がよかろうかということも含めて検討させていただければと思いますので、よろしくお願いします。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"確かに事故物件ですから、こだわる人はこだわると思うんですけれども、そんなこと言ってられないという方も結構いらっしゃると思うんですよ。わかっていなくて申し込まないのと、わかっているけどその物件に入りたくないと言って申し込まないのでは違うじゃないか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"委員のご意見を踏まえまして、その辺の対応の仕方を検討してまいりたいと思います。当然そういう情報を受けて、適切な情報をどういう形でお示ししようかというところについて検討してまいりたいと思います。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"今の藤原委員への説明の中で、都だからいいというのではなくて、当然ご承知おきだとは思いますけれども、宅建業法の重要事項説明、３５条とかはご存じだと思いますので、その辺を含めて東京都の方とお話し合いをしてくださいという要望です。","respondent":"伊藤委員長、柏原住宅担当課長","answer":"他になければ、これで本件を終了いたします。 既に４月１日から住宅リフォーム助成事業ということで実施しているものです。住宅・建築物耐震改修等支援事業、それと環境共生住宅事業等、こちらの方を実施した場合。","id":"exchange-019"}]},{"id":"topic-03","title":"の住宅リフォーム助成事業の実施","agenda":"の住宅リフォーム助成事業の実施","exchanges":[{"speaker":"原委員","kind":"質問","question":"区の考え方をお聞きしたいんですけれども、そうでなくて、逆に言うと何とか詐欺みたいな形のものが出るようなことも困ったものだなと。ですから、その辺のところについて区としての考え方を説明を求めました。","respondent":"柏原住宅担当課長","answer":"なるべく多くの事業者の方に導入いただければと考えていますが、一応こちらでは、事前に事業者ということで区に登録していただいております。必要な書類、資本の関係であるとか、そこに署名をしていただいた登録業者の方をご利用いただくというような形で進めております。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"ではその中で、その書類を出していただいたときの審査というか、チェック機能ですか、よくご存じのようにランクづけがありますよね。その辺について区としての方針があるのかないのか。","respondent":"柏原住宅担当課長","answer":"ランクづけというところでは特にこうだということはしていないのですが、区内業者というように限定しておりますので、区外の業者は外しております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"この施策だけではなくてもやってほしいというのは一般質問でも何回も言っているんですが、それについて教えてください。それと、助成金額が工事費の５％で上限が１０万円というのと、工事費の１０％で上限が２０万円という、この数字と金額を決めた根拠を説明を求めました。","respondent":"柏原住宅担当課長","answer":"件数を考えてみますと、助成金額の上限が１０万円、工事費用の５％ですので、一回の工事が最大２００万円規模の工事になります。耐震改修につきましては、これは事業として進めたいというところがありましたので、１０％で２０万円ということとさせていただいているところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"窓口のワンストップというのは絶対に考えていくべきだと思うので、あと、件数はどのぐらい見込んでいらっしゃるんでしょうか。これをやることによる経済効果というのもどのぐらい見込んでいるんか尋ねました。","respondent":"柏原住宅担当課長","answer":"そういうことで、こちらの上限が１０万円ということですので３００件として３,０００万円、最大でこのぐらいの金額だろうと見込んでおります。それが仮に３００件来たということになりますと、工事全体の金額としては６億円の経済効果が出るであろうというような見込みです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川区としてこの施策というのは、前段でも言いましたプレス発表でも大きな柱の一つですから、どんどん活用していただきたいと思うんです。その辺については、結局最後に聞いたときに「打ち上げましたけれども、件数が全然満たなかった」というのではしょうがないですからね。","respondent":"柏原住宅担当課長","answer":"もちろん区としましても一生懸命ＰＲを実施していきたいと思っておりまして、引き続きＰＲ活動を続けていくというように考えております。まだ始まって１週間、２週間というところですので、件数の推移を見ながら考えていきたいと考えています。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"それとも今、現実にこれまで区の仕事をしてこられた業者を対象にしているという話なのか、その辺教えてください。では、現状での登録業者は全体でどれぐらいいらっしゃるのかという数字はありますか。","respondent":"柏原住宅担当課長","answer":"現在のところ、１００件ほど既に登録しております。ですので、そこのＰＲを続けまして、随時登録は受け付けていくつもりでおりますので、今後増えてくるものと思います。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"建設４組合だとか、先ほど課長がおっしゃったいろいろな団体の総体としての業者の数は、実際どれぐらいあるんですか。これに該当するような業者です。","respondent":"柏原住宅担当課長","answer":"例えば建設業ということですと、平成１８年当時の事業所・企業統計を見ますと、品川区内には１,２５６社あるんですね。これはあくまで正確な数字ではなくて私の感覚的なところもあるんですが、５００社から８００社ぐらいはあるのではないかというように思っております。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"どういう形で登録業者を拡大するかというのは、かなり急がなくちゃならない話ではないかと思うんですね。今後、登録業者をどうやって増やしていくのかというのを、具体的なところでもう少し何かあるのであれば教えていただけますか。","respondent":"柏原住宅担当課長","answer":"この１００社だけでとまってしまいますとあれですので、随時、登録していただいて助成をすることになっているわけです。場合によっては広報紙であるとか、いろいろな手段を使いながら、事業者の方には周知していくというように思っております。","id":"exchange-027"},{"speaker":"阿部副委員長","kind":"質問","question":"例示があるほうが当然わかりやすいのでいいんですけれども、ここに書かれたものというのはあくまで例示であると考えていいんでしょうか。例示はできるだけ細かく書いてほしいなというのと、使う方に「もしかしたらこれもいいのかな、いかがか尋ねました。","respondent":"柏原住宅担当課長、伊藤委員長、藤橋都市整備下水道課長","answer":"こちらは例示ということになっております。増刷することになっておりますので、委員おっしゃるように、そういったところで表現を加えさせていただきたいと… 他になければ、これで本件を終了いたします。区といたしましては、詳細な設計を行い、平成２３年度から平成２４年度にかけて建物の解体および整備工事を行う予定です。","id":"exchange-028"}]},{"id":"topic-04","title":"の広域避難場所（仮称）国文学研究資料館跡地整備計画（案）に対するパブリックコメントの実施結果","agenda":"の広域避難場所（仮称）国文学研究資料館跡地整備計画（案）に対するパブリックコメントの実施結果","exchanges":[{"speaker":"武内委員","kind":"意見","question":"それともまだそういう考えまで検討していないのか。どんなふうになっていますかとの意見を述べました。","respondent":"中山防災課長","answer":"正式な話は聞いていませんけれども、今回の整備で、１,６００m2ぐらい増える予定になってあります。それから、広域避難場所については指定されてありますので、あとは避難人口の変更ということを東京都と協議していくです。","id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"どうしてもそれは品川区ですから、具体的な例を挙げて申しわけないけど、そこを確かめたほうがいいんではないかと。その辺はどうなんか尋ねました。","respondent":"中山防災課長","answer":"品川区では２本の指定避難路しかないんですけれども、その１本が滝王子通りということで、滝王子通りの拡幅を防災整備担当とやっているところです。","id":"exchange-030"},{"speaker":"阿部副委員長","kind":"質問","question":"このパブリックコメント、資料がなかなか丁寧にまとめられていていいなと思うんですが、これはご意見をお寄せいただいた方にはどのような形で返しているのか説明を求めました。","respondent":"藤橋都市整備下水道課長","answer":"本委員会に提出している段階では、直接回答はしておりませんが、今後、提出された意見については回答するとともに、ホームページでも、このような意見に対してこういう考え方ですというのを明らかにして、区民の皆様に広く周知することを考えています。","id":"exchange-031"},{"speaker":"阿部副委員長","kind":"質問","question":"今のは私がちょっと聞き逃してしまったかもしれない。お寄せいただいた方にも直接お返しするということでよろしいか尋ねました。","respondent":"藤橋都市整備下水道課長、伊藤委員長","answer":"そのように考えております。他になければ、これで本件を終了いたします。出水に伴い、出水をとめるための止水工事が約６カ月間程度必要と見込まれるため、下水道工事と公園復旧工事の予定が変更となる見込みです。","id":"exchange-032"}]},{"id":"topic-05","title":"の戸越幹線貯留管中流部整備工事（シールド工）の今後の予定","agenda":"の戸越幹線貯留管中流部整備工事（シールド工）の今後の予定","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"出水に関してですが、当たり前ですけど予測はされなかったと思うのですが、その出水に関して、水をとめる工事代がかかったと思うんですけれども、そのための工事に金額はどのぐらいかかるのかということと、これは全額品川区のお金でやるのか、その２点お願いしますとの意見を述べました。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる水をとめるための工事を行わなければいけませんので、概算の工事費用として恐らく１億円以上かかると見込んでおります。区という考え方ではなく、これらについてのことを見極めなければ、今のところはどこが負担するというのは申し上げる段階にはございません。","id":"exchange-033"},{"speaker":"阿部副委員長","kind":"質問","question":"今、出水原因の分析をされている最中ということですけれども、これはいつごろまでにまとまるか、大体の見通しというのはあるんでしょうか。それから地元説明会はいつごろを予定されていますか。","respondent":"藤橋都市整備下水道課長","answer":"浸水被害を軽減させたいと考えていますので、その辺を考えますと、できるだけ早い時期に結論を出して工事にかかりたいと考えています。今現在私の方で考えているのは、できればゴールデンウィーク前に地域の皆さん方に説明したいと考えています。","id":"exchange-034"},{"speaker":"阿部副委員長","kind":"質問","question":"ゴールデンウィーク前ということですね。分析結果というのもまた委員会へのご報告があるということでよろしいか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"次回の５月の建設委員会に間に合えば、その段階でご報告させていただきたいと思います。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3972#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":29944,"voices":116}},{"id":"h22-20100413-9","meetingId":"h22-cm04","date":"2010年4月13日","dateIso":"2010-04-13","committee":"文教委員会","time":"午後１時０２分～午後２時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"小学校では２４０名多い、顕著にあらわれるのは小学校のほうかなとは思いますけれども、この辺はどんなふうに見通していらっしゃるのか。そういう傾向もあらわれているのかどうか、どういった学校にあらわれているのか、今後の見通しをご説明いただけますかとの意見を述べました。","respondent":"富田学務課長","answer":"今後の入学者の動向ですが、住民基本台帳上の出生している人数は増加傾向にあるという状況です。学校選択制を行っておりますので、そういったところの動向とあわせて、今後分析をしてまいりたいと思っているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"学校で見るとどういうところの学校が特徴的なのか、先を見通したらこういう影響が予想されるとか、もし今見通しがあったら教えていただけますか。３月末時点で繰り上がりといいますか、最終的に抽選となって希望がかなわなかった学校というのはどこなのか、ご説明いただけますか。","respondent":"富田学務課長","answer":"中学校につきましては、抽選を行いましたのは３番の日野学園日野中学校と６番の伊藤学園伊藤中学校、１４番の戸越台中学校の３校です。このうち、中学校の抽選繰り上げの期限は２月末ですが、最終的に繰り上がらなかったのは伊藤学園伊藤中学校１校です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"日野学園と伊藤学園で伺いたいんですけれども、小中一貫校ですけれども、それぞれどのぐらいの数が入学されているのか。原小学校と伊藤中学校のように、どういう関係をつくりたいと思っていらっしゃるのか、その理念を教えてほしいと求めました。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"もう一つ、日野学園は開設が平成１８年度で毎年抽選は行っておりますが、私立等へ行かれて辞退する方を除き全員繰り上がっているのが多い傾向です。伊藤学園につきましては平成１９年度の開設ですが、毎年抽選を行っておりますが… 理念ですが、もちろんそのまま継続して一貫中学校に上がっていただくというのが、私どもの目指しています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう理念をお持ちなのか、ちょっと中身を教えていただきたいのと、伊藤学園の場合は今回繰り上がりができない子が生まれたと。そこの評価を伺えたらと思います。","respondent":"和氣小中一貫教育担当課長、富田学務課長、冠木指導課長","answer":"９年間を通じて子どもたちをしっかり育ててまいりたいと思ってありますので、もちろんそのまま上がっていただいて９年間継続した指導をしていきたい。… 施設等の事情から希望が集中したときに抽選という方法をとるのはやむを得ないことかと考えておりまして、公平な制度運営に努めているところです。荏原平塚学園の小学校は、今回１年生で学級規模縮小ということで校長先生がご判断されて、今回の配置ということになっております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それがどういうことなのかちょっと教えていただきたいのと、これはどういう教育効果をその校長先生はお考えになられているのか、ご説明いただけますか。","respondent":"冠木指導課長","answer":"小学校につきましては、まず早く学校生活に慣れていただきたいというところでの効果が大きいかなと思ってあります。その中で、それぞれの教科の学習においての効果は期待できると考えています。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"少人数学級を進めていただきたいと思うんですけれども、区のお考えはいかがかということです。私は一歩一歩少人数学級を広げていくべきだと思いますけれども、いかがか尋ねました。","respondent":"富田学務課長","answer":"２年生以上の４０人の学級があるわけですが、区といたしましてもこれに基づいて実施していくというふうに考えてあります。小学校につきましては小１、小２が対象になると聞いております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"そういうことなんでしょうか。今の説明を、もう一度ご説明いただけますか。","respondent":"富田学務課長","answer":"はい、委員がおっしゃるとおりです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした願いを区教委はどう受けとめているのか、どう思っているのか伺いたい。都や政府に対して少人数学級の実現をしっかり、予算措置も含めた実現を求めていくべきじゃないかと思うんですけれども、いかがか尋ねました。","respondent":"富田学務課長","answer":"学級編制基準は、東京都の基準にのっとり実施していくという考えに変わりはございません。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の法律はそうなっていますよという話は先ほどから充分伺っています。校長会、いろいろな場所にしても、しっかりと求めていく。","respondent":"富田学務課長","answer":"そのための方策として学級規模の縮小に活用する学校もあれば、ＴＴ等で活用する学校もあると、そういった対応をしているところもある。都の基準のもとに実施していかざるを得ない、そしてまいるです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"制度上の制約の話は今までも説明がありましたけれども、求めていくべきじゃないかと、区の主体性を聞いているんですね。その実現を、政府だったり都にしっかり主張していく必要があるんじゃないかと思うんですけれど、いかがか尋ねました。","respondent":"市川教育次長","answer":"この制度の中で、当然都に対しても国に対しても物は申してきていますし、またその方針に変わりはございません。学級編制の問題についても同様の考えでおります。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば伊藤学園だったら伊藤学園で小学部、中学部と行くのが普通だと思うんですが、その実態はどうなっているんでしょうかというのが１つ。それと、中学部になって特別支援学級という方もいらっしゃると思うんですが、その割合はどのぐらいなのか実態を知らせていただきたいんです。","respondent":"冠木指導課長","answer":"その割合ですけれども、小学校の通常学級から中学校の固定学級、特別支援学級に行くお子さんの割合は非常に少ない。就学相談のデータといたしましても、通常学級から中学校の固定学級というようなご相談は非常にまれであったという報告を受けているところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"どうも保護者の方たちの中に浸透していないのではないか、そこのところを、今後の特別支援教育のあり方をお聞きしたいということ。そういう傾向をどう考えられるのか、今後の特別支援教育についての一貫的な教育をどう考えるのか、お聞きしたいと思います。","respondent":"冠木指導課長","answer":"そのような中で、小学校と中学校が分離型であっても特別支援学級同士の交流をしている学校が、今。中学校になったときも親御さんが安心して特別支援学級を選択していただけるように進めてまいりたいと思ってあります。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"必要な教育は必要なところでちゃんとでき上がっているものですから、そこにアクセスできるようにしていただきたいと思っています。考慮点、特別な専門的な知識も必要になってくるだろうと思うんですけれども、その手当てはどうなっているんでしょうかというのが１つ。","respondent":"田村庶務課長、富田学務課長","answer":"すまいるスクールはご存じのとおり特別支援学級のお子さんも、あるいは特別支援学校に通われているお子さんも。それと特別支援のお子さんによっても程度がかなり、今のところそういう形で受け入れも行っていますし、対応しているです。小学校で言えば平塚小学校１校と、中学校で言えば２校だけでございましたので、この学校について調査を行ったということであります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"それは現場は先生は多いほうがいいですから、現場は非常に混乱するんじゃないかと思うんですが、どういうふうに対応していくんでしょうか。現場の混乱を考えるとちょっと心配なんですが、いかがか尋ねました。","respondent":"富田学務課長","answer":"３年間についての制度ということで決まっておりまして、３年実施する中でいろいろ検証等々をしていくというふうに聞いております。具体的に実施するに当たっては、私どもと各学校と連絡を密に行ってまいりましたので、そういったさまざまなご心配は必要ないかと。","id":"exchange-014"},{"speaker":"井上委員","kind":"確認","question":"一つ確認なんですが、小学校の特別支援のところで、今年の就学通知は最後はいつ出されているのかお伺いしたいと思います。それ以降何件で、一番最後の方はいつ出されたのか説明を求めました。","respondent":"冠木指導課長","answer":"中学生の場合はご自分の考えもありますから、これについて私どもの出す判断と保護者の方のお考えと、６割程度は合ってまいります。それで、数字ですけれども、前回の予算特別委員会でお答えした段階ではまだ２件決定しておりませんという回答をさせていただきました。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"その４割の方の相談事例で、ちょっと細かくてすみません、結果的に保護者の意向が反映されたケースなのか、教育委員会のほうが勧めたほうになったのか、その辺の内訳というか内容をお願いします。","respondent":"冠木指導課長","answer":"残りの１割の部分は、いろいろお考えいただいて私どもの助言を酌んでいただきながら判断を変えられたという事例です。この３年間、同じ傾向です。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"３月２０日に、やはりこれは保護者の立場で言うともっと早くちゃんと安心して次のステップに行くための準備をしたいというところがあるかと思います。「あ、ぜひ早目の対応をしていただきたいということを、ぜひそういったところは保護者側の立場に立って進めていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"浅野委員","kind":"確認","question":"１点お伺いしたいんですけれども、３９名の児童数で２学級ずつにして、それが１年たつと３年生になりますね。今回４０人だから１クラスになったのかなと単純に考えたんですけれど、一度確認をしておきたいなと思いました。","respondent":"富田学務課長","answer":"中学校の９年生になるとき、東京都に申請を行い、認められれば１年間に限り学級数を維持することが認められるという制度です。今年度につきましてはその適用申請に至る該当学級がございませんでしたので、結果として申請がないです。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"この件に関しては学校で特に手当てと言うんでしょうか、今度３年生で１クラスになったということで支援というんでしょうか、何か考えられているのか。そこのところだけお願いします。","respondent":"冠木指導課長","answer":"その学級が４０人で１クラスだからということではございませんけれども、そういった趣旨で区としての非常勤講師を配置したりというような制度を持っておりますので、そういうような形で対応しています。","id":"exchange-019"},{"speaker":"浅野委員","kind":"意見","question":"どうもありがとうありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"林副委員長","kind":"確認","question":"要するに、一応確認しますけれども、教育委員会は作為的に人数をこういうふうにしたということはないでしょうねというのが一つ。いわゆる小学校１年生に上がる子どもの数、それから７年生という中学１年生に上がる数、その数をもう一度教えてくれますか。","respondent":"富田学務課長","answer":"このうち区立小学校１学年の人数というのが２,１６６人です。区立中学校の入学者ですが、昨年１０月の住民基本台帳上の就学人口は２,０４４人、これに対して１年生の人数は１,４９０人です。","id":"exchange-021"},{"speaker":"林副委員長","kind":"質問","question":"そうすると、この表にあらわれてきた差、子どもたちの就学の人数というのは、教育改革を進めながら小中一貫教育を進めている品川区の教育委員会として、これは妥当な数字、妥当という言葉がいいのか、公立の責任自治体としてはどういうふうにとらえる数字なんか尋ねました。","respondent":"富田学務課長","answer":"希望選択がどういうふうに動いたのか等々といった増減の事由につきましては、今後分析をいたしますので、改めてこちらの文教委員会に報告させていただきたいと思います。","id":"exchange-022"},{"speaker":"林副委員長","kind":"質問","question":"とすると、あるいは私学側からの発表だと入学生が減っているというようなこともマスコミでは言われるが、そういうことはないんですか。呼び戻すというのはおかしいが、私学に行こうとする子どもたちを公立の学校にとどめるというような思いは、もうあきらめたんか尋ねました。","respondent":"富田学務課長、市川教育次長","answer":"従前より区立学校への入学率等々といったものは、品川区の場合、２３区の平均に近いような状況ではあります。そのような中で、先ほど申し上げましたように今後の学校ごとの分析等々をした上で… 私どもが教育改革に取り組むときの大きな問題意識として、区立の小中学校教育への支持、信頼の回復ということをうたってまいりました。","id":"exchange-023"},{"speaker":"林副委員長","kind":"意見","question":"この１年の数字を見てすぐどうのこうのという判断は非常に難しいんだけれども、選択制も経てきて、品川区教育委員会のある時点での検証。そういうことも含めて、ここでよそとは違う数字あるいは現象が出ているということを伝えてほしいなと思いますので、お願いをしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"区教委としてはどんなふうに考えていらっしゃるのか、どんなご努力をされているのか、ちょっとご説明ほしいと求めました。よくわからないので教えていただきたいのと、２人の非常勤の元校長先生と言ったらいいんでしょうか、ちょっとご説明いただけますか尋ねました。","respondent":"冠木指導課長","answer":"私どもも学校経営の継続性であるとか課題の解決の状況などを見まして、内申いたしまして、東京都側に話をしています。学校参与というのはその職を設置する小中学校、ぜひお力を発揮していただきたいという意味で、この職を設けたところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"この制度が始まった目的をもう１回伺いたいと思います。今までもよくわからなかったので、だれなのか、どんなふうに決まるのか、またどんな役割があるのか、ちょっと教えていただけますか。","respondent":"冠木指導課長、田村庶務課長","answer":"体力ともに十分で教員、その結果によって引き続きお力を発揮いただけるという方に、再任用の校長を引き受けていただいてあります。年数等につきましては、東京都全体の問題ですので私からコメントはできません。 聞いているところでは荏原第一中学校の校長が校長会の会長ということで、それぞれの校長会で互選で決めているということで、結果を聞いているです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、前任校のところに「東京都教育庁」と書いてある方がお二方ですかね。というのは、やはり新しい校長先生はそれなりの希望を持ったりとかしているものですから、参与という立場は非常に微妙ではないのかなと。","respondent":"冠木指導課長","answer":"それから学校参与が学校に入ってですけれども、考え方としましては、今度新しく入っていただく後任の校長先生には存分に力を発揮していただく。それから参与が今まで培ってこられたノウハウも十分に発揮して、さらによい学校にと、そういう意味であります。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"東京都教育委員会との関係もつながるのかなという思いもあるんですが、品川区にとってのメリットがあるのかどうかお聞きしたい。東京都の関係はもしもありましたら、それだけお聞きしたいと思います。","respondent":"冠木指導課長","answer":"今まで培ってこられたことを適宜品川区の特別支援教育をはじめとしてそういったところで、手腕を発揮していただきたい。なお、私どもが進めている小中一貫教育についても十分にご理解いただいて、お迎えしたところです。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"学校参与というものの目的があって今後どうされるのか、３年間の任期を終えられたお２人の先生が学校経営監として、たまたま今回の取り組みなのか。その辺を整理して、今後の見通しを含めてお聞きしたいと思います。","respondent":"冠木指導課長、市川教育次長","answer":"２人の学校経営監、第１期生ということで現在の形になってありますけれども、再任用等とは別に任命をしてまいりたいと考えております。学校参与はさらに特定の学校、そこの学校経営の継続性ということをぜひとも担保したいということでつくった職です。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"６５歳まで５年間ということで考えていいのか、その先はどういう議論をするのかということが、もう一つ命題になることです。議論の経過をちょっと説明してほしいと求めました。","respondent":"冠木指導課長","answer":"任期につきましては１年ですので、あくまでも実績等を考慮しまして、１年ごとの更新ということになります。それからこの学校参与の設置につきましては、さらに伸ばしていくかという視点での議論を積み重ねてまいりまして、今回の設置という経過になったです。","id":"exchange-030"},{"speaker":"井上委員","kind":"意見","question":"選考の基準というか、何をもってすぐれた実績というふうにしていくのかという、明文化されたものを教育委員会としてお持ちなのかどうか。そのところをお願いしますとの意見を述べました。","respondent":"冠木指導課長","answer":"学校参与に関しましては一般基準を教育委員会として決定いたしまして、それに基づいて選考したところです。「当該校の学校経営において特にすぐれた実績を挙げるなど、学校教育に関する豊富な知識と経験を有する者のうちから任命する」です。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを教えていただきたい。この荏原平塚学園の内容について伺いたいんですけれども、この荏原平塚学園ではどうなっていくのか、現状を教えていただけますか。","respondent":"和氣小中一貫教育担当課長","answer":"一貫校での活動はほかの学校と同様にさまざまな取り組みを行ってまいりますけれども、教科担任制も５年生からということで行ってまいる予定です。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"かなり準備会とかでいろいろ議論があったと思うんですけれども、入学式と運動会はどういう形になるのか教えていただきたい。最後に夏休みの水泳教室ですけれども、ここのプールは教育施設としての位置づけでしょうか、それとも一般施設としての位置づけか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"入学式ですが、４月７日に小中合同で行いました。今のところの予定としては平塚小学校の校庭で通常どおり運動会と、荏原平塚中学校のほうで運動会ということを予定していると聞いています。","id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"運動会は今年はそれぞれの校庭でやるということで、来年からは合同ということを考えていらっしゃるのか。今年と来年はまた違うのかご説明いただければと思うんですけれども、小学校６年生の卒業式の形は変わるのか、ご説明いただけますかとの意見を述べました。","respondent":"和氣小中一貫教育担当課長","answer":"ただ来年度の計画ですので、これからまた詰めていくことになります。具体的な形態についてはまだ聞いておりませんが、どちらも合同でやるというふうに今のところは聞いてあります。","id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"先ほどの説明では、合同というのは９年生との合同だということだと思いますが、やはりそういう仕方というのは問題があるなと思います。十分検討しながら、本当に見直しが必要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"新年度予算が始まったということで、緊急対策の一つだった待機児解消策について、４月を迎えたので現状はどうなのかお伺いしたいと思います。つまり、何人の方が認可保育園に申し込まれて、何人の方に内定が出たのか、状況を教えていただけますか尋ねました。","respondent":"吉岡保育課長","answer":"２次の申し込みに対する内定は１３９名ということで、４月１日現在で内定を持っていらっしゃる方というか、入園された方は１,２８６名です。なお４月１日現在は、その新しく入園された方も含めて、全部で４,９８１名の方が在籍をしているです。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"それと、以前の文教委員会で中延保育園と西品川保育園の分園についてのご説明がありましたけれども、改めて変更がないのかどうか。中延保育園と西品川保育園のそれぞれのクラスについての定員と、現在の在籍児童数をご報告いただけますか尋ねました。","respondent":"吉岡保育課長","answer":"学校施設を活用した分園の設置によりまして２６名の定員増をいたしまして、結果、平成２２年４月１日現在では１２６名というのが定員です。なお在籍の状況につきましては平成２２年４月１日現在、定員と同じく１２６名の方が在籍しております。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"西品川保育園の定員が、いろいろな結果で１４２名ということですか。それで、在籍が１３７名か尋ねました。","respondent":"吉岡保育課長","answer":"それから西品川保育園と中延保育園のそれぞれの５歳児の在籍数ですが、西品川保育園が２１名、中延保育園が１９名となっています。精査してございまして、例年どおり５月の文教委員会におきまして詳細を確定数値で報告しますときに、あわせてさせていただければと考えています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4696#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":27995,"voices":102}},{"id":"h22-20100413-5","meetingId":"h22-cm04","date":"2010年4月13日","dateIso":"2010-04-13","committee":"総務委員会","time":"午後１時０２分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"の品川区勢概要２０１０の発行","agenda":"の品川区勢概要２０１０の発行","exchanges":[{"speaker":"土井委員","kind":"意見","question":"したがってウェブのページ等々が、もっとある意味では検索のしやすい、必要な方はそれをさらに詳しく見ていくことが可能になる。感想と若干のお願いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"の区内企業との連携促進","agenda":"の区内企業との連携促進","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"伺いたいのは、社会貢献活動というのはどういうことをやるのか尋ねました。","respondent":"伊勢総務課長","answer":"一般的には、例えば企業の社会貢献活動ですと、企業の活動の本来のもの以外に、例えば環境問題だとか、あるいは地域の清掃だとか、そういう企業の営利活動とは別の次元の社会的責任を果たすという意味での活動を、社会貢献活動と言っております。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"品川区としてはどういうふうに考えているのかというのと、品川区の基本構想の理念に基づいて社会貢献活動を行うということなんですか。それとも、この品川区の基本構想の理念に基づいて連携を促進するということなのか、ちょっとこの文章ではよくわからないですね。","respondent":"伊勢総務課長","answer":"先ほど社会貢献活動の説明をいたしましたけれども、背景の中の２番目ですけれども、ここのところを社会貢献活動と言ってあります。この協働の中で、企業との連携だとかそういうところをやっていくということで、こういう形をとらせていただいています。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"ある意味では積極的な面もあるんだけれども、そうすると、ではどこで線を引くのかというのがよくわからないということが１つ。そこのところをもう１度伺いたいというのと、この説明だけだとちょっとよくわからないんですけれども、それをもう１度お願いします。","respondent":"伊勢総務課長","answer":"もうちょっと大がかりにやるだとかといった場合は、そういう意味では清掃ということでとらえれば社会貢献活動になる場合が当然あると思います。検討の場が必要だとか、今後（仮称）ＣＳＲ推進協議会を立ち上げて、その中で議論をして進めていきたいということです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"企業も求めているものだと思いますし、それに対して区が一緒にやりませんかという対応、姿勢はすごくいいのではないか。さまざまなことがあると思いますが、やはり積極的に連携して、品川区のために私はやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"すごくいい事例も出てくると思うんですけれども、そういったことというのは何かしらで表現というのか、示せないものかなと思うんですけれども。成果といったら全然おかしいかもしれないんですけれども、そういったものというのはどんなふうにイメージされているのか、教えていただければ。","respondent":"伊勢総務課長","answer":"そういう活動事例を積極的に載せていきたいと考えていますし、今回９つの事例ですけれども、これを改訂する中で新しい事例も紹介していきたいと考えています。","id":"exchange-006"},{"speaker":"山元委員","kind":"意見","question":"この下から２番目に「とくに社会貢献活動はしていない」というのが４分の１、２５％あるんですけれども、何かこれからアプローチしていこうとかというお考えはありますかとの意見を述べました。","respondent":"伊勢総務課長","answer":"やはり４分の１ほどこういう実態がありますので、しながわＣＳＲ推進協議会が立ち上がった段階で、これをあまりこういうところに関心がなかった企業、あるいは知らなかった企業についてもうまく周知していきたいと考えております。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問・要望","question":"ですからそういう皆さんこそ、何かやりたいなと思っていらっしゃる可能性が非常に大きい。ですから、活動内容の紹介であったりというのは、非常に重要なことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-03","title":"の商店街電線類地中化工事（戸越銀座地区）その３請負契約","agenda":"の商店街電線類地中化工事（戸越銀座地区）その３請負契約","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"そこのところを教えていただきたいのと、こちらも４０カ所、このボックスがかなり邪魔じゃないかという声がよく出るんです。そういう邪魔ではないかという声もあるんですけれども、何か配慮できるものなのかどうか、どうなんか尋ねました。","respondent":"阿部経理課長","answer":"全体計画につきましては平成２４年度末の終了を目指していると聞いてあります。小型トラフから普通の管に変えますので、その管を収納する横断桝というので、どうしてもこの数は必要だというふうに所管から聞いています。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、平成２４年度のときに景観、全体的な上の工事をする。わかればなんですけれども、そのボックス全体の大きさは大体どのぐらいになるのか、わかればとの意見を述べました。","respondent":"阿部経理課長","answer":"まず小型トラフというのが出てきますけれども、これについては横が４０cmで、縦が概寸で言いますと３０cm程度のものです。ちょっと具体的にどのぐらいの大きさかというのは、申しわけございませんが、小型トラフはそういう程度のものということしか承知していません。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"いわゆる道路のところにぽこっと置いてあるのがトラフということなんか尋ねました。","respondent":"阿部経理課長","answer":"今回は変圧器の話でしょうけれども、それは今、申し上げたように上の街路灯につけますので、外には出てきません。","id":"exchange-011"},{"speaker":"若林副委員長","kind":"質問・要望","question":"これが平成２２年の１１月８日の工期ということで、平成２４年末に向けて、路面とかはどういう状態で残るのかというのをひとつ確認したいと思います。その１、その２で何か改善すべきこと、反省すべきことがあれば教えていただきたい。","respondent":"阿部経理課長","answer":"その２につきましては、ここで説明しているような小型トラフの設置とか管路の設置とか、終了していると思います。それが平成２４年度までにすべての工事を終わるというふうに聞いてあります。","id":"exchange-012"},{"speaker":"若林副委員長","kind":"質問","question":"どこがその１、その２かというのは、私も歩いていて非常に工事が始まってからやはり思うんです。その３についてはそこら辺も含めて、その３はまた別な新たな工区になりますので、もうちょっと教えていただけますか。","respondent":"阿部経理課長","answer":"確かに工期の変更とか、通行する区民の方に迷惑をかけている、それは聞いてあります。ですからそういう点を踏まえて、所管のほうでは今回の工事を考えているのではないかと思っています。","id":"exchange-013"},{"speaker":"若林副委員長","kind":"意見","question":"わかりました。ぜひその１、その２の状況を踏まえてその３、歩行者の方が困るようなことにはならないような改善をぜひお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"箱型のほうがもちろん簡単で、それはやはりそういう技術的なものとか工期的なものとか、そういうことで箱形式で常識的につくるものなのですか。その辺、もしわかれば説明を求めました。","respondent":"阿部経理課長","answer":"申しわけございません。そこまではちょっとわかりませんけれども、一応これが東京都で施工する型、これが一般型と聞いています。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"途中でもそういう声が出てくるでしょうから、ぜひ続けていただきたいというのが１つと、特殊財源がいっぱいありますよね。一応、総務委員会でもありますので、その辺をちょっと聞かせていただきます。","respondent":"金子企画財政課長","answer":"それから東京都に関しては４分の１が入ります。国庫、東京都の補助関係は以上です。","id":"exchange-016"}]},{"id":"topic-04","title":"の商店街電線類地中化工事（戸越銀座地区）その４請負契約","agenda":"の商店街電線類地中化工事（戸越銀座地区）その４請負契約","exchanges":[{"speaker":"土井委員","kind":"質問","question":"こういうことなのでしょうか。掘るだけでもないしというところの、そういうノウハウを持ったところでないと、なかなかうまくいかないからこういう形になっているのか尋ねました。","respondent":"阿部経理課長","answer":"辞退で番号１のところはＮＩＰＰＯですけれども、その３を請け負ってございまして、もう技術者が配置できないということで辞退です。その結果応募者が多くなく、例えば今回のように３社、あるいは２社であるということになってしまったです。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"結局１社になったということなんですけれども、というのも、その入札の成立という要件というのはどういうふうになるのか。そこら辺の考え方ということについてちょっとの意見を述べました。","respondent":"阿部経理課長","answer":"３社が申し込みをして２社が辞退ということではありますけれども、例えばここの会社が辞退したということは知り得る状況にはございません。そういうのは一斉に開きますので、その時点で知り得る状況ではございませんで、今回も含めまして有効に成立しております。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"約２割ぐらい、単純に工事の面積というか、工事する場所が長くなっているわけです。ところが入札予定価格は２割多く提示はされていないんですが、何か特に、そういう基礎的なものが何か根拠があるんか尋ねました。","respondent":"阿部経理課長","answer":"ただ単純に２割長くなるから、例えば桝の数が２割多くなるかとか、積算基準に従って積算をした結果としてこういう形になるです。","id":"exchange-019"},{"speaker":"土井委員","kind":"意見","question":"ぜひその意味では人権週間ばかりでなくて、ふだんでもいろいろな形で啓蒙等ができるように、ぜひご配慮をお願いしたいなと考えています。そういう方がたくさんお見えいただいているので、よろしくお願いしたいという意味で、これも意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"９ページのところで同和問題を知っているかということで、これだけの回答で、この同和をどういうふうにしたら解決するか。ここのところはどういうふうに目標だとか、そこら辺の例えば数値的にはどういうふうに考えておられるのか、ちょっと伺いたいと思います。","respondent":"中山人権啓発課長","answer":"１０ページのほうをご覧いただきますと、心の中の意識というところで、自分の子どもの結婚相手であればどうかという形で聞かせていただいています。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"意見","question":"端的に言うとどういうことなのかというのがよくわからないんですけれども、正しい知識とはどんなものか、端的にちょっとの意見を述べました。","respondent":"中山人権啓発課長","answer":"歴史的にどういうふうな形で同和問題が生まれてきたか、そういう地区に対する差別があったかということを知ることだと思います。１つには、あとは人権啓発・社会同和教育講座ということで、文化スポーツ振興課のほうでも意識啓発に努めているところです。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"この同和問題は、特に今の説明でも具体的にどういうふうになったらこの同和問題というのが終結するのか。私は、もうこういうのはやめたほうがいいということを言っておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1850#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":19040,"voices":80}},{"id":"h22-20100414-14","meetingId":"h22-cm04","date":"2010年4月14日","dateIso":"2010-04-14","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"の区施設の活用に関することとしまして、橋梁長寿命化修繕計画","agenda":"の区施設の活用に関することとしまして、橋梁長寿命化修繕計画","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"橋自体に対してどうなっているんだろうというのは関心の高いところですし、もう一度もう少し説明していただきたいなというのが１点です。大ざっぱでいいんですけれども、そのマニュアルの内容をご紹介ほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"前の状況との対比ができないので、基本的にはこの要領に沿って今後も点検したいと考えております。もう１点は、維持管理する部門、都市環境事業部の道路公園課のほうで今後点検していくようなことを考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"道路公園課ということなんですか。この辺は具体的にどんな点検の作業が行われ担保されるんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"表面のクラックの数ですとか幅をもとにトータル的に劣化を予測することが現在の技術で可能ですので、今回、そのような方法とした次第です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは知識を持っていかないと、区の職員の側もじっくりと専門的に技能や知識を育てていけるような体制をぜひとってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"確認したいのは、通常橋として大丈夫なのかどうか。２６ページですか、維持管理サイクルの構築という説明がありましたけれども、点検業者から区にデータが来るという形になるんでしょうかね。","respondent":"藤橋都市整備下水道課長","answer":"例えば８ページ、９ページをご覧いただきたいんですけれども、これが品川区の橋梁の事例です。そから２点目の点検の結果から維持管理サイクルの構築に向けての点検のデータなんですけれども、それをシステムに入力していく形をとる予定です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"先ほど説明で目視でいろいろな研究を重ねていって大丈夫なんだとおっしゃいますけれども、本体に損傷がないというのがどうしてわかるのかな。中の鉄部が腐食をするということも多々あるわけで、本当に目視だけのチェックで区は大丈夫だという判断なのか、ちょっと伺いたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"先ほどのお話の中で、今申した予測という現在使われる技術の最高レベルのものでできる範囲で予測していきましょうというのが、今回の計画です。大規模な崩壊につながるようなことは今のところないというふうに考えています。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"５ページを見て、ちょっと素朴に感じたんですが、写真１は下にＪＲ、写真２は上にＪＲが通っていますよね。もしくは区道がかかっているということになるので区が主体になるんでしょうが、ＪＲからの協力というものはあるんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"国の中で昭和６３年になりますけれども、今回、工事を計画した側が負担するというようなものがあります。したがって、ＪＲが負担するということではなくて、この場合区がやるのであれば区の負担という形になります。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、今どういう割合でやっているんですかね。それとも、区は区でやっていて、両方でやっているという考え方でよろしいんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"この場合はＪＲは点検をしているわけではございません。管理者である区がすべて点検と費用を負担して行うという形になっております。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"今回、橋梁について保全型というふうに方向を転換されたわけですけれども、この考え方というのは橋梁だけなんでしょうか。それとも区が管理するさまざまな例えば建築物等々についても同じ考え方で今後進めていくということなのでしょうか、説明を求めました。","respondent":"日下部企画部長","answer":"５月、その本編について改めてご説明をする予定ですが、要するに何か修理が必要になった。それで対応しようということではなくて、あくまでも予防型で対応していく。","id":"exchange-008"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区民要望や社会情勢、やはり住民要望が高い、また認可保育園とかそういう要望も高いので。あわせて、やればいいというものではありませんから、しっかり理解を求めるその姿勢を品川区にも貫いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須藤委員","kind":"提案","question":"地域住民の要望だけでなく高齢者福祉施設等の全区的な施策というところに、「とともに区施策の活用についても」というのを加えてはどうかと思います。１つ、２つつくるというものも施策的にあろうかと思うので、提案をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"区施策で１つ、２つとかという建物も考えられてこようかと思うので、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろんみんなの要望でもあるし、地域の特徴もあるという意味なんでしょうかね。同じ品川区民の要望、保育園１つとっても、やはり保育園をつくってほしいという願いはみんなの願いであるわけです。","respondent":"宮崎委員長","answer":"ちょっと今、正副で意見を交わしたんですけれども、今の須藤委員のお話を、例えば全区的な施策への活用というものと、高齢者福祉施設等というのを入れかえたりすると、そのまま意味が通るかなと思ったんですけれども、どうでしょうか。","id":"exchange-012"},{"speaker":"須藤委員","kind":"意見","question":"そうしたときに、それは全区的にこう置きなさいというものではないので、運用の仕方が１つ生かせるのかなという。この表現だけだと、そういう特徴的なものが何かほしいよ、そういった表現を入れてもらえればいいんじゃないかなと思うんですとの意見を述べました。","respondent":"宮崎委員長","answer":"わかりました。ほかにないようでしたら、今のご意見はちょっとまた正副で調整させていただいて。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"私もこの文言どおりで十分であると思っています。全区的な課題ということですから、区内に中心部に１カ所きゅりあんを置くというのも全区的な課題であって、これで十分かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"ここでは地域住民の要望が１つ。区民全体、それを全区的と言うんですかね、そういうもののニーズ、要望が１つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"さっきちょっとあいまいでしたけれども、自分でもあいまいだったと思うんだけれども、このままでいいのかなというふうに思います。そもそもこの提案自体が議会として注文つけるものですから、ある意味では加えるというか、こうしてほしいという中身になると思うのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"高齢者福祉施設等というところの問題で、私はお話あれなのかなと感じていたんですが、例えば施設整備等とかという書きかえはできないんですか。その全区的な施策というものはここの文章の中では、そういうわけではないんか尋ねました。","respondent":"宮崎委員長","answer":"ですからもうちょっと正確にしていきたいとか、ちょっと抜けているものだとかというのがあれば、ちょっと補足していきたいというふうな思いがあるんですけれども。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"であれば、正副に一任していたわけですから、これで等ということで含まれていると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"言葉だけ残っていってしまうので、それがわかるようにしっかり表現しておかないと、このときの行革委員会は何を言ったんだと。きちんとそういうものも議会の要望として来ているよというのができるので、ぜひそういう方向をつくっておいて、もう少し砕いていったほうが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"私はやはりずばり特養ホームだとか、障害者の施設だとか認可保育園だとか、こういうものはぜひ盛り込んで欲しい。文面的にはこれでいいと思いますけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"川西委員","kind":"質問・要望","question":"１番目の利用時間の区分の見直し、委員会にずっと出ておりまして、どういうことだったかというのが記憶にないんですけれども。教えていただきたい。","respondent":"宮崎委員長","answer":"１時から４時半とかなっているのを、もうちょっと施設によって変えてもいいのではないか。りんし２１については、在宅介護支援センターに使うんだけれども、こんな文言に。","id":"exchange-021"},{"speaker":"川西委員","kind":"質問","question":"私も感じておりまして、５時までというのはできないものかどうかということを思っておりますので、そういうことを指していると理解していいですね。ここで質問すると申しわけないから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"川西委員","kind":"質問","question":"とても不自由を感じています。そのことを指しているんだなと思って質問しました。","respondent":"久保田行財政改革担当課長","answer":"前も委員会のほうでご説明したと思いますけれども、区民集会所については４時半まで、ご意見のほうは所管のほうに伝えていきたいとは考えております。ただ、そういったところも含めましてご意見は所管のほうに伝えてまいりたいと思います。","id":"exchange-023"}]},{"id":"topic-03","title":"を行います。 (1)の荏原平塚中学校跡地利用計画のスケジュールの変更","agenda":"を行います。 (1)の荏原平塚中学校跡地利用計画のスケジュールの変更","exchanges":[{"speaker":"川西委員長","kind":"質問・要望","question":"区民要望としてはいろいろなクラブ、教室のままで使えるものもあるのではないかということで、ぜひ企画のほうで考えてほしいと求めました。１つだけにしておきます。","respondent":"久保田行財政改革担当課長","answer":"現在考えているのは、校庭部分の活用とスポレクが使ってきたということもありますので、体育館のほうの活用を考えているということころです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元からの改善要望が強く寄せられているというところの文章を見ると、この要望というのは上がってきたものか。その経過をちょっと知りたいので説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"全員で１つの部屋に入れないので廊下のほうにはみ出たり、そういった形でかなり不便をしながら使っているということをよく聞いております。はやはり地域センターを利用される方からそういったような意見が寄せられているというふうに聞いております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、学校が新校舎に移転すると、教育財産から一般財産に変わることになるのでしょうか。それを教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"今、詳細は詰めているところですけれども、平成２２年度中はまずは教育財産のまま継続をしていきたいなというふうに考えております。平成２３年度以降、地域センターが移った後につきましてはまたちょっと検討はしなければいけないんですけれども。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"平成２４年度に多目的広場として整備とありますけれども、この建物はどういう計画を今考えていらっしゃるのか、教えていただきたい。荏原第二中学校ですと収容人数が現在７８８人で、避難場所として指定されているんですけれども、どういう計画なのか教えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"それと、多目的広場のほうですけれども、こちらは平成２０年度の行革委員会のほうでもご説明してきましたとおり。一貫校のほうの荏原平塚学園のほうで３町会分は取り入れることができるのではないかということで調整をしているというふうに聞いております。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問・要望","question":"確認も含めてなんですが、スポレク調整会議、今までの利用団体が使えるような仕組みはそのままにしておいてほしいと求めました。向こうも一応年間の事業計画等も立てていらっしゃるでしょうから、早目にしてほしいと求めましたが、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"それの所管をするのが文化スポーツ振興課になりますから、地域センターのかかわり等をどうしていこうかというところを含めまして検討しています。そういうご説明ですので、地元の地域の今使っている団体の方を中心に貸していきたいという方針は変わりございません。","id":"exchange-028"},{"speaker":"市川委員","kind":"質問","question":"地域センターに改修された後に、この地域センターはどこが入り口になるんでしょうか。どこから入っていくのか。","respondent":"久保田行財政改革担当課長","answer":"このあたりから入れるのではないかというふうに聞いております。費用の面でも効率的なところということも踏まえまして、今ある形の中で使い勝手をよくしていきたいというふうに考えております。","id":"exchange-029"},{"speaker":"市川委員","kind":"質問","question":"わかりました。それからもう１点、この移転をするという周知については、どういう方法で周知をされていくんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"これにつきましては、今週末ありますので、そちらのほうで改めてスケジュール等の説明をしていきたいというふうに考えております。ホームページを活用したり、あとは地域センター内にそういった張り紙をして、広く周知を図っていきたいというふうに考えているところです。","id":"exchange-030"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういったところというのは別に１回使ったから次もずっと使い続けなければいけないという要望は基本的に持っていなくて。このスケジュールだと別に１月から３月にしなくても、そういったことも検討できるのではないかと思うんですが、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明いたしましたように、現時点ではちょっと校舎の活用というのは考えていないというお答えをさせていただきましたけれども。","id":"exchange-031"},{"speaker":"若林委員","kind":"質問","question":"同じ流れになるかもしれませんが、地域センター仕様にまず改修が１月からというのは、もっと早くできないんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明しましたように、あともう１点、こういう工事期間の設定をさせていただいたです。","id":"exchange-032"},{"speaker":"若林委員","kind":"質問","question":"設計と工事、これは今給食室ですかね、網かけの部分というのは。そうすると、さっきのご答弁だと、給食関係の部屋だったかな。","respondent":"久保田行財政改革担当課長","answer":"給食室ではなくて特別学級か何かがあるあたりだというふうに聞いております。集会所を利用される方の不便がないような形での改修はしていきたいと考えておりまして、こういった工事の期間を設けさせていただいたです。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"それはもうそのとおりでして、影響を最小限にしていただきたいんですが、そんなにいっぱい工事に場所をとるんですかね。どうしても影響がこんなにあるから１月から３月にするというのならわかるんですが、ちょっと私、今ここで理解はできないというのが１つ。","respondent":"久保田行財政改革担当課長","answer":"多分使い勝手が悪いというところの話は第１、第２集会室ですけれども、５割から６割程度の年間利用率があるといったところです。ちょっと正確に何件ということはつかんでおりませんけれども、全体の形としてはそういうようなことを地域センターのほうからは伺っているです。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問","question":"要するに区政協力委員会等々の場でそういう広さ的に使い勝手が悪いというお話が出てきているぐらいですから、５月と９カ月校舎があいているのに、これはやってあげたらいいんじゃないかと思うんですけれども。","respondent":"日下部企画部長","answer":"さっきもご説明させていただきましたバリアフリーの問題から、これが、いろいろな条件をクリアしなければいけない。ただ、さっき申し上げましたように、その辺も含めてこれから地域の皆様方のご意見等も踏まえてしっかりと対応はしてまいりたいと考えております。","id":"exchange-035"}]},{"id":"topic-04","title":"の旧第一日野小学校跡地の活用","agenda":"の旧第一日野小学校跡地の活用","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"大変にお疲れさまでございました。そういう中で１点だけ、安全性とかそこら辺をどういうふうに確保されたかというのを１点確認だけさせてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"貸し出しにあたり、建物自体には機械警備がそのまま継続していますので、何かあれば警備会社が飛んでくるというふうになっております。さらに、幼稚園の園庭として使ってまいりますので、そういった中で安全性の確保を図っていきたいというふうに考えております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"ＴＯＣへの貸し付けが９月からということなんですが、貸し付け期間というのはどれぐらいになるのか、それを教えてください。少年野球とサッカーチームに８月まで貸し出すということなんですけれども、これからは９月以降、どこで活動されるのかお伺いします。","respondent":"久保田行財政改革担当課長","answer":"遅れている理由ですけれども、経済情勢というご説明をいたしましたけれども、計画のスタートの時期を見きわめているというふうに伺っておりますので。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"第一日野の移転のご協力ということは、具体的には費用経費の負担ということなのか、ちょっとお幾らぐらいなのか教えてください。昨今の経済状況というのが、まだちょっと説明としては私の中ではまだつながっていないんですが、もう少し具体的に説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"平成１７年度にもお答えいたしましたけれども、そういったところのご協力を調整をして今後具体的に決めていきたいというふうに思っているところです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明は受けていると思いますので、そういうことがあれば議会にも受けた説明の内容はきちんと報告してほしいと求めました。今の現在の例えば、この地域ではどんなスポーツ団体の需要というんですかね、どのようにこの地域の行政需要をつかんでいらっしゃるんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"地元の方々もそういうふうな認識を持っているというふうに伺っております。ＴＯＣのほうには３００を超えるテナントが入っておりますので、活性化を継続させていく上では非常に重要な存在であると認識しておりまして、今回。","id":"exchange-039"},{"speaker":"安藤委員","kind":"意見","question":"これから跡地の活用に向かって、スポーツだけに限らないと思うんですけれども、どういう需要があるのか、区としてさまざまな研究や調査を進めていって、ぜひそういったものを反映させていくようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを伺いたいと思います。それと、前の街づくり特別委員会でしょうか、たしかあのときの説明で、ここを駐車場にするというお話でしたでしょうか、変更がないのかどうか。","respondent":"久保田行財政改革担当課長","answer":"駐車場につきましてですけれども、土日の混雑解消という意味も込めてＴＯＣ側は借り受けをしたいというふうに聞いております。校舎等の解体というところもこれまでご説明してきたとおりの形で進めていくのかなというふうに思っておりますので、９月以後当面の間は。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"現実制約があるから一時的なんでしょうかね、どういう制約、どういう事情があるのか。要するに子どもたちが新しくできる第一日野から移動をするという、どういう姿になるのかがよくわからなかったので、そこを教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"ＴＯＣ側から建て替え計画があって、それで区としてもいろいろと総合的に検討させていただいて判断した結果、貸し出すというところに至っているです。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"幼稚園だけ始まって保育園は後からですか。そこの姿がちょっと正直よくわからなかったので、ご説明いただけますか。","respondent":"久保田行財政改革担当課長","answer":"済みません、改めましてご説明いたします。可能であれば外構工事が終わるまでの間、幼稚園自体はもう移っていますけれども、校庭として旧校庭だけを使いたいです。","id":"exchange-043"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、役所の中同士のことですから、これは要望だけしておきます。これは私、以前からずっとこれが平成１７年当時のことですけれども、平塚小学校の跡にできるような施設をずっと一般質問等で要望していました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問・要望","question":"８月の後ろに予定とあって、９月から予定とあって、ちょっとその辺の心証を教えていただきたい。お互いの利益になるようにやっていけばいいと思うんですけれども、ずっと待つんでしょうかね。","respondent":"久保田行財政改革担当課長","answer":"決して計画が遅れるということを見込んで予定が多いということではございませんので、今後気をつけていきたいと考えています。９月から借りたいということで調整しておりますので、その意味では時期が遅れるということはないというふうに考えているところです。","id":"exchange-045"},{"speaker":"阿部委員","kind":"質問・要望","question":"この部分は一応お考えを伺ってみます。こちらのほうもぜひ積極的に検討していただきたいんですが、この点についてもお考えを伺います。","respondent":"市岡総務部長、久保田行財政改革担当課長","answer":"それから、若干時期をずらしても当初の予定どおり借りたいという要望がありましたので、その調整の中で今出てきた利用計画をご説明している。そういうことですのでご理解をいただきたいと思います。今まで第一日野小学校が学校避難所だった町会で、端にあってちょっと遠いといったものを日野学園のほうに移したというふうに聞いております。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/438675?Template=document&Id=5880#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":36274,"voices":119}},{"id":"h22-20100415-15","meetingId":"h22-cm04","date":"2010年4月15日","dateIso":"2010-04-15","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"水辺とみどりの整備に関することとして、水辺とみどりの実態調査の結果","agenda":"水辺とみどりの整備に関することとして、水辺とみどりの実態調査の結果","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"７カ所、１３カ所ということで、実際どのような壁面緑化が施されているのか教えてほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"立会川、その辺も含んでおりますので、面積的にはそういったものがカウントの中には非常に多く出てきているという形のものです。樹種としてはやはりツタの仲間が２０カ所ほどこの中ではあったです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"今目黒川沿い、川沿いのということでお伺いしたいんですけど、荏原地区１４カ所、４１６m2ということで、荏原地区は川がないわけで、これは純然にビルの、ビルといいますか、建物の壁面の緑化ということでいいんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"今回はそういったものは除きまして、適切に管理しているものだけを拾っておりますので、委員今お話があったとおり純然たる壁面の緑化ということで行われている結果です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと基本的なところをまずお伺いしたいんですが、ちょっとそこの大もとのところを教えていただきたいのと、区の評価というのは今どういう評価になっているのか説明を求めました。","respondent":"藤田水とみどりの課長","answer":"今回は１.９ポイントの増ということで、そういった面では前回よりはもっとスピードが上がってきているのかなと思っています。私どもの施策として平成１１年、平成１６年、そういったものの効果もあるのかなというふうに考えているところです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この水面を加えたということは、そういう意図が含まれているのだろうなと思っているんですが、ちょっとその辺をもう一回お伺いしたいと思います。区が目指しているところと比べるとどうなのか、満足している増え方なのかどうか、ちょっとその辺も含めてもう一回お答えほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"まず私ども今現在の、目標的に持っていますのは、昭和５９年のころに４分の１緑化というような形での目標数値を挙げております。今回が２１.２％ということで、みどりを大切にしながらこの目標に近づけていければなというふうに考えているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"草地ですか、この辺というのは具体的にどういうところが増えてこの伸びになっているのかを教えていただきたいのと、ベース的にその地域の。その辺の差がどういうところなのかというあたりと、この辺の今後についてのお考えがあるのかどうかを説明を求めました。","respondent":"藤田水とみどりの課長","answer":"最後の工事がずっと進んだということで、樹木で覆われる部分の面積が随分増えてきているというような形になっているところです。私どもで均等に事業として割り振ってやっているとか、そういうことではございませんので、そういう中でそういう数が見られたという形のものです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実態ですからね、今の屋上緑化等も含めて、そういうような積極的なデータの使い方をしていっていただきたいなと思っているのが一つです。その辺をちょっと教えていただきたいのと、どういう対象というか、この５８名のところの根拠を教えてほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"それから、データを施策の中に生かしてほしいということですが、その辺は私どもももちろんそういうような形でやっていきたいと考えています。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"行動計画は、どんな内容なのか、何を目的につくるのか、いつごろつくる予定にしていらっしゃるのか、その辺を改めて教えていただきたいのが二つ目。さっき説明があったのかしら、あまりなかったような気がしたので、改めてちょっと伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"それから水辺の施策も今まで一定、そういう中で真に区民から求められているものを改めてちょっと認識をして、あるいは先ほど申した４分の１緑化。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"だから、区によってどこに政策の重点を置くかということで違っていると、そういうことでとらえていいのかなというのが一つ確認をしたいと思います。ちょっと改めてその辺を確認したいんですけども、これはだって、５８人の意見というのは横浜から千葉までの間のところの調査では。","respondent":"藤田水とみどりの課長","answer":"区内調査です。","id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"あっ、区内の調査なんですか。それにしても５８人というのは妥当だと思うけども、どういうふうなスタンスで進めていくのかというのをちょっともう一回確認したいと思います。","respondent":"藤田水とみどりの課長","answer":"それから、私どものほうで細かいお話はできませんが、みどりの施策を進めていく中ではまず実態を把握するということは大切だと私は考えてあります。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"最初のところの、予算特別委員会でちょっと質問したんですけど、やっぱり開発を進めるとＣＯ２もいっぱい出てきますよね。いいです、答弁は。","respondent":"岩田都市環境事業部長","answer":"短くお答えしますと、みどり担当の部局として努力しますよと言っているわけですけども、みどりを増やす施策はここの所管だけではないんですね。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"書いていないのか、ちょっとわからないけど、目立つほどに緑化はされていないという状況があるじゃないですか。ですから、いろんな部署で横並びでやっているというお話ですから、ぜひそういう意見も加えて検討していただきたいということを申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"前回の調査から伸びてきたのか教えていただきたいのと、そのお考えを教えていただきたいのと、どういったのがあったのか教えていただきたい。もう一つは、調査をして、この５年間でどのような、この調査によって生かされた部分があるのか、もしあったら幾つか教えてほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"実は新たな調査というご質問はありますが、平成１６年のときにやっていなかった調査でございまして、ちょっと比較ができないという状況にあります。５年間に生かされたものとしては、やはり大きな伸びを示したなということで、こういったものについては一定の評価をしています。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"どういった悩みがあるのかとか、どういったものが区として求められているのかという調査を、もしできたらしていただきたい。５年たったら、経済状況でそれはまだわからないわけですから、ちょっとそこだけ教えていただければなと思います。","respondent":"藤田水とみどりの課長","answer":"私ども施策をやる中で、やりっ放しで評価しないというのはいけないことだと考えています。そういった中では緊急雇用を施策の中でできたということで、これについては一定の私どもも評価をしています。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"接道部の現況、今ちょっとお話があったところなんですけれども、今回初めての調査というお話です。考え方で、その点をお伺いしたいのと、ちょっと具体的にどういうところがここに含まれているのかというところをちょっと教えていただきたい。","respondent":"藤田水とみどりの課長","answer":"建物と道路の間が例えば５０cmぐらいしかないというような場所については、そういった場所については緑化の可能性が低い場所としております。あるいは高さ３ｍ以上の擁壁、それについてはちょっと難しいだろうということで、それらについては除外しているものです。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問","question":"特に交通安全については多分いろんな基準を設けられて設置をしたときには安全対策みたいなものをやられていると思うんですけれども、そこら辺の関係は多分考慮されていると思いますけど、その点をお伺いしたいと思います。","respondent":"藤田水とみどりの課長","answer":"通常生け垣でないと何になっているのかなというふうに考えますと、塀になっているんだと思うんですね。それぞれのご理解の中で、私どもが指導するというよりかは、そういう中でそれぞれが工夫してやっていただけているのかなというふうに考えております。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういう安全の面も接道とかいろいろ見られるときにも一緒に見て、危険なところは整備するとかしていってほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"それぞれの環境についてあるいは人間が生きるために生かしていこうというみどりと水ということになるんだけども、そういう考えでいいんですか。川とか運河とか、この調査の結果を見ながら、私たちはそういうふうに理解をしておかないといけないのかな。","respondent":"藤田水とみどりの課長","answer":"先ほど申し上げた行動計画につなげて、今回の実態調査も、その中の基礎調査ということで位置づけているものです。品川区、活用を進めていくために区としてどういう策を今後打っていく必要があるのか、そういったものをはっきりさせていくために実態調査を行うです。","id":"exchange-017"},{"speaker":"林委員","kind":"質問・要望","question":"みどりはみどりとして増やしていく。例えばビオトープだっけ、人にとっていやされる、ぜひそういうところにも考えを及ぼしていただきたいなというのをお願いだけしておきます。","respondent":"山路委員長、工藤環境課長、柏原住宅担当課長","answer":"ほかにございませんか。ほかになければ、以上で特定事件調査を終了します。私のほうから温暖化対策事業（家庭への支援）につきまして、お手元の資料に基づきまして説明をいたします。こちらのほうは、まず私のほうで説明しまして… 私のほうから引き続きまして資料の２のほうのご説明をします。","id":"exchange-018"}]},{"id":"topic-02","title":"を行います。 温暖化対策事業（家庭への支援）","agenda":"を行います。 温暖化対策事業（家庭への支援）","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"三洋電機とか、それらほかの会社でも似たような製品があると推測しているんですけれども、確認はできません。なぜこのエコキュート、エコジョーズだけなんですかという素直な質問なんですけれども、確認いただけますか尋ねました。","respondent":"工藤環境課長","answer":"それぞれいろいろな電機会社が機器をつくってございまして、コロナとか、すべての電機会社がつくっている部分がこちらのほうに対応しているです。８社ぐらいつくっておりますけれども、大きな考え方としてはすべてのメーカーの中で機器の要件に入っていれば、一応該当になるです。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"確認はとれたんですけど、伝わっていますね、私が聞きたいことは。つまり、この指定した業者、指定したものだけじゃなくて、こちらに当てはまるものであればいいですよという確認、いいですよね。","respondent":"工藤環境課長","answer":"すみません、もう少し丁寧に、説明が足りませんでした。それぞれの、そういった部分では、すべてのメーカーが入ってくるというふうにご理解いただければと考えています。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういうことに対する対処をどうするのかということ。それから工事が１,５００万円とかありますけど、効果をどう測定していくのか、この辺をあわせてご答弁をお願いいたします。","respondent":"工藤環境課長","answer":"私どもがこの新規事業を実施するに当たりまして、積み重ねるとそんなに大きくはない数字だというふうに思っております。いずれにしましても、こういった私どもとしてもこのような機器の導入という部分を進めていきたいという思いから支援として立ち上げたところです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"そしたら、ぜひ区民に対する説明をするときに、そういう削減効果も具体的な数字として入れたらどうでしょうかね。じゃあ機器の開発とあわせて新しいマンション向けの機器ができた場合には、どう対処していくのかということの確認をお願いしたいと思います。","respondent":"工藤環境課長","answer":"私どももやはりホームページ等でＣＯ２の削減効果等を含めたような形でしっかりと説明してまいりたいというふうに考えております。今設置の場所としまして、もしくは玄関のところでも若干スペースがあれば設置可能ということになってありますので、そういった部分も含めまして。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひそういう角度で取り組んでいただきたいという、そんなようなニュースというか、番組だったんですね。ですから、その辺のところをどういうふうな歯どめをかけるのかというのをちょっと指導として考えておられるのか、それを伺いたいと思います。","respondent":"工藤環境課長、柏原住宅担当課長","answer":"私ども予算規模、件数をどのような考えで設定したかですけれど、他自治体２３区の中でも既にやっているところがあります。それぞれの地域で異なるかと思いますけれど、そういった部分で始めた、考えを決めたです。こちらのほうは中小事業者のほう、先ほどもありました悪意というのをなるべく排除しようということで、事前の登録制度をとらせていただいております。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"それは大賛成だし大いにやってほしいと求めましたが、ですから、ないように指導してほしいと求めました。金額的に８０万円が５件と、８０万円がいいかどうかというのはいろいろあるけど、これはちょっと個人的な意見として申し上げておいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この省エネのほうも環境共生住宅助成事業のところも抽選というところにおいてやはり大いに宣伝してほしいし、ぜひ１期と２期と分かれていますよね。その点が１点と、国と区の負担がどうなっているのかなというのを教えていただきたいのと、どの辺がどう拡大されているのかを説明を求めました。","respondent":"工藤環境課長、柏原住宅担当課長","answer":"現時点ではどうという部分はちょっとお答えできませんけれど、機器も少しずつ下がってくるというふうに言われています。補助額の考え方としましては、おおむね自己負担金の中で光熱費等を入れれば大体１０年で元が取れると… そういった件数等々を考えながらなるべく多くの方に利用していただこうというところを配慮しまして、今回１,５００万円で各期７５０万円と。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"今の分譲マンションのところに拡大というところにおいては、助成の割合とか額とかはどういうふうに変わっていくんか尋ねました。","respondent":"柏原住宅担当課長","answer":"基本的にはこちらの工事費の１０％、上限３０万円ということで、その部分と同じで考えております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ使い勝手のいいものにしていっていただきたいし、工事的には大きな工事とかにはならないんですかね。なかなか仕事がないというところにおいて、登録というところをくぐり抜けないとこの辺の助成は受けられないということなんでしょうか、もう一回。","respondent":"柏原住宅担当課長","answer":"正直なところ、ただ、３０万円は決して低い数字ではないというふうには考えているところです。今のところ１００件ほど登録いただいておりまして、都市計画課のほうにお問い合わせいただければ、登録はご案内するようにしております。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"申し込みはどこにどの段階で言うんでしょうか。申し込みができないとか、ちょっとその辺のタイミング的なことと、品川区のどこにまず伺えばいいのか説明を求めました。","respondent":"柏原住宅担当課長","answer":"こちらの環境共生住宅は、着工する前ということが基本になっておりますので、そちらのほう、着工前に、都市計画課住宅運営担当のほうまでお問い合わせいただければと考えています。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270609?Template=document&Id=6184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":29067,"voices":76}}]);
